INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d8abe6e-b38b-4777-9219-083db49583cb', '酬祕書王丞見寄', '酬祕书王丞见寄', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["相看頭白來城闕，却憶漳溪舊往還。","今體詩中偏出格，常參官裏每同班。","街西借宅多臨水，馬上逢人亦說山。","芸閣水曹雖最冷，與君長喜得身閑。"]', '["相看头白来城闕，却憶漳溪旧往還。","今體诗中偏出格，常參官裏每同班。","街西借宅多臨水，马上逢人亦说山。","芸閣水曹雖最冷，與君长喜得身闲。"]', '诗', 'shi', '', NULL, '酬祕書王丞見寄 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9cceace-2c0b-4a98-9532-fbca3d7dd057', '送李餘及第後歸蜀', '送李餘及第後归蜀', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["十年人詠好詩章，今日成名出舉場。","歸去唯將新誥牒，後來爭取舊衣裳。","山橋曉上芭蕉暗，水店晴看芋草黃。","鄉里親情相見日，一時攜酒賀高堂。"]', '["十年人詠好诗章，今日成名出舉場。","归去唯將新誥牒，後来爭取旧衣裳。","山橋晓上芭蕉暗，水店晴看芋草黄。","乡里親情相见日，一时携酒賀高堂。"]', '诗', 'shi', '', NULL, '送李餘及第後歸蜀 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2cfde83-58d0-4d9e-9783-61f9de80c42d', '早朝寄白舍人嚴郎中', '早朝寄白舍人嚴郎中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鼓聲初動未聞雞，羸馬街中踏凍泥。","燭暗有時衝石柱，雪深無處認沙堤。","常參班裏人猶少，待漏房前月欲西。","鳳闕星郎離去遠，閤門開日入還齊。"]', '["鼓声初动未闻雞，羸马街中踏凍泥。","燭暗有时衝石柱，雪深無处認沙堤。","常參班裏人猶少，待漏房前月欲西。","鳳闕星郎離去远，閤门开日入還齊。"]', '诗', 'shi', '', NULL, '早朝寄白舍人嚴郎中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df014f30-57b2-4a82-b2be-efa446d5f926', '書懷寄元郎中', '书懷寄元郎中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["轉覺人間無氣味，常因身外省因緣。","經過獨愛遊山客，計校唯求買藥錢。","重作學官閑盡日，一離江塢病多年。","吟君釣客詞中說，便欲南歸榜小船。"]', '["轉覺人间無氣味，常因身外省因緣。","經過独愛游山客，計校唯求買藥錢。","重作学官闲尽日，一離江塢病多年。","吟君釣客词中说，便欲南归榜小船。"]', '诗', 'shi', '', NULL, '書懷寄元郎中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('220398b6-508f-4148-bc38-7287f18faa67', '贈道士宜師', '贈道士宜師', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["自到王城得幾年，巴童蜀馬共隨緣。","兩朝侍從當時貴，五字聲名遠處傳。","舊住紅樓通內院，新承墨詔賜齋錢。","閑房暫喜居相近，還得陪師坐竹邊。"]', '["自到王城得幾年，巴童蜀马共隨緣。","兩朝侍從當时貴，五字声名远处傳。","旧住紅楼通內院，新承墨詔賜斋錢。","闲房暫喜居相近，還得陪師坐竹邊。"]', '诗', 'shi', '', NULL, '贈道士宜師 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c637b5-6125-4c59-9d66-1932b721ee82', '書懷寄王祕書', '书懷寄王祕书', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["白髮如今欲滿頭，從來百事盡應休。","祗於觸目須防病，不擬將心更養愁。","下藥遠求新熟酒，看山多上最高樓。","賴君同在京城住，每到花前免獨遊。"]', '["白髮如今欲满头，從来百事尽應休。","祗於觸目須防病，不擬將心更養愁。","下藥远求新熟酒，看山多上最高楼。","賴君同在京城住，每到花前免独游。"]', '诗', 'shi', '', NULL, '書懷寄王祕書 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64cd94af-cc46-46c4-83cd-c2e52706fdbc', '題韋郎中新亭', '題韋郎中新亭', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["起得幽亭景復新，碧莎地上更無塵。","琴書著盡猶嫌少，松竹栽多亦稱貧。","藥酒欲開期好客，朝衣暫脫見閑身。","成名同日官連署，此處經過有幾人。"]', '["起得幽亭景复新，碧莎地上更無塵。","琴书著尽猶嫌少，松竹栽多亦稱貧。","藥酒欲开期好客，朝衣暫脫见闲身。","成名同日官連署，此处經過有幾人。"]', '诗', 'shi', '', NULL, '題韋郎中新亭 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ef2d670-45a0-4c58-b23f-4fe45fcfb414', '送楊州判官', '送楊州判官', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["應得煙霞出俗心，茅山道士共追尋。","閑憐鶴貌偏能畫，暗辨桐聲自作琴。","長嘯每來松下坐，新詩堪向雪中吟。","征南幕裏多賓客，君獨相知最校深。"]', '["應得煙霞出俗心，茅山道士共追尋。","闲怜鹤貌偏能畫，暗辨桐声自作琴。","长嘯每来松下坐，新诗堪向雪中吟。","征南幕裏多賓客，君独相知最校深。"]', '诗', 'shi', '', NULL, '送楊州判官 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('247c812e-2db0-44ae-95b6-bfcb328016a8', '喜王起侍郎放牒', '喜王起侍郎放牒', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["東風節氣近清明，車馬爭來滿禁城。","二十八人初上牒，百千萬里盡傳名。","誰家不借花園看，在處多將酒器行。","共賀春司能鑒識，今年定合有公卿。"]', '["东风節氣近清明，车马爭来满禁城。","二十八人初上牒，百千万里尽傳名。","誰家不借花园看，在处多將酒器行。","共賀春司能鑒識，今年定合有公卿。"]', '诗', 'shi', '', NULL, '喜王起侍郎放牒 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14449c3d-09ec-494f-bd4c-7b5531cd38e4', '贈王司馬', '贈王司马', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["白笏朱衫年少時，久登班列會朝儀。","貯財不省關身用，行義唯愁被衆知。","藏得寶刀求主帶，調成駿馬乞人騎。","未曾相識多聞說，遙望長如白玉枝。"]', '["白笏朱衫年少时，久登班列會朝儀。","貯財不省关身用，行義唯愁被衆知。","藏得寶刀求主带，調成駿马乞人騎。","未曾相識多闻说，遙望长如白玉枝。"]', '诗', 'shi', '', NULL, '贈王司馬 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18a94893-e46a-4a0b-a892-934276cd8286', '書懷', '书懷', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["自小信成疎嬾性，人間事事總無功。","別從仙客求方法，時到僧家問苦空。","老大登朝如夢裏，貧窮作活似村中。","未能即便休官去，慚愧南山採藥翁。"]', '["自小信成疎嬾性，人间事事總無功。","別從仙客求方法，时到僧家问苦空。","老大登朝如梦裏，貧窮作活似村中。","未能即便休官去，慚愧南山採藥翁。"]', '诗', 'shi', '', NULL, '書懷 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea13a4d6-be49-40a4-bdf2-f82968727c3a', '贈令狐博士', '贈令狐博士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["頭白新年六十餘，近聞生計轉空虛。","久爲博士誰能識，自到長安賃舍居。","騎馬出隨尋寺客，呼兒散寫乞錢書。","古來賢哲皆如此，應是才高與衆疎。"]', '["头白新年六十餘，近闻生計轉空虛。","久爲博士誰能識，自到长安賃舍居。","騎马出隨尋寺客，呼兒散寫乞錢书。","古来賢哲皆如此，應是才高與衆疎。"]', '诗', 'shi', '', NULL, '贈令狐博士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9228894a-0c26-451a-8328-110d7fae7f42', '送從弟刪東歸', '送從弟刪东归', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["雲水東南兩月程，貪歸慶節馬蹄輕。","春橋欲醉攀花別，野路閑吟觸雨行。","詩價已高猶失意，禮司曾賞會成名。","舊山風月知應好，莫向秋時不到京。"]', '["云水东南兩月程，貪归慶節马蹄轻。","春橋欲醉攀花別，野路闲吟觸雨行。","诗價已高猶失意，禮司曾賞會成名。","旧山风月知應好，莫向秋时不到京。"]', '诗', 'shi', '', NULL, '送從弟刪東歸 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6d0c089-9c15-4895-95f8-0c334edbf3a3', '贈王祕書', '贈王祕书', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["早在山東聲價遠，曾將順策佐嫖姚。","賦來詩句無閑語，老去官班未在朝。","身屈祗聞詞客說，家貧多見野僧招。","獨從書閣歸時晚，春水渠邊看柳條。"]', '["早在山东声價远，曾將順策佐嫖姚。","賦来诗句無闲語，老去官班未在朝。","身屈祗闻词客说，家貧多见野僧招。","独從书閣归时晚，春水渠邊看柳條。"]', '诗', 'shi', '', NULL, '贈王祕書 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb81d8cb-2ad6-4b73-878c-cf146a785289', '哭丘長史', '哭丘长史', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["曾是先皇殿上臣，丹砂久服不成真。","常騎馬在嘶空櫪，自作書留別故人。","詩句徧傳天下口，朝衣偏送地中身。","最悲昨日同遊處，看却春風樹樹新。"]', '["曾是先皇殿上臣，丹砂久服不成真。","常騎马在嘶空櫪，自作书留別故人。","诗句徧傳天下口，朝衣偏送地中身。","最悲昨日同游处，看却春风樹樹新。"]', '诗', 'shi', '', NULL, '哭丘長史 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3d3d64e-76f0-4c7c-be55-9c9e61d8baac', '送枝江劉明府', '送枝江劉明府', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["老著青衫爲楚宰，平生志業有誰知。","家僮從去愁行遠，縣吏迎來怪到遲。","定訪玉泉幽院宿，應過碧澗早茶時。","向南漸漸雲山好，一路唯聞唱竹枝。"]', '["老著青衫爲楚宰，平生志業有誰知。","家僮從去愁行远，縣吏迎来怪到遲。","定訪玉泉幽院宿，應過碧澗早茶时。","向南漸漸云山好，一路唯闻唱竹枝。"]', '诗', 'shi', '', NULL, '送枝江劉明府 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77b0962f-1c31-4ff1-9f4c-2f90d4cd309c', '送從弟徹東歸', '送從弟徹东归', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["緱山領印知公奏，才稱同時盡不如。","奉使賀成登冊禮，陪班看出降恩書。","去迴在路秋塵裏，受詔辭歸曉漏初。","早晚得爲朝署拜，閑坊買宅作鄰居。"]', '["緱山領印知公奏，才稱同时尽不如。","奉使賀成登冊禮，陪班看出降恩书。","去迴在路秋塵裏，受詔辞归晓漏初。","早晚得爲朝署拜，闲坊買宅作鄰居。"]', '诗', 'shi', '', NULL, '送從弟徹東歸 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d7fc68f-be35-464b-b70a-06725f99238a', '哭胡十八遇', '哭胡十八遇', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["早得聲名年尚少，尋常志氣出風塵。","文場繼續成三代，家族輝華在一身。","幼子見生才滿月，選書知寫未呈人。","送君帳下衣裳白，數尺墳頭栢樹新。"]', '["早得声名年尚少，尋常志氣出风塵。","文場繼續成三代，家族輝华在一身。","幼子见生才满月，選书知寫未呈人。","送君帳下衣裳白，數尺墳头栢樹新。"]', '诗', 'shi', '', NULL, '哭胡十八遇 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33be17f8-f0b2-4c54-9d97-d4900b2c1f31', '贈賈島', '贈賈島', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["籬落荒涼僮僕飢，樂遊原上住多時。","蹇驢放飽騎將出，秋卷裝成寄與誰。","拄杖傍田尋野菜，封書乞米趂時炊。","姓名未上登科記，身屈惟應內史知。"]', '["籬落荒涼僮僕飢，乐游原上住多时。","蹇驢放飽騎將出，秋卷裝成寄與誰。","拄杖傍田尋野菜，封书乞米趂时炊。","姓名未上登科記，身屈惟應內史知。"]', '诗', 'shi', '', NULL, '贈賈島 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef40e90a-5774-4790-951d-06277b45033d', '逢王建有贈', '逢王建有贈', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["年狀皆齊初有髭，鵲山漳水每追隨。","使君座下朝聽易，處士庭中夜會詩。","新作句成相借問，閑求義盡共尋思。","經今三十餘年事，却說還同昨日時。"]', '["年狀皆齊初有髭，鵲山漳水每追隨。","使君座下朝听易，处士庭中夜會诗。","新作句成相借问，闲求義尽共尋思。","經今三十餘年事，却说還同昨日时。"]', '诗', 'shi', '', NULL, '逢王建有贈 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ee04935-b05b-427d-be12-d1015dfabff7', '移居靜安坊答元八郎中', '移居静安坊答元八郎中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["長安寺裏多時住，雖守卑官不苦貧。","作活每常嫌費力，移居祗是貴容身。","初開井淺偏宜樹，漸覺街閑省踏塵。","更喜往還相去近，門前減却送書人。"]', '["长安寺裏多时住，雖守卑官不苦貧。","作活每常嫌費力，移居祗是貴容身。","初开井淺偏宜樹，漸覺街闲省踏塵。","更喜往還相去近，门前減却送书人。"]', '诗', 'shi', '', NULL, '移居靜安坊答元八郎中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7670129d-e5f8-483d-9c00-361f0e425faa', '送楊少尹赴鳳翔', '送楊少尹赴鳳翔', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["詩名往日動長安，首首人家卷裏看。","西學已行秦博士，南宮新拜漢郎官。","得錢祗了還書鋪，借宅常時事藥欄。","今去岐州生計薄，移居偏近隴頭寒。"]', '["诗名往日动长安，首首人家卷裏看。","西学已行秦博士，南宮新拜漢郎官。","得錢祗了還书鋪，借宅常时事藥欄。","今去岐州生計薄，移居偏近隴头寒。"]', '诗', 'shi', '', NULL, '送楊少尹赴鳳翔 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9448354e-2de0-4cad-8a68-dfca162110cf', '送韓侍御歸山', '送韓侍御归山', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["聞君久臥在雲間，爲佐嫖姚未得還。","新階茆廬招隱逸，獨騎驄馬入深山。","九靈洞口行應到，五粒松枝醉亦攀。","明日珂聲出城去，家僮不復埽柴關。"]', '["闻君久臥在云间，爲佐嫖姚未得還。","新階茆廬招隐逸，独騎驄马入深山。","九靈洞口行應到，五粒松枝醉亦攀。","明日珂声出城去，家僮不复埽柴关。"]', '诗', 'shi', '', NULL, '送韓侍御歸山 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0660e5ee-25b4-41c5-ac79-7994c87f6e3d', '新除水曹郎答白舍人見賀', '新除水曹郎答白舍人见賀', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["年過五十到南宮，章句無名荷至公。","黃紙開呈相府後，朱衣引入謝班中。","諸曹縱許爲仙侶，羣吏多嫌是老翁。","最幸紫薇郎見愛，獨稱官與古人同。"]', '["年過五十到南宮，章句無名荷至公。","黄紙开呈相府後，朱衣引入謝班中。","諸曹縱許爲仙侶，羣吏多嫌是老翁。","最幸紫薇郎见愛，独稱官與古人同。"]', '诗', 'shi', '', NULL, '新除水曹郎答白舍人見賀 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38e62a26-9840-48c5-b72f-78c744172661', '送楊少尹赴滿城', '送楊少尹赴满城', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["官爲本府當身榮，因得還鄉任野情。","自廢田園今作主，每逢耆老不呼名。","舊遊寺裏僧應識，新別橋邊樹已成。","公事況閑詩更好，將隨相逐上山行。"]', '["官爲本府當身榮，因得還乡任野情。","自廢田园今作主，每逢耆老不呼名。","旧游寺裏僧應識，新別橋邊樹已成。","公事況闲诗更好，將隨相逐上山行。"]', '诗', 'shi', '', NULL, '送楊少尹赴滿城 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52dc13f5-5fd6-4b8c-aa4b-afc699123361', '哭元九少府', '哭元九少府', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["平生志業獨相知，早結雲山老去期。","初作學官常共宿，晚登朝列暫同時。","閑來各數經過地，醉後齊吟唱和詩。","今日春風花滿宅，入門行哭見靈帷。"]', '["平生志業独相知，早結云山老去期。","初作学官常共宿，晚登朝列暫同时。","闲来各數經過地，醉後齊吟唱和诗。","今日春风花满宅，入门行哭见靈帷。"]', '诗', 'shi', '', NULL, '哭元九少府 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fea8fb6-44b1-495c-b196-3875715a09d1', '送侯判官赴廣州從軍', '送侯判官赴廣州從軍', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["年少才高求自展，將身萬里赴軍門。","辟書遠到開呈客，公服新成著謝恩。","驛舫過江分白堠，戍亭當嶺見紅旛。","海花蠻草連冬有，行處無家不滿園。"]', '["年少才高求自展，將身万里赴軍门。","辟书远到开呈客，公服新成著謝恩。","驛舫過江分白堠，戍亭當嶺见紅旛。","海花蠻草連冬有，行处無家不满园。"]', '诗', 'shi', '', NULL, '送侯判官赴廣州從軍 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28527ad0-4b09-4eca-8a74-79a1ab1aa755', '答白杭州郡樓登望畫圖見寄', '答白杭州郡楼登望畫圖见寄', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["畫得江城登望處，寄來今日到長安。","乍驚物色從詩出，更想工人下手難。","將展書堂偏覺好，每來朝客盡求看。","見君向此閑吟意，肯恨當時作外官。"]', '["畫得江城登望处，寄来今日到长安。","乍驚物色從诗出，更想工人下手难。","將展书堂偏覺好，每来朝客尽求看。","见君向此闲吟意，肯恨當时作外官。"]', '诗', 'shi', '', NULL, '答白杭州郡樓登望畫圖見寄 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2deab82a-0a07-4848-85e1-f77dc21495d8', '贈趙將軍', '贈趙將軍', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["當年膽略已縱橫，每見妖星氣不平。","身貴早登龍尾道，功高自破鹿頭城。","尋常得對論邊事，委曲承恩掌內兵。","會取安西將報國，凌煙閣上大書名。"]', '["當年膽略已縱橫，每见妖星氣不平。","身貴早登龙尾道，功高自破鹿头城。","尋常得对論邊事，委曲承恩掌內兵。","會取安西將報国，凌煙閣上大书名。"]', '诗', 'shi', '', NULL, '贈趙將軍 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a7ff27-a054-41fa-8d37-71901338f6da', '送和蕃公主', '送和蕃公主', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["塞上如今無戰塵，漢家公主出和親。","邑司猶屬宗卿寺，冊號還同虜帳人。","九姓旗旛先引路，一生衣服盡隨身。","氈城南望無迴日，空見沙蓬水柳春。"]', '["塞上如今無戰塵，漢家公主出和親。","邑司猶屬宗卿寺，冊號還同虜帳人。","九姓旗旛先引路，一生衣服尽隨身。","氈城南望無迴日，空见沙蓬水柳春。"]', '诗', 'shi', '', NULL, '送和蕃公主 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa1adb66-7fe0-4b2b-be06-6f56eb01cec5', '寒食內宴二首 一', '寒食內宴二首 一', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["朝光瑞氣滿宮樓，綵纛魚龍四面稠。","廊下御廚分冷食，殿前香騎逐飛毬。","千官盡醉猶教坐，百戲皆呈未放休。","共喜拜恩侵夜出，金吾不敢問行由。"]', '["朝光瑞氣满宮楼，綵纛鱼龙四面稠。","廊下御廚分冷食，殿前香騎逐飞毬。","千官尽醉猶教坐，百戲皆呈未放休。","共喜拜恩侵夜出，金吾不敢问行由。"]', '诗', 'shi', '', NULL, '寒食內宴二首 一 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc0e121-f66f-4368-9c8a-1fe8635e7ad1', '寒食內宴二首 二', '寒食內宴二首 二', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["城闕沈沈向曉寒，恩當令節賜餘歡。","瑞煙深處開三殿，春雨微時引百官。","寶樹樓前分繡幕，綵花廊下暎華欄。","宮筵戲樂年年別，已得三廻對御看。"]', '["城闕沈沈向晓寒，恩當令節賜餘歡。","瑞煙深处开三殿，春雨微时引百官。","寶樹楼前分繡幕，綵花廊下暎华欄。","宮筵戲乐年年別，已得三廻对御看。"]', '诗', 'shi', '', NULL, '寒食內宴二首 二 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ef7bc94-3b3f-4224-ba4c-889a39870e38', '朝日勅賜百官櫻桃', '朝日勅賜百官櫻桃', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["仙果人間都未有，今朝忽見下天門。","捧盤小吏初宣勅，當殿羣臣共拜恩。","日色遙分門下坐，露香才出禁中園。","每年重此先偏待，願得千春奉至尊。"]', '["仙果人间都未有，今朝忽见下天门。","捧盤小吏初宣勅，當殿羣臣共拜恩。","日色遙分门下坐，露香才出禁中园。","每年重此先偏待，願得千春奉至尊。"]', '诗', 'shi', '', NULL, '朝日勅賜百官櫻桃 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74b9cde0-f297-46e1-a744-dcc9daeb7d92', '太白老人', '太白老人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["日觀東峰幽客住，竹巾藤帶亦逢迎。","暗修黃籙無人見，深種胡麻共犬行。","洞裏仙家常獨往，壺中靈藥自爲名。","春泉四面遶茅屋，日日唯聞杵臼聲。"]', '["日观东峰幽客住，竹巾藤带亦逢迎。","暗修黄籙無人见，深種胡麻共犬行。","洞裏仙家常独往，壺中靈藥自爲名。","春泉四面遶茅屋，日日唯闻杵臼声。"]', '诗', 'shi', '', NULL, '太白老人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68080293-b18f-4260-9564-f5b35c06ad3a', '和裴司空酬滿城楊少尹', '和裴司空酬满城楊少尹', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["聖朝偏重大司空，人詠元和第一功。","擁節高臨漢水上，題詩遠入舜城中。","共驚向老多年別，更憶登科舊日同。","誰不望歸丞相府，江邊楊柳又秋風。"]', '["聖朝偏重大司空，人詠元和第一功。","擁節高臨漢水上，題诗远入舜城中。","共驚向老多年別，更憶登科旧日同。","誰不望归丞相府，江邊楊柳又秋风。"]', '诗', 'shi', '', NULL, '和裴司空酬滿城楊少尹 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4334cf10-8430-42a2-b83d-cb8695f024c0', '寄和州劉使君', '寄和州劉使君', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["別離已久猶爲郡，閑向春風倒酒缾。","送客特過沙口堰，看花多上水心亭。","曉來江氣連城白，雨後山光滿郭青。","到此詩情應更遠，醉中高詠有誰聽。"]', '["別離已久猶爲郡，闲向春风倒酒缾。","送客特過沙口堰，看花多上水心亭。","晓来江氣連城白，雨後山光满郭青。","到此诗情應更远，醉中高詠有誰听。"]', '诗', 'shi', '', NULL, '寄和州劉使君 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d09f2306-ec02-4e9f-a5d1-d37967e17ab1', '贈商州王使君', '贈商州王使君', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["銜命南來會郡堂，却思朝裏接班行。","才雄猶是山城守，道薄初爲水部郎。","選勝相留開客館，尋幽更引到僧房。","明朝從此辭君去，獨出商關路漸長。"]', '["銜命南来會郡堂，却思朝裏接班行。","才雄猶是山城守，道薄初爲水部郎。","選勝相留开客館，尋幽更引到僧房。","明朝從此辞君去，独出商关路漸长。"]', '诗', 'shi', '', NULL, '贈商州王使君 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5383280e-28b4-4df5-8fe0-ee9f651165cd', '寄令狐賓客', '寄令狐賓客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["勳名盡得國家傳，退狎琴僧與酒仙。","還帶郡符經幾處，暫辭台座已三年。","留司未到龍樓下，拜表長懷玉案前。","秋日出城伊水好，領誰相逐上閑船。"]', '["勳名尽得国家傳，退狎琴僧與酒仙。","還带郡符經幾处，暫辞台座已三年。","留司未到龙楼下，拜表长懷玉案前。","秋日出城伊水好，領誰相逐上闲船。"]', '诗', 'shi', '', NULL, '寄令狐賓客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599ee7ca-7e82-4689-b92a-709e51bfce33', '寄梅處士', '寄梅处士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["擾擾人間是與非，官閑自覺省心機。","六行班裏身常下，九列符中事亦稀。","市客慣曾賒賤藥，家僮驚見著新衣。","君今獨得居山樂，應喜多時未辦歸。"]', '["擾擾人间是與非，官闲自覺省心機。","六行班裏身常下，九列符中事亦稀。","市客慣曾賒賤藥，家僮驚见著新衣。","君今独得居山乐，應喜多时未辦归。"]', '诗', 'shi', '', NULL, '寄梅處士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c7be068-f8db-44c0-99c3-9f44d95b7d4a', '送施肩吾東歸', '送施肩吾东归', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["知君本是煙霞客，被薦因來城闕間。","世業偏臨七里瀨，仙遊多在四明山。","早聞詩句傳人徧，新得科名到處閑。","惆悵灞亭相送去，雲中琪樹不同攀。"]', '["知君本是煙霞客，被薦因来城闕间。","世業偏臨七里瀨，仙游多在四明山。","早闻诗句傳人徧，新得科名到处闲。","惆悵灞亭相送去，云中琪樹不同攀。"]', '诗', 'shi', '', NULL, '送施肩吾東歸 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f254a77c-17ff-46b4-83e9-623ef57d441c', '崑崙兒', '崑崙兒', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["崑崙家住海中州，蠻客將來漢地遊。","言語解教秦吉了，波濤初過鬱林洲。","金環欲落曾穿耳，螺髻長卷不裹頭。","自愛肌膚黑如漆，行時半脫木綿裘。"]', '["崑崙家住海中州，蠻客將来漢地游。","言語解教秦吉了，波濤初過鬱林洲。","金环欲落曾穿耳，螺髻长卷不裹头。","自愛肌膚黑如漆，行时半脫木綿裘。"]', '诗', 'shi', '', NULL, '崑崙兒 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01f4e76e-8cee-4b7e-a513-e1221a53300d', '贈李杭州', '贈李杭州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["仙郎白首未歸朝，應爲蒼生領六條。","惠化州人盡清淨，高情野鶴與逍遙。","竹間虛館無朝訟，山畔青田長夏苗。","終日政聲長獨坐，開門長望浙江潮。"]', '["仙郎白首未归朝，應爲蒼生領六條。","惠化州人尽清淨，高情野鹤與逍遙。","竹间虛館無朝訟，山畔青田长夏苗。","終日政声长独坐，开门长望浙江潮。"]', '诗', 'shi', '', NULL, '贈李杭州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43966955-c47e-428d-92e8-0803ac8bb4de', '送鄭尚書赴廣州', '送鄭尚书赴廣州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["聖朝選將持符節，內使宣時百辟聽。","海北蠻夷來舞蹈，嶺南封管送圖經。","白鷴飛遶迎官舫，紅槿開當讌客亭。","此處莫言多瘴癘，天邊看取老人星。"]', '["聖朝選將持符節，內使宣时百辟听。","海北蠻夷来舞蹈，嶺南封管送圖經。","白鷴飞遶迎官舫，紅槿开當讌客亭。","此处莫言多瘴癘，天邊看取老人星。"]', '诗', 'shi', '', NULL, '送鄭尚書赴廣州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f09773a-fe00-4b09-8c0f-c045fd61f344', '賀秘書王丞南郊攝將軍', '賀秘书王丞南郊攝將軍', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["正初天子親郊禮，詔攝將軍領衛兵。","斜帶銀刀入黃道，先隨玉輅到青城。","壇邊不在千官位，仗外唯聞再拜聲。","共喜與君逢此日，病中無計得隨行。"]', '["正初天子親郊禮，詔攝將軍領衛兵。","斜带銀刀入黄道，先隨玉輅到青城。","壇邊不在千官位，仗外唯闻再拜声。","共喜與君逢此日，病中無計得隨行。"]', '诗', 'shi', '', NULL, '賀秘書王丞南郊攝將軍 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90e225a-331a-4f78-9e14-f930489e2cff', '送令狐尚書赴東都留守', '送令狐尚书赴东都留守', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["朝廷重寄在關東，共說從前選上公。","勳業新城大梁鎮，恩榮更守洛陽宮。","行香暫出天橋上，巡禮常過禁殿中。","每領羣臣拜章慶，半開門仗日曈曈。"]', '["朝廷重寄在关东，共说從前選上公。","勳業新城大梁鎮，恩榮更守洛陽宮。","行香暫出天橋上，巡禮常過禁殿中。","每領羣臣拜章慶，半开门仗日曈曈。"]', '诗', 'shi', '', NULL, '送令狐尚書赴東都留守 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fee945e-5d15-48c3-9ca1-4115f9ee27cd', '拜豐陵', '拜豐陵', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["歲朝園寢遣公卿，學省班中亦攝行。","身逐陵官齊再拜，手持木鐸叩三聲。","寒更報點來山殿，曉炬分行照栢城。","却下龍門看漸遠，金峰高處日微明。"]', '["歲朝园寢遣公卿，学省班中亦攝行。","身逐陵官齊再拜，手持木鐸叩三声。","寒更報点来山殿，晓炬分行照栢城。","却下龙门看漸远，金峰高处日微明。"]', '诗', 'shi', '', NULL, '拜豐陵 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68da5949-d64b-4058-85e9-ccdf23dd687c', '贈孔尚書', '贈孔尚书', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["能將直道歷榮班，事著元和實錄間。","三表自陳辭北闕，一家相送入南山。","買來侍女教人嫁，賜得朝衣在篋閑。","宅近青山高靜處，時歸林下暫開關。"]', '["能將直道歷榮班，事著元和實錄间。","三表自陳辞北闕，一家相送入南山。","買来侍女教人嫁，賜得朝衣在篋闲。","宅近青山高静处，时归林下暫开关。"]', '诗', 'shi', '', NULL, '贈孔尚書 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d111410-9d0e-411b-af45-e61d4f1e0c7a', '酬杭州白使君兼寄浙東元大夫', '酬杭州白使君兼寄浙东元大夫', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["相印暫離臨遠鎮，掖垣出守復同時。","一行已作三年別，兩處空傳七字詩。","越地江山應共見，秦天風月不相知。","人間聚散真難料，莫歎平生信所之。"]', '["相印暫離臨远鎮，掖垣出守复同时。","一行已作三年別，兩处空傳七字诗。","越地江山應共见，秦天风月不相知。","人间聚散真难料，莫歎平生信所之。"]', '诗', 'shi', '', NULL, '酬杭州白使君兼寄浙東元大夫 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6eff5bf-c858-4b80-8ad2-75f19c022a55', '寄蘇州白二十二使君', '寄蘇州白二十二使君', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["三朝出入紫微臣，頭白金章未在身。","登第早年同座主，題詩今日是州人。","閶門柳色煙中遠，茂苑鶯聲雨後新。","此處吟詩向山寺，知君忘却曲江春。"]', '["三朝出入紫微臣，头白金章未在身。","登第早年同座主，題诗今日是州人。","閶门柳色煙中远，茂苑鶯声雨後新。","此处吟诗向山寺，知君忘却曲江春。"]', '诗', 'shi', '', NULL, '寄蘇州白二十二使君 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d6d253-6aa8-43ea-98ae-6fbd0bafbbf7', '送白賓客分司東都', '送白賓客分司东都', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["赫赫聲名三十春，高情人獨出埃塵。","病辭省闥歸閑地，恩許宮曹作上賓。","詩裏難同相得伴，酒邊多見自由身。","老人也擬休官去，便是君家池上人。"]', '["赫赫声名三十春，高情人独出埃塵。","病辞省闥归闲地，恩許宮曹作上賓。","诗裏难同相得伴，酒邊多见自由身。","老人也擬休官去，便是君家池上人。"]', '诗', 'shi', '', NULL, '送白賓客分司東都 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ceb589-d95b-45e5-a962-0c45a0619a1a', '贈閻少保', '贈閻少保', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["辭榮戀闕未還鄉，修養年多氣力強。","半俸歸燒伏火藥，全家解說養生方。","特承恩詔新開戟，每見公卿不下牀。","竹樹晴深寒院靜，長懸石磬在虛廊。"]', '["辞榮戀闕未還乡，修養年多氣力強。","半俸归燒伏火藥，全家解说養生方。","特承恩詔新开戟，每见公卿不下牀。","竹樹晴深寒院静，长懸石磬在虛廊。"]', '诗', 'shi', '', NULL, '贈閻少保 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8765dbf-31c4-46a6-bd1e-0accbdc6fe95', '贈別王侍御赴任陝州司馬', '贈別王侍御赴任陝州司马', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["京城在處閑人少，唯共君行並馬蹄。","更和詩篇名最出，時傾杯酒戶常齊。","同趨闕下聽鐘漏，獨向軍前聞鼓鼙。","今日春明門外別，更無因得到街西。"]', '["京城在处闲人少，唯共君行並马蹄。","更和诗篇名最出，时傾杯酒戶常齊。","同趨闕下听鐘漏，独向軍前闻鼓鼙。","今日春明门外別，更無因得到街西。"]', '诗', 'shi', '', NULL, '贈別王侍御赴任陝州司馬 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84169119-3ee7-4a54-b111-0ed05cb569fa', '田司空入朝', '田司空入朝', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["西來將相位兼雄，不與諸君覲禮同。","早變山東知順命，新收濟上立殊功。","朝官敘謁趨門外，恩使喧迎滿路中。","閶闔曉開銅漏靜，身當受冊大明宮。"]', '["西来將相位兼雄，不與諸君覲禮同。","早变山东知順命，新收濟上立殊功。","朝官敘謁趨门外，恩使喧迎满路中。","閶闔晓开銅漏静，身當受冊大明宮。"]', '诗', 'shi', '', NULL, '田司空入朝 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa36b511-7c7b-4d4f-9595-bd0c6a64646e', '送浙西周判官', '送浙西周判官', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["由來自是煙霞客，早已聞名詩酒間。","天闕因將賀表到，家鄉新著賜衣遠。","常吟卷裏新酬句，自話湖中舊住山。","吳越主人偏愛重，多應不肯放君閑。"]', '["由来自是煙霞客，早已闻名诗酒间。","天闕因將賀表到，家乡新著賜衣远。","常吟卷裏新酬句，自話湖中旧住山。","吳越主人偏愛重，多應不肯放君闲。"]', '诗', 'shi', '', NULL, '送浙西周判官 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd4b03d3-5491-4c49-80a4-2514043e5d74', '送吳鍊師歸王屋', '送吳鍊師归王屋', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["玉陽峰下學長生，玉洞仙中已有名。","獨戴熊鬚冠暫出，唯將鶴尾扇同行。","煉成雲母休炊爨，已得雷公當吏兵。","却到瑤壇上頭宿，應聞空裏步虛聲。"]', '["玉陽峰下学长生，玉洞仙中已有名。","独戴熊鬚冠暫出，唯將鹤尾扇同行。","煉成云母休炊爨，已得雷公當吏兵。","却到瑤壇上头宿，應闻空裏步虛声。"]', '诗', 'shi', '', NULL, '送吳鍊師歸王屋 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6706142-79ab-4639-9fbe-9c1e09517c5e', '送邵州林使君', '送邵州林使君', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["詞客南行寵命新，瀟湘郡入曲江津。","山幽自足探微處，俗朴應無爭競人。","郭外相連排殿閣，市中多半用金銀。","知君不作家私計，遷日還同到日貧。"]', '["词客南行寵命新，瀟湘郡入曲江津。","山幽自足探微处，俗朴應無爭競人。","郭外相連排殿閣，市中多半用金銀。","知君不作家私計，遷日還同到日貧。"]', '诗', 'shi', '', NULL, '送邵州林使君 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ec388a-d5a9-4b2c-a93f-86cb85c8f597', '寄王六侍御', '寄王六侍御', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["漸覺近來筋力少，難堪今日在風塵。","誰能借問功名事，祗自扶持老病身。","貴得藥資將助道，肯嫌家計不如人。","洞庭已置新居處，歸去安期與作鄰。"]', '["漸覺近来筋力少，难堪今日在风塵。","誰能借问功名事，祗自扶持老病身。","貴得藥資將助道，肯嫌家計不如人。","洞庭已置新居处，归去安期與作鄰。"]', '诗', 'shi', '', NULL, '寄王六侍御 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82da9ec9-f213-4a87-b5e0-f419f984b8dc', '送稽亭山寺僧', '送稽亭山寺僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["師住稽亭高處寺，斜廊曲閣倚雲開。","山門十里松間入，泉澗三重洞裏來。","名岳尋遊今已徧，家城禮謁便應迴。","舊房到日閑吟後，林下還登說法臺。"]', '["師住稽亭高处寺，斜廊曲閣倚云开。","山门十里松间入，泉澗三重洞裏来。","名岳尋游今已徧，家城禮謁便應迴。","旧房到日闲吟後，林下還登说法台。"]', '诗', 'shi', '', NULL, '送稽亭山寺僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('109f899b-84f0-4e71-959a-969db7f67755', '送汀州源使君', '送汀州源使君', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["曾成趙北歸朝計，因拜王門最好官。","爲郡暫辭雙鳳闕，全家遠過九龍灘。","山鄉祗有輸蕉戶，水鎮應多養鴨欄。","地僻尋常來客少，刺桐花發共誰看。"]', '["曾成趙北归朝計，因拜王门最好官。","爲郡暫辞雙鳳闕，全家远過九龙灘。","山乡祗有輸蕉戶，水鎮應多養鴨欄。","地僻尋常来客少，刺桐花發共誰看。"]', '诗', 'shi', '', NULL, '送汀州源使君 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f26e21c-78b1-4f24-be65-7e27ae0d3be0', '寄孫洛陽格', '寄孫洛陽格', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["久持刑憲聲名遠，好是中朝正直臣。","赤縣上來應足事，青山老去未離身。","常思從省連歸馬，乍覺同班少舊人。","遙愛南橋秋日晚，雨邊楊柳映天津。"]', '["久持刑憲声名远，好是中朝正直臣。","赤縣上来應足事，青山老去未離身。","常思從省連归马，乍覺同班少旧人。","遙愛南橋秋日晚，雨邊楊柳映天津。"]', '诗', 'shi', '', NULL, '寄孫洛陽格 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4dc1b33-be39-4b2d-be7f-ef13827e6b21', '胡山人歸王屋因有贈', '胡山人归王屋因有贈', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["轉轉無成到白頭，人間舉眼盡堪愁。","此生已是蹉跎去，每事應從鹵莽休。","雖作閑官少拘束，難逢勝景可淹留。","君歸與訪移家處，若箇峰頭最較幽。"]', '["轉轉無成到白头，人间舉眼尽堪愁。","此生已是蹉跎去，每事應從鹵莽休。","雖作闲官少拘束，难逢勝景可淹留。","君归與訪移家处，若箇峰头最較幽。"]', '诗', 'shi', '', NULL, '胡山人歸王屋因有贈 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6380ab9-4da5-4392-8dd5-d6b9bc4b23de', '寄虔州韓使君', '寄虔州韓使君', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["南康太守負才豪，五十如今未擁旄。","早得一人知姓字，常聞三事說功勞。","月明渡口漳江靜，雲散城頭贛石高。","郡政已成秋思遠，閑吟應不問官曹。"]', '["南康太守負才豪，五十如今未擁旄。","早得一人知姓字，常闻三事说功勞。","月明渡口漳江静，云散城头贛石高。","郡政已成秋思远，闲吟應不问官曹。"]', '诗', 'shi', '', NULL, '寄虔州韓使君 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39545234-b328-4476-9299-df92067de29b', '送從弟濛赴饒州', '送從弟濛赴饒州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["京城南去鄱陽遠，風月悠悠別思勞。","三領郡符新寄重，再登科第舊名高。","去程江上多看堠，迎吏船中亦帶刀。","到日更行清靜化，春田應不見蓬蒿。"]', '["京城南去鄱陽远，风月悠悠別思勞。","三領郡符新寄重，再登科第旧名高。","去程江上多看堠，迎吏船中亦带刀。","到日更行清静化，春田應不见蓬蒿。"]', '诗', 'shi', '', NULL, '送從弟濛赴饒州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb9157d6-9cc6-42ff-8fb0-b59181af7aba', '羅道士', '羅道士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["城裏無人得實年，衣襟常帶臭黃煙。","樓中賒酒唯留藥，洞裏爭棋不賭錢。","聞客語聲知貴賤，持花歌詠似狂顛。","尋常行處皆逢見，世上多疑是謫仙。"]', '["城裏無人得實年，衣襟常带臭黄煙。","楼中賒酒唯留藥，洞裏爭棋不賭錢。","闻客語声知貴賤，持花歌詠似狂顛。","尋常行处皆逢见，世上多疑是謫仙。"]', '诗', 'shi', '', NULL, '羅道士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f917edb7-95ba-446b-afab-cf98986139ba', '寄陸渾趙明府', '寄陸渾趙明府', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["與君學省同官處，常日相隨說道情。","新作陸渾山縣長，早知三禮甲科名。","郭中時有仙人住，城內應多藥草生。","公事稀疎來客少，無妨著屐獨閑行。"]', '["與君学省同官处，常日相隨说道情。","新作陸渾山縣长，早知三禮甲科名。","郭中时有仙人住，城內應多藥草生。","公事稀疎来客少，無妨著屐独闲行。"]', '诗', 'shi', '', NULL, '寄陸渾趙明府 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8451c1ce-8951-4d77-8948-8be88dc4fbfe', '同將作韋二少監贈水部李郎中', '同將作韋二少監贈水部李郎中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["舊年同是水曹郎，各罷魚符自楚鄉。","重著青衫承詔命，齊趨紫殿異班行。","別來同說經過事，老去相傳補養方。","憶得當時亦連步，如今獨在讀書堂。"]', '["旧年同是水曹郎，各罷鱼符自楚乡。","重著青衫承詔命，齊趨紫殿異班行。","別来同说經過事，老去相傳補養方。","憶得當时亦連步，如今独在读书堂。"]', '诗', 'shi', '', NULL, '同將作韋二少監贈水部李郎中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daa86f6d-98fb-4231-84c3-f0cace4efbf6', '贈王侍御', '贈王侍御', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["心同野鶴與塵遠，詩似冰壺見底清。","府縣同趨昨日事，升沈不改故人情。","上陽春晚蕭蕭雨，洛水寒來夜夜聲。","自歎獨爲折腰吏，可憐騘馬路傍行。"]', '["心同野鹤與塵远，诗似冰壺见底清。","府縣同趨昨日事，升沈不改故人情。","上陽春晚蕭蕭雨，洛水寒来夜夜声。","自歎独爲折腰吏，可怜騘马路傍行。"]', '诗', 'shi', '', NULL, '贈王侍御 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf87caa9-9c44-4fed-a46e-f72f5b400811', '送金少卿副使歸新羅', '送金少卿副使归新羅', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["雲島茫茫天畔微，向東萬里一帆飛。","久爲侍子承恩重，今佐使臣銜命歸。","通海便應將國信，到家猶自著朝衣。","從前此去人無數，光彩如君定是稀。"]', '["云島茫茫天畔微，向东万里一帆飞。","久爲侍子承恩重，今佐使臣銜命归。","通海便應將国信，到家猶自著朝衣。","從前此去人無數，光彩如君定是稀。"]', '诗', 'shi', '', NULL, '送金少卿副使歸新羅 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7768076-32f2-47d4-8e1e-18841709b67e', '送李司空赴鎮襄陽', '送李司空赴鎮襄陽', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["中外兼權社稷臣，千官齊出拜行塵。","再調公鼎勳庸盛，三受兵符寵命新。","商路雪開旗斾展，楚堤梅發驛亭春。","襄陽風景由來好，重與江山作主人。"]', '["中外兼權社稷臣，千官齊出拜行塵。","再調公鼎勳庸盛，三受兵符寵命新。","商路雪开旗斾展，楚堤梅發驛亭春。","襄陽风景由来好，重與江山作主人。"]', '诗', 'shi', '', NULL, '送李司空赴鎮襄陽 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcda6c14-512b-4aa0-ba62-d10f4c4fc50c', '送李僕射愬赴鎮鳳翔', '送李僕射愬赴鎮鳳翔', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["由來勳業屬英雄，兄弟連營列位同。","先入賊城擒首惡，盡封筦庫讓元公。","旌幢獨繼家聲外，竹帛新添國史中。","天子新收秦隴地，故教移鎮古扶風。"]', '["由来勳業屬英雄，兄弟連營列位同。","先入賊城擒首惡，尽封筦庫讓元公。","旌幢独繼家声外，竹帛新添国史中。","天子新收秦隴地，故教移鎮古扶风。"]', '诗', 'shi', '', NULL, '送李僕射愬赴鎮鳳翔 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1290d4c7-e30b-4007-a0fe-bac3cb9d0f4f', '寄白二十二舍人', '寄白二十二舍人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["早知內詔過先輩，蹭蹬江南百事疎。","湓浦成中爲上佐，爐峰寺後著幽居。","偏依仙法多求藥，長共僧遊不讀書。","三省比來名望重，肯容君去樂樵漁。"]', '["早知內詔過先輩，蹭蹬江南百事疎。","湓浦成中爲上佐，爐峰寺後著幽居。","偏依仙法多求藥，长共僧游不读书。","三省比来名望重，肯容君去乐樵漁。"]', '诗', 'shi', '', NULL, '寄白二十二舍人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a2dd04-afb6-4cf4-97f2-8ddd300ebaef', '送友人盧處士遊吳越', '送友人盧处士游吳越', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["羨君東去見殘梅，惟有王孫獨未回。","吳苑夕陽明古堞，越宮春草上高臺。","波生野水雁初下，風滿驛樓潮欲來。","試問漁舟看雪浪，幾多江燕荇花開。"]', '["羨君东去见殘梅，惟有王孫独未回。","吳苑夕陽明古堞，越宮春草上高台。","波生野水雁初下，风满驛楼潮欲来。","試问漁舟看雪浪，幾多江燕荇花开。"]', '诗', 'shi', '', NULL, '送友人盧處士遊吳越 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3db0db09-2db6-4884-bc07-4dd85d45b67c', '蘇州江岸留別樂天', '蘇州江岸留別乐天', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["銀泥裙暎錦障泥，畫舸停橈馬簇蹄。","清管曲終鸚鵡語，紅旗影動薄寒嘶。","漸消酒色朱顏淺，欲話離情翠黛低。","莫忘使君吟詠處，女墳湖北武丘西。"]', '["銀泥裙暎錦障泥，畫舸停橈马簇蹄。","清管曲終鸚鵡語，紅旗影动薄寒嘶。","漸消酒色朱顏淺，欲話離情翠黛低。","莫忘使君吟詠处，女墳湖北武丘西。"]', '诗', 'shi', '', NULL, '蘇州江岸留別樂天 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e9f8876-7c0c-4722-b7e7-0eba3f64daa5', '寒食看花', '寒食看花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["早入公門到夜歸，不因寒食少閑時。","顛狂遶樹猿離鎖，踴躍緣岡馬斷羈。","酒汙衣裳從客笑，醉饒言語覓花知。","老來自喜常無事，仰面西園得詠詩。"]', '["早入公门到夜归，不因寒食少闲时。","顛狂遶樹猿離鎖，踴躍緣岡马斷羈。","酒汙衣裳從客笑，醉饒言語覓花知。","老来自喜常無事，仰面西园得詠诗。"]', '诗', 'shi', '', NULL, '寒食看花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4ab13ce-b240-407a-a2fc-1949081758ba', '酬浙東元尚書見寄綾素', '酬浙东元尚书见寄綾素', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["越地繒紗紋樣新，遠封來寄學曹人。","便令裁制爲時服，頓覺光榮上病身。","應念此官同棄置，獨能相賀更殷勤。","三千里外無由見，海上東風又一春。"]', '["越地繒紗紋樣新，远封来寄学曹人。","便令裁制爲时服，頓覺光榮上病身。","應念此官同棄置，独能相賀更殷勤。","三千里外無由见，海上东风又一春。"]', '诗', 'shi', '', NULL, '酬浙東元尚書見寄綾素 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1adfc21-9991-486e-a47a-457753a32af5', '贈項斯', '贈項斯', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["端坐吟詩忘忍飢，萬人中覓似君稀。","門連野水風長到，驢放秋原夜不歸。","日煖剩收新落葉，天寒更著舊生衣。","曲江亭上頻頻見，爲愛鸕鷀雨裏飛。"]', '["端坐吟诗忘忍飢，万人中覓似君稀。","门連野水风长到，驢放秋原夜不归。","日煖剩收新落葉，天寒更著旧生衣。","曲江亭上頻頻见，爲愛鸕鷀雨裏飞。"]', '诗', 'shi', '', NULL, '贈項斯 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e7e656b-5ca2-4dbc-972f-0369be5046b8', '和韋開州盛山十二首 宿雲亭', '和韋开州盛山十二首 宿云亭', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["清淨當深處，虛明向遠開。","卷簾無俗客，應只見雲來。"]', '["清淨當深处，虛明向远开。","卷簾無俗客，應只见云来。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 宿雲亭 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5dc1daca-91ed-4733-a4b4-b20c3243d375', '和韋開州盛山十二首 梅溪', '和韋开州盛山十二首 梅溪', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["自愛新梅好，行尋一徑斜。","不教人掃石，恐損落來花。"]', '["自愛新梅好，行尋一徑斜。","不教人掃石，恐損落来花。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 梅溪 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc8c6420-826a-4025-962d-e5b01a6c76b5', '和韋開州盛山十二首 茶嶺', '和韋开州盛山十二首 茶嶺', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["紫芽連白蘂，初向嶺頭生。","自看家人摘，尋常觸露行。"]', '["紫芽連白蘂，初向嶺头生。","自看家人摘，尋常觸露行。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 茶嶺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c498561-27a0-447d-86fc-ad0232f9ee43', '和韋開州盛山十二首 流杯渠', '和韋开州盛山十二首 流杯渠', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["淥酒白螺杯，隨流去復回。","似知人把處，各向面前來。"]', '["淥酒白螺杯，隨流去复回。","似知人把处，各向面前来。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 流杯渠 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ea9fab0-d3c4-4ed6-8234-f78a1ae68cbb', '和韋開州盛山十二首 盤石磴', '和韋开州盛山十二首 盤石磴', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["壘石盤空遠，層層勢不危。","不知行幾匝，得到上頭時。"]', '["壘石盤空远，層層勢不危。","不知行幾匝，得到上头时。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 盤石磴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70580fb2-022f-4fea-9944-776f5637d835', '和韋開州盛山十二首 桃塢', '和韋开州盛山十二首 桃塢', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["春塢桃花發，多將野客遊。","日西殊未散，看望酒缸頭。"]', '["春塢桃花發，多將野客游。","日西殊未散，看望酒缸头。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 桃塢 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('389039e4-0124-42c5-84cf-cf29ebcb31e4', '和韋開州盛山十二首 竹巖', '和韋开州盛山十二首 竹巖', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨入千竿裏，緣巖踏石層。","笋頭齊欲出，更不許人登。"]', '["独入千竿裏，緣巖踏石層。","笋头齊欲出，更不許人登。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 竹巖 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e28b4e3b-2cd8-4915-9c8f-f9d4a50636ab', '和韋開州盛山十二首 琵琶臺', '和韋开州盛山十二首 琵琶台', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["臺上綠蘿春，閑登不待人。","每當休暇日，著履戴紗巾。"]', '["台上綠蘿春，闲登不待人。","每當休暇日，著履戴紗巾。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 琵琶臺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e9c0991-3551-4acf-8948-8115251f0c66', '和韋開州盛山十二首 胡蘆沼', '和韋开州盛山十二首 胡蘆沼', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["曲沼春流滿，新蒲映野鵝。","閑齋朝飯後，拄杖遶行多。"]', '["曲沼春流满，新蒲映野鵝。","闲斋朝飯後，拄杖遶行多。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 胡蘆沼 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb5ee0ca-ad31-409d-bcc7-b95b08ba2165', '和韋開州盛山十二首 隱月岫', '和韋开州盛山十二首 隐月岫', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["月出深峰裏，清涼夜亦寒。","每嫌西落疾，不得到明看。"]', '["月出深峰裏，清涼夜亦寒。","每嫌西落疾，不得到明看。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 隱月岫 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae8591be-54b1-484d-8bde-2ccec2ae987f', '和韋開州盛山十二首 繡衣石榻', '和韋开州盛山十二首 繡衣石榻', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["山城無別味，藥草兼魚果。","時到繡衣人，同來石上坐。"]', '["山城無別味，藥草兼鱼果。","时到繡衣人，同来石上坐。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 繡衣石榻 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5209fed5-6f9b-4e12-9fd9-f2d91d154d90', '和韋開州盛山十二首 上士泉缾', '和韋开州盛山十二首 上士泉缾', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["堦上一眼泉，四邊青石甃。","唯有護淨僧，添缾將盥漱。"]', '["堦上一眼泉，四邊青石甃。","唯有護淨僧，添缾將盥漱。"]', '诗', 'shi', '', NULL, '和韋開州盛山十二首 上士泉缾 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49ce4f86-6999-48a4-8d85-59851b6f62fd', '送遠客', '送远客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["憔悴遠歸客，殷勤欲別杯。","九星壇下路，幾日見重來。"]', '["憔悴远归客，殷勤欲別杯。","九星壇下路，幾日见重来。"]', '诗', 'shi', '', NULL, '送遠客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c937660-3aa1-4f1a-b39d-c41c717162ef', '寄西峰僧', '寄西峰僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["松暗水涓涓，夜涼人未眠。","西峰月猶在，遙憶草堂前。"]', '["松暗水涓涓，夜涼人未眠。","西峰月猶在，遙憶草堂前。"]', '诗', 'shi', '', NULL, '寄西峰僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f27bad0-5a8e-45c1-ae8d-54652a436648', '禪師', '禪師', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨在西峰頂，年年閉石房。","定中無弟子，人到爲焚香。"]', '["独在西峰頂，年年閉石房。","定中無弟子，人到爲焚香。"]', '诗', 'shi', '', NULL, '禪師 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aee5e51-52a5-4f6d-9271-a95b47d1db12', '惜花', '惜花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["山中春已晚，處處見花稀。","明日來應盡，林間宿不歸。"]', '["山中春已晚，处处见花稀。","明日来應尽，林间宿不归。"]', '诗', 'shi', '', NULL, '惜花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afe54c56-6577-4031-9610-361371e02256', '題暉師影堂', '題暉師影堂', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["日早欲參禪，竟無相識緣。","道場今獨到，惆悵影堂前。"]', '["日早欲參禪，竟無相識緣。","道場今独到，惆悵影堂前。"]', '诗', 'shi', '', NULL, '題暉師影堂 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ba6512-5989-4b29-929f-5e1e218eaddd', '涇州塞', '涇州塞', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["行到涇州塞，唯聞羌戍鼙。","道邊古雙堠，猶記向安西。"]', '["行到涇州塞，唯闻羌戍鼙。","道邊古雙堠，猶記向安西。"]', '诗', 'shi', '', NULL, '涇州塞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d25708ee-f6bb-4c12-a41d-5ff44f3d21bc', '野田', '野田', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["漠漠野田草，草中牛羊道。","古墓無子孫，白楊不得老。"]', '["漠漠野田草，草中牛羊道。","古墓無子孫，白楊不得老。"]', '诗', 'shi', '', NULL, '野田 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c914d5f4-9d87-4a75-b774-0c01187b4a97', '岸花', '岸花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["可憐岸邊樹，紅蘂發青條。","東風吹渡水，衝着木蘭橈。"]', '["可怜岸邊樹，紅蘂發青條。","东风吹渡水，衝着木蘭橈。"]', '诗', 'shi', '', NULL, '岸花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c703f78-d424-4982-b5d0-fcc5c5b219f5', '別于鵠', '別于鵠', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["離燈及晨輝，行人起復思。","出門兩相顧，青山路逶迤。"]', '["離灯及晨輝，行人起复思。","出门兩相顧，青山路逶迤。"]', '诗', 'shi', '', NULL, '別于鵠 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84243ce-8627-4860-9065-f36af42441e8', '送蜀客', '送蜀客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["蜀客南行祭碧雞，木棉花發錦江西。","山橋日晚行人少，時見猩猩樹上啼。"]', '["蜀客南行祭碧雞，木棉花發錦江西。","山橋日晚行人少，时见猩猩樹上啼。"]', '诗', 'shi', '', NULL, '送蜀客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d280af5-5168-4daf-9c35-ff414a1c79ad', '送元結', '送元結', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["昔日同遊漳水邊，如今重說恨綿綿。","天涯相見還離別，客路秋風又幾年。"]', '["昔日同游漳水邊，如今重说恨綿綿。","天涯相见還離別，客路秋风又幾年。"]', '诗', 'shi', '', NULL, '送元結 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec4bc92d-bd98-4edd-9a32-223db867aebc', '宿山祠', '宿山祠', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋草宮人斜裏墓，宮人誰送葬來時。","千千萬萬皆如此，家在邊城亦不知。"]', '["秋草宮人斜裏墓，宮人誰送葬来时。","千千万万皆如此，家在邊城亦不知。"]', '诗', 'shi', '', NULL, '宿山祠 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12ee9d91-c4af-467a-90cd-ad6857e7f96f', '美人宮棊', '美人宮棊', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["紅燭臺前出翠娥，海沙鋪局巧相和。","趂行移手巡收盡，數數看誰得最多。"]', '["紅燭台前出翠娥，海沙鋪局巧相和。","趂行移手巡收尽，數數看誰得最多。"]', '诗', 'shi', '', NULL, '美人宮棊 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53151f8d-1ea9-4c74-8681-a93760003b9c', '蠻州', '蠻州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["瘴水蠻中入洞流，人家多住竹棚頭。","一山海上無城郭，唯見松牌記象州。"]', '["瘴水蠻中入洞流，人家多住竹棚头。","一山海上無城郭，唯见松牌記象州。"]', '诗', 'shi', '', NULL, '蠻州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a149d59f-edb5-4ce1-9ace-cfe23be399f8', '送元宗簡', '送元宗簡', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["貂帽垂肩窄皂裘，雪深騎馬向西州。","暫時相見還相送，却閉閑門依舊愁。"]', '["貂帽垂肩窄皂裘，雪深騎马向西州。","暫时相见還相送，却閉闲门依旧愁。"]', '诗', 'shi', '', NULL, '送元宗簡 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4ff8d39-cbac-431a-aaac-f12a80f1f99c', '寄徐晦', '寄徐晦', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鄠陂魚美酒偏濃，不出琴齋見雪峰。","應勝昨來趨府日，簿書牀上亂重重。"]', '["鄠陂鱼美酒偏濃，不出琴斋见雪峰。","應勝昨来趨府日，簿书牀上亂重重。"]', '诗', 'shi', '', NULL, '寄徐晦 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5951cc09-83ca-4e54-83dd-97bedbce2d78', '寄白學士', '寄白学士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["自掌天書見客稀，縱因休沐鎖雙扉。","幾回扶病欲相訪，知向禁中歸未歸。"]', '["自掌天书见客稀，縱因休沐鎖雙扉。","幾回扶病欲相訪，知向禁中归未归。"]', '诗', 'shi', '', NULL, '寄白學士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58a7e4bd-15de-4126-a91c-de9562694ce8', '喜王六同宿', '喜王六同宿', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["十八年來恨別離，唯同一宿詠新詩。","更相借問詩中語，共說如今勝舊時。"]', '["十八年来恨別離，唯同一宿詠新诗。","更相借问诗中語，共说如今勝旧时。"]', '诗', 'shi', '', NULL, '喜王六同宿 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f67bc3-4e10-4e03-8bb7-903cfa77c55e', '題玉像堂', '題玉像堂', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["玉毫不着世間塵，輝相分明十八身。","入夜無煙燈更好，堂中唯有轉經人。"]', '["玉毫不着世间塵，輝相分明十八身。","入夜無煙灯更好，堂中唯有轉經人。"]', '诗', 'shi', '', NULL, '題玉像堂 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ac10c96-2565-49a8-8d9c-c7a8e00a6bfd', '與賈島閑遊', '與賈島闲游', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["水北原南草色新，雪消風暖不生塵。","城中車馬應無數，能解閑行有幾人。"]', '["水北原南草色新，雪消风暖不生塵。","城中车马應無數，能解闲行有幾人。"]', '诗', 'shi', '', NULL, '與賈島閑遊 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1708826e-98b4-46c1-b549-e7fef08b274a', '哭丘長史', '哭丘长史', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["丘公已歿故人稀，欲過街西更訪誰。","每到子城東路上，憶君相逐入朝時。"]', '["丘公已歿故人稀，欲過街西更訪誰。","每到子城东路上，憶君相逐入朝时。"]', '诗', 'shi', '', NULL, '哭丘長史 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('001fb373-42bc-4183-b801-4bd6fbd0ced2', '哭孟寂', '哭孟寂', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["曲江院裏題名處，十九人中最少年。","今日春光君不見，杏花零落寺門前。"]', '["曲江院裏題名处，十九人中最少年。","今日春光君不见，杏花零落寺门前。"]', '诗', 'shi', '', NULL, '哭孟寂 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37b86718-b55e-4d15-a925-35fd808661f5', '患眼', '患眼', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["三年患眼今年[校]，[免]與風光便隔生。","昨日韓家後園裏，看花猶似未分明。"]', '["三年患眼今年[校]，[免]與风光便隔生。","昨日韓家後园裏，看花猶似未分明。"]', '诗', 'shi', '', NULL, '患眼 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21f79e41-e677-4b23-851f-3d0ef6bd5c23', '答劉競', '答劉競', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["劉君久被時拋擲，老向城中作選人。","昨日街西相近住，每來存問老夫身。"]', '["劉君久被时拋擲，老向城中作選人。","昨日街西相近住，每来存问老夫身。"]', '诗', 'shi', '', NULL, '答劉競 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b28f476-519a-4f0f-bd77-5ebc5c080eb0', '贈華嚴院僧', '贈华嚴院僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["一身依止荒閑院，燭耀窗中有宿煙。","徧禮華嚴經裏字，不曾行到寺門前。"]', '["一身依止荒闲院，燭耀窗中有宿煙。","徧禮华嚴經裏字，不曾行到寺门前。"]', '诗', 'shi', '', NULL, '贈華嚴院僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbd2b5f0-bdcd-4cf6-a824-32cdc7ed6eaf', '逢故人', '逢故人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["山東一十餘年別，今日相逢在上都。","說盡向來無限事，相看摩捋白髭鬚。"]', '["山东一十餘年別，今日相逢在上都。","说尽向来無限事，相看摩捋白髭鬚。"]', '诗', 'shi', '', NULL, '逢故人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3df800a-ab93-4401-be88-6de07067e8d5', '送蕭遠弟', '送蕭远弟', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["街北槐花傍馬垂，病身相送出門遲。","與君別後秋風夜，作得新詩說向誰。"]', '["街北槐花傍马垂，病身相送出门遲。","與君別後秋风夜，作得新诗说向誰。"]', '诗', 'shi', '', NULL, '送蕭遠弟 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7043fe9-514d-4931-9dc0-66be822cdc76', '送辛少府任樂安', '送辛少府任乐安', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["才多不肯浪容身，老大詩章轉更新。","選得天台山下住，一家全作學仙人。"]', '["才多不肯浪容身，老大诗章轉更新。","選得天台山下住，一家全作学仙人。"]', '诗', 'shi', '', NULL, '送辛少府任樂安 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a57e93-7560-4156-8e99-d34e36ef8ade', '贈任道人', '贈任道人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["長安多病無生計，藥鋪醫人亂索錢。","欲得定知身上事，憑君爲算小行年。"]', '["长安多病無生計，藥鋪醫人亂索錢。","欲得定知身上事，憑君爲算小行年。"]', '诗', 'shi', '', NULL, '贈任道人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47ee7083-94cd-4830-be32-c2288e68642e', '招周居士', '招周居士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["閉門秋雨濕墙莎，俗客來稀野思多。","已掃書齋安藥竈，山人作意早經過。"]', '["閉门秋雨濕墙莎，俗客来稀野思多。","已掃书斋安藥竈，山人作意早經過。"]', '诗', 'shi', '', NULL, '招周居士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8be94615-01f2-4bec-a310-10374fa3b6d0', '送許處士', '送許处士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["高情自與俗人疎，獨向藍溪選僻居。","會到白雲長取醉，不能窗下讀閑書。"]', '["高情自與俗人疎，独向藍溪選僻居。","會到白云长取醉，不能窗下读闲书。"]', '诗', 'shi', '', NULL, '送許處士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dce86802-daf7-44d1-9f88-35ae33c96877', '送律師歸婺州', '送律師归婺州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["京中開講已多時，曾作壇頭證戒師。","歸到雙溪橋北寺，鄉僧爭就學威儀。"]', '["京中开講已多时，曾作壇头證戒師。","归到雙溪橋北寺，乡僧爭就学威儀。"]', '诗', 'shi', '', NULL, '送律師歸婺州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72f904c4-5ff2-419a-b3a4-b96dcc2b89cc', '題楊秘書新居', '題楊秘书新居', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["愛閑不向爭名地，宅在街西最靜坊。","卷裏詩過一千首，白頭新受秘書郎。"]', '["愛闲不向爭名地，宅在街西最静坊。","卷裏诗過一千首，白头新受秘书郎。"]', '诗', 'shi', '', NULL, '題楊秘書新居 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55839370-dff8-405f-a7fa-38486feffa91', '送晊師', '送晊師', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["九星臺下煎茶別，五老峰頭覓寺居。","作得新詩旋相寄，人來請莫達空書。"]', '["九星台下煎茶別，五老峰头覓寺居。","作得新诗旋相寄，人来請莫達空书。"]', '诗', 'shi', '', NULL, '送晊師 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ee3ee4d-af63-4945-9560-930b01e3a510', '送僧往金州', '送僧往金州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["聞道谿陰山水好，師行一一徧經過。","事須覓取堪居處，若箇溪頭藥最多。"]', '["闻道谿陰山水好，師行一一徧經過。","事須覓取堪居处，若箇溪头藥最多。"]', '诗', 'shi', '', NULL, '送僧往金州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfc14bee-9fa0-4706-b0fc-380d3562d90b', '尋徐道士', '尋徐道士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["尋師遠到暉天觀，竹院森森閉藥房。","聞入靜來經七日，仙童簷下獨焚香。"]', '["尋師远到暉天观，竹院森森閉藥房。","闻入静来經七日，仙童簷下独焚香。"]', '诗', 'shi', '', NULL, '尋徐道士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5224101-9e0a-4bc9-8945-5c4779ca04d2', '答開州韋使君寄車前子', '答开州韋使君寄车前子', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["開州午日車前子，作藥人皆道有神。","慙愧使君憐病眼，三千餘里寄閑人。"]', '["开州午日车前子，作藥人皆道有神。","慙愧使君怜病眼，三千餘里寄闲人。"]', '诗', 'shi', '', NULL, '答開州韋使君寄車前子 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3bfb43c-eae3-43dc-9864-195d236b1cfe', '憶故州', '憶故州', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["壘石爲山伴野夫，自收靈藥讀仙書。","如今身是他州客，每見青山憶舊居。"]', '["壘石爲山伴野夫，自收靈藥读仙书。","如今身是他州客，每见青山憶旧居。"]', '诗', 'shi', '', NULL, '憶故州 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8649844-a2b5-4db0-8cd9-3bacebecb233', '送客遊蜀', '送客游蜀', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["行盡青山到益州，錦城樓下二江流。","杜家曾向此中住，爲到浣花溪水頭。"]', '["行尽青山到益州，錦城楼下二江流。","杜家曾向此中住，爲到浣花溪水头。"]', '诗', 'shi', '', NULL, '送客遊蜀 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aebe5864-0507-4a19-b7f2-e40929e7c98c', '送陸暢', '送陸暢', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["共踏長安街裏塵，吳州獨作未歸身。","昔年舊宅今誰住，君過西塘與問人。"]', '["共踏长安街裏塵，吳州独作未归身。","昔年旧宅今誰住，君過西塘與问人。"]', '诗', 'shi', '', NULL, '送陸暢 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae0b6631-6a2b-478c-9f05-a8c1f2899e81', '感春', '感春', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["遠客悠悠任病身，謝家池上又逢春。","明年各自東西去，此地看花是別人。"]', '["远客悠悠任病身，謝家池上又逢春。","明年各自东西去，此地看花是別人。"]', '诗', 'shi', '', NULL, '感春 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b1d427-649a-4860-aa54-589b206d13aa', '贈李司議', '贈李司議', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["漢庭誰問投荒客，十載天南着白衣。","秋草茫茫惡谿路，嶺頭遙送北人稀。"]', '["漢庭誰问投荒客，十載天南着白衣。","秋草茫茫惡谿路，嶺头遙送北人稀。"]', '诗', 'shi', '', NULL, '贈李司議 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29dcc03b-5647-471d-893c-0a9cbc225dcd', '別客', '別客', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["青山歷歷水悠悠，今日相逢明日秋。","繫馬城邊楊柳樹，爲君沽酒暫淹留。"]', '["青山歷歷水悠悠，今日相逢明日秋。","繫马城邊楊柳樹，爲君沽酒暫淹留。"]', '诗', 'shi', '', NULL, '別客 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fd2d72d-8fde-4406-8ed9-b8eeb91995e5', '登樓寄胡家兄弟', '登楼寄胡家兄弟', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["獨上西樓盡日閑，林煙演漾鳥蠻蠻。","謝家兄弟重城裏，不得同看雨後山。"]', '["独上西楼尽日闲，林煙演漾鸟蠻蠻。","謝家兄弟重城裏，不得同看雨後山。"]', '诗', 'shi', '', NULL, '登樓寄胡家兄弟 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab2c0eb-e8e5-4b84-bf00-60a49887ac0c', '答劉明府', '答劉明府', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["身病多時又客居，滿城親舊盡相疎。","可憐絳縣劉明府，猶解頻頻寄遠書。"]', '["身病多时又客居，满城親旧尽相疎。","可怜絳縣劉明府，猶解頻頻寄远书。"]', '诗', 'shi', '', NULL, '答劉明府 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ecd41f12-a61f-4c5e-8cce-5289695e52d3', '酬藤杖', '酬藤杖', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["病裏出門行步遲，喜君相贈古藤枝。","倚來自覺身生力，每向傍人說得時。"]', '["病裏出门行步遲，喜君相贈古藤枝。","倚来自覺身生力，每向傍人说得时。"]', '诗', 'shi', '', NULL, '酬藤杖 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42a7ef88-90f5-4f79-abbf-bf05bd87bc9e', '法雄寺東樓', '法雄寺东楼', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["汾陽舊宅今爲寺，猶有當時歌舞樓。","四十年來車馬絕，古槐深巷暮蟬愁。"]', '["汾陽旧宅今爲寺，猶有當时歌舞楼。","四十年来车马絕，古槐深巷暮蟬愁。"]', '诗', 'shi', '', NULL, '法雄寺東樓 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ec7646c-d08e-40af-8557-f9530dfacd43', '寄故人', '寄故人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["靜曲閑房病客居，蟬聲滿樹槿花疎。","故人祗在藍田縣，強半年來未得書。"]', '["静曲闲房病客居，蟬声满樹槿花疎。","故人祗在藍田縣，強半年来未得书。"]', '诗', 'shi', '', NULL, '寄故人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31bbcbd6-e531-470f-92ec-915fa97ce639', '鄰婦哭征夫', '鄰婦哭征夫', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["雙鬟初合便分離，萬里征夫不得隨。","今日軍回身獨歿，去時鞍馬別人騎。"]', '["雙鬟初合便分離，万里征夫不得隨。","今日軍回身独歿，去时鞍马別人騎。"]', '诗', 'shi', '', NULL, '鄰婦哭征夫 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5388a4b-7457-4f76-826c-ffed2a8ec779', '和崔駙馬聞蟬', '和崔駙马闻蟬', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鳳凰樓下多歡樂，不覺秋風暮雨天。","應爲昨來身暫病，蟬聲得到耳傍邊。"]', '["鳳凰楼下多歡乐，不覺秋风暮雨天。","應爲昨来身暫病，蟬声得到耳傍邊。"]', '诗', 'shi', '', NULL, '和崔駙馬聞蟬 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('badab31e-682c-4658-9a2e-cb2b13e317f0', '和裴僕射看櫻桃花', '和裴僕射看櫻桃花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["昨日南園新雨後，櫻桃花發舊枝柯。","天明不待人同看，遶樹重重履跡多。"]', '["昨日南园新雨後，櫻桃花發旧枝柯。","天明不待人同看，遶樹重重履跡多。"]', '诗', 'shi', '', NULL, '和裴僕射看櫻桃花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c499a93-bbd0-406b-a428-7bfe13f77626', '和長安郭明府與友人縣中會飲', '和长安郭明府與友人縣中會饮', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["一尊清酒兩人同，好在街西水縣中。","自恨病身相去遠，此時閑坐對秋風。"]', '["一尊清酒兩人同，好在街西水縣中。","自恨病身相去远，此时闲坐对秋风。"]', '诗', 'shi', '', NULL, '和長安郭明府與友人縣中會飲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('833f4a39-0f62-420f-8033-870d5e243d7e', '唐昌觀看花', '唐昌观看花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["新紅舊紫不相宜，看覺從前兩月遲。","更向同來詩客道，明年到此莫過時。"]', '["新紅旧紫不相宜，看覺從前兩月遲。","更向同来诗客道，明年到此莫過时。"]', '诗', 'shi', '', NULL, '唐昌觀看花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ccf17af-4e7a-46c0-826b-657b84f20989', '九華觀看花', '九华观看花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["街西無數閑遊處，不似九華仙觀中。","花裏可憐池上景，幾重墻壁貯春風。"]', '["街西無數闲游处，不似九华仙观中。","花裏可怜池上景，幾重墻壁貯春风。"]', '诗', 'shi', '', NULL, '九華觀看花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa49873e-d6a9-4a2b-87f0-b9b3fb310b20', '贈姚合', '贈姚合', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["丹鳳城門向曉開，千官相次入朝來。","唯君獨走衝塵土，下馬橋邊報直迴。"]', '["丹鳳城门向晓开，千官相次入朝来。","唯君独走衝塵土，下马橋邊報直迴。"]', '诗', 'shi', '', NULL, '贈姚合 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('163ddb38-3261-4fbd-acd1-71705cb54341', '同韋員外開元觀尋時道士', '同韋員外开元观尋时道士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["觀裏初晴竹樹涼，閑行共到最高房。","昨來官罷無生計，欲就師求斷穀方。"]', '["观裏初晴竹樹涼，闲行共到最高房。","昨来官罷無生計，欲就師求斷穀方。"]', '诗', 'shi', '', NULL, '同韋員外開元觀尋時道士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe71226b-16c1-4d10-9241-ef9b61690cc5', '同韓侍御南溪夜賞', '同韓侍御南溪夜賞', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["喜作閑人得出城，南溪兩月逐君行。","忽聞新命須歸去，一夜船中語到明。"]', '["喜作闲人得出城，南溪兩月逐君行。","忽闻新命須归去，一夜船中語到明。"]', '诗', 'shi', '', NULL, '同韓侍御南溪夜賞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad2e7334-362c-4ba1-bc63-941fff9c1ddf', '使行望悟真寺', '使行望悟真寺', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["採玉峰連佛寺幽，高高斜對驛門樓。","無端來去騎官馬，寸步教身不得遊。"]', '["採玉峰連佛寺幽，高高斜对驛门楼。","無端来去騎官马，寸步教身不得游。"]', '诗', 'shi', '', NULL, '使行望悟真寺 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1da2720d-861f-482d-9931-e61480f4498c', '重陽日至峽道', '重陽日至峽道', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["無限青山行已盡，迴看忽覺遠離家。","逢高欲飲重陽酒，山菊今朝未有花。"]', '["無限青山行已尽，迴看忽覺远離家。","逢高欲饮重陽酒，山菊今朝未有花。"]', '诗', 'shi', '', NULL, '重陽日至峽道 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdca1529-ac5a-4830-a908-e5b1789174c3', '贈主客劉郎中', '贈主客劉郎中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["憶昔君登南省日，老夫猶是褐衣身。","誰知二十餘年後，來作客曹相替人。"]', '["憶昔君登南省日，老夫猶是褐衣身。","誰知二十餘年後，来作客曹相替人。"]', '诗', 'shi', '', NULL, '贈主客劉郎中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d7646fe-985e-4673-a554-61497dd86c8c', '同嚴給事聞唐昌觀玉蘂近有仙過因成絕句二首 一', '同嚴給事闻唐昌观玉蘂近有仙過因成絕句二首 一', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["千枝花裏玉塵飛，阿母宮中見亦稀。","應共諸仙鬬百草，獨來偷得一枝歸。"]', '["千枝花裏玉塵飞，阿母宮中见亦稀。","應共諸仙鬬百草，独来偷得一枝归。"]', '诗', 'shi', '', NULL, '同嚴給事聞唐昌觀玉蘂近有仙過因成絕句二首 一 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65e884d8-cf9f-4275-ae15-f6063d2eaf63', '同嚴給事聞唐昌觀玉蘂近有仙過因成絕句二首 二', '同嚴給事闻唐昌观玉蘂近有仙過因成絕句二首 二', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["九色雲中紫鳳車，尋仙來到洞仙家。","飛輪迴處無踪跡，唯有斑斑滿地花。"]', '["九色云中紫鳳车，尋仙来到洞仙家。","飞輪迴处無踪跡，唯有斑斑满地花。"]', '诗', 'shi', '', NULL, '同嚴給事聞唐昌觀玉蘂近有仙過因成絕句二首 二 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7191c0c6-7b3a-47cb-9fe6-1ef51857319a', '秋思', '秋思', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["洛陽城裏見秋風，欲作歸書意萬重。","忽恐匆匆說不盡，行人臨發又開封。"]', '["洛陽城裏见秋风，欲作归书意万重。","忽恐匆匆说不尽，行人臨發又开封。"]', '诗', 'shi', '', NULL, '秋思 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4488fc89-5956-4d50-8312-544f7126e8b4', '憶遠', '憶远', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["行人猶未有歸期，萬里初程日暮時。","唯愛門前雙柳樹，枝枝葉葉不相離。"]', '["行人猶未有归期，万里初程日暮时。","唯愛门前雙柳樹，枝枝葉葉不相離。"]', '诗', 'shi', '', NULL, '憶遠 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1454d2df-ace5-4fce-8b72-1a5cb201b937', '玉仙館', '玉仙館', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["長溪新雨色如泥，野水陰雲盡向西。","楚客天南行漸遠，山山樹裏鷓鴣啼。"]', '["长溪新雨色如泥，野水陰云尽向西。","楚客天南行漸远，山山樹裏鷓鴣啼。"]', '诗', 'shi', '', NULL, '玉仙館 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('230fbb94-0120-432a-a422-117f5b69dfbc', '寄府吏', '寄府吏', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["野外尋花共作期，今朝出郭不相隨。","待君公事有閑日，此地春風應過時。"]', '["野外尋花共作期，今朝出郭不相隨。","待君公事有闲日，此地春风應過时。"]', '诗', 'shi', '', NULL, '寄府吏 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d7026ad-92ab-4b60-98bb-4543b8253ca0', '弟蕭遠雪夜同宿', '弟蕭远雪夜同宿', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["數卷新遊蜀客詩，長安僻巷得相隨。","草堂雪夜攜琴宿，說是青城館裏時。"]', '["數卷新游蜀客诗，长安僻巷得相隨。","草堂雪夜携琴宿，说是青城館裏时。"]', '诗', 'shi', '', NULL, '弟蕭遠雪夜同宿 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d5cfc9c-9522-44de-9c4b-17c73394212a', '涼州詞三首 一', '涼州词三首 一', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["邊城暮雨雁飛低，蘆笋初生漸欲齊。","無數鈴聲遙過磧，應馱白練到安西。"]', '["邊城暮雨雁飞低，蘆笋初生漸欲齊。","無數鈴声遙過磧，應馱白練到安西。"]', '诗', 'shi', '', NULL, '涼州詞三首 一 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5743da4b-cc5b-4855-b622-30cd00c34f50', '涼州詞三首 二', '涼州词三首 二', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["古鎮城門白磧開，胡兵往往傍沙堆。","巡邊使客行應早，欲問平安無使來。"]', '["古鎮城门白磧开，胡兵往往傍沙堆。","巡邊使客行應早，欲问平安無使来。"]', '诗', 'shi', '', NULL, '涼州詞三首 二 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41b2a7ad-b60f-46aa-b9a0-42535c232763', '涼州詞三首 三', '涼州词三首 三', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["鳳林關裏水東流，白草黃榆六十秋。","邊將皆承主恩澤，無人解道取涼州。"]', '["鳳林关裏水东流，白草黄榆六十秋。","邊將皆承主恩澤，無人解道取涼州。"]', '诗', 'shi', '', NULL, '涼州詞三首 三 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95afc3cc-485b-4b1d-b502-d283840537d2', '宮詞 一', '宮词 一', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["新鷹初放兔猶肥，白日君王在內稀。","薄暮千門臨欲鎖，紅妝飛騎向前歸。"]', '["新鷹初放兔猶肥，白日君王在內稀。","薄暮千门臨欲鎖，紅妝飞騎向前归。"]', '诗', 'shi', '', NULL, '宮詞 一 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac0ef485-8298-4910-92e3-45c941babf93', '宮詞 二', '宮词 二', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["黃金捍撥紫檀槽，弦索初張調更高。","盡理昨來新上曲，內官簾外送櫻桃。"]', '["黄金捍撥紫檀槽，弦索初張調更高。","尽理昨来新上曲，內官簾外送櫻桃。"]', '诗', 'shi', '', NULL, '宮詞 二 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40de74da-142d-4202-8d42-6538736cd361', '華清宮', '华清宮', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["溫泉流入漢離宮，宮樹行行浴殿空。","武帝時人今欲盡，青山空閉御墻中。"]', '["溫泉流入漢離宮，宮樹行行浴殿空。","武帝时人今欲尽，青山空閉御墻中。"]', '诗', 'shi', '', NULL, '華清宮 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d60258ad-0f56-472e-b6f1-eae37b98766d', '崔駙馬養鶴', '崔駙马養鹤', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["身閑無事稱高情，已有人間章句名。","求得鶴來教翦翅，望仙臺下亦將行。"]', '["身闲無事稱高情，已有人间章句名。","求得鹤来教翦翅，望仙台下亦將行。"]', '诗', 'shi', '', NULL, '崔駙馬養鶴 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7818efd-615f-4df7-bd23-3cfefcba3cdc', '閑遊', '闲游', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["老身不計人間事，野寺秋晴每獨過。","病眼校來猶斷酒，却嫌行處菊花多。"]', '["老身不計人间事，野寺秋晴每独過。","病眼校来猶斷酒，却嫌行处菊花多。"]', '诗', 'shi', '', NULL, '閑遊 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36f49c2a-a1fd-4807-8073-506b7e1e75c9', '劉兵曹贈酒', '劉兵曹贈酒', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["一缾顏色似甘泉，閑向新栽小竹前。","飲罷身中更無事，移牀獨就夕陽眠。"]', '["一缾顏色似甘泉，闲向新栽小竹前。","饮罷身中更無事，移牀独就夕陽眠。"]', '诗', 'shi', '', NULL, '劉兵曹贈酒 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c4cde49-4616-4258-b780-f8ac5f8a8627', '送梧州王使君', '送梧州王使君', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["楚江亭上秋風起，看發蒼梧太守船。","千里同行從此別，相逢又隔幾多年。"]', '["楚江亭上秋风起，看發蒼梧太守船。","千里同行從此別，相逢又隔幾多年。"]', '诗', 'shi', '', NULL, '送梧州王使君 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce70861d-2ec3-4224-a989-c20b98b7c2c9', '春日早朝', '春日早朝', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["曉陌春寒朝騎來，瑞雲深處見樓臺。","夜來新雨沙堤濕，東上閤門應未開。"]', '["晓陌春寒朝騎来，瑞云深处见楼台。","夜来新雨沙堤濕，东上閤门應未开。"]', '诗', 'shi', '', NULL, '春日早朝 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('037c9bcb-a457-4c3d-b359-048dda1f23bc', '寄朱闞二山人', '寄朱闞二山人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["爲箇朝章束此身，眼看東路去無因。","歷陽舊客今應少，轉憶鄰家二老人。"]', '["爲箇朝章束此身，眼看东路去無因。","歷陽旧客今應少，轉憶鄰家二老人。"]', '诗', 'shi', '', NULL, '寄朱闞二山人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e074a5f-78d4-4d05-a248-c872831c493e', '寄李渤', '寄李渤', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["五度溪頭躑躅紅，嵩陽寺裏講時鐘。","春山處處行應好，一月看花到幾峰。"]', '["五度溪头躑躅紅，嵩陽寺裏講时鐘。","春山处处行應好，一月看花到幾峰。"]', '诗', 'shi', '', NULL, '寄李渤 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f0e76c3-fa01-4082-b01c-3a1193ff7e06', '尋仙', '尋仙', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["溪頭一徑入青崖，處處仙居隔杏花。","更見峰西幽客說，雲中猶有兩三家。"]', '["溪头一徑入青崖，处处仙居隔杏花。","更见峰西幽客说，云中猶有兩三家。"]', '诗', 'shi', '', NULL, '尋仙 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2742f3ef-4b79-44df-878f-bd61b8ff829c', '同白侍郎杏園贈劉郎中', '同白侍郎杏园贈劉郎中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["一去瀟湘頭欲白，今朝始見杏花春。","從來遷客應無數，重到花前有幾人。"]', '["一去瀟湘头欲白，今朝始见杏花春。","從来遷客應無數，重到花前有幾人。"]', '诗', 'shi', '', NULL, '同白侍郎杏園贈劉郎中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0cbb0bd-9129-48c9-aef6-c116139328cc', '答鄱陽客藥名詩', '答鄱陽客藥名诗', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["江臯歲暮相逢地，黃葉霜前半夏枝。","子夜吟詩向松桂，心中萬事喜君知。"]', '["江臯歲暮相逢地，黄葉霜前半夏枝。","子夜吟诗向松桂，心中万事喜君知。"]', '诗', 'shi', '', NULL, '答鄱陽客藥名詩 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c5a58a3-f22f-47e5-b9e5-02d48242cbf9', '寄宋景', '寄宋景', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["詔發官兵取亂臣，將軍弓箭不離身。","今君獨在征東府，莫遣功名屬別人。"]', '["詔發官兵取亂臣，將軍弓箭不離身。","今君独在征东府，莫遣功名屬別人。"]', '诗', 'shi', '', NULL, '寄宋景 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('afb264e3-d77f-4320-8a74-99504f66893a', '寄王侍御', '寄王侍御', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["愛君紫閣峰前好，新作書堂藥竈成。","見欲移居相近住，有田多與種黃精。"]', '["愛君紫閣峰前好，新作书堂藥竈成。","见欲移居相近住，有田多與種黄精。"]', '诗', 'shi', '', NULL, '寄王侍御 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec0d936d-5d2c-4923-92df-40f89286341c', '題渭北寺上方', '題渭北寺上方', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["昔祭郊壇今謁陵，寺中高處最來登。","十餘年後人多別，喜見當時轉讀僧。"]', '["昔祭郊壇今謁陵，寺中高处最来登。","十餘年後人多別，喜见當时轉读僧。"]', '诗', 'shi', '', NULL, '題渭北寺上方 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('555ea1b6-606e-4ff9-80f2-d1d1daf76166', '閑遊', '闲游', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["終日不離塵土間，若爲能見此身閑。","今朝暫共遊僧語，更恨趨時別舊山。"]', '["終日不離塵土间，若爲能见此身闲。","今朝暫共游僧語，更恨趨时別旧山。"]', '诗', 'shi', '', NULL, '閑遊 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e79f014-6170-4b01-b3cb-c6044a6a989a', '倡女詞', '倡女词', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["輕鬢叢梳闊掃眉，爲嫌風日下樓稀。","畫羅金縷難相稱，故著尋常淡薄衣。"]', '["轻鬢叢梳闊掃眉，爲嫌风日下楼稀。","畫羅金縷难相稱，故著尋常淡薄衣。"]', '诗', 'shi', '', NULL, '倡女詞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a15c396-5516-4577-958b-53df6a5b5bd2', '答元八遺紗帽', '答元八遺紗帽', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["黑紗方帽君邊得，稱對山前坐竹牀。","唯恐被人偷剪樣，不曾閑戴出書堂。"]', '["黑紗方帽君邊得，稱对山前坐竹牀。","唯恐被人偷剪樣，不曾闲戴出书堂。"]', '诗', 'shi', '', NULL, '答元八遺紗帽 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69245aca-a305-47b1-9fb5-79c1302ce84e', '題僧院', '題僧院', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["聞師行講青龍疏，本寺住來多少年。","靜掃空房唯獨坐，千莖秋竹在簷前。"]', '["闻師行講青龙疏，本寺住来多少年。","静掃空房唯独坐，千莖秋竹在簷前。"]', '诗', 'shi', '', NULL, '題僧院 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d0527b-5364-47a7-976b-dd87c9997d71', '送元八', '送元八', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["百神齋祭相隨徧，尋竹看山亦共行。","明日城西送君去，舊遊重到獨題名。"]', '["百神斋祭相隨徧，尋竹看山亦共行。","明日城西送君去，旧游重到独題名。"]', '诗', 'shi', '', NULL, '送元八 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ddfd5e0-60cd-4227-b9fe-fc44ebf1bbde', '吳楚歌詞', '吳楚歌词', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["庭前春鳥啄林聲，紅夾羅襦縫未成。","今朝社日停針線，起向朱櫻樹下行。"]', '["庭前春鸟啄林声，紅夾羅襦縫未成。","今朝社日停針線，起向朱櫻樹下行。"]', '诗', 'shi', '', NULL, '吳楚歌詞 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a3efde-7272-4f8c-a71a-9ae10f8d1e35', '題方睦上人月臺觀', '題方睦上人月台观', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["一身清淨無童子，獨坐空堂得幾年。","每夜焚香通月觀，可鄰光影最團圓。"]', '["一身清淨無童子，独坐空堂得幾年。","每夜焚香通月观，可鄰光影最團圓。"]', '诗', 'shi', '', NULL, '題方睦上人月臺觀 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ee1fe66-9b60-4913-81e0-1df1f3ea8f01', '華山廟', '华山廟', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["金天廟下西京道，巫女紛紛走似煙。","手把紙錢迎過客，遣求恩福到神前。"]', '["金天廟下西京道，巫女紛紛走似煙。","手把紙錢迎過客，遣求恩福到神前。"]', '诗', 'shi', '', NULL, '華山廟 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa48fb92-fea1-4a20-8fca-3e9559f217bf', '病中酬元宗簡', '病中酬元宗簡', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["東風漸暖滿城春，獨占幽居養病身。","莫說櫻桃花已發，今年不作看花人。"]', '["东风漸暖满城春，独占幽居養病身。","莫说櫻桃花已發，今年不作看花人。"]', '诗', 'shi', '', NULL, '病中酬元宗簡 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f80bc0e-6754-4b32-86a7-c1bd53306e8d', '寺宿齋', '寺宿斋', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["晚到金光門外寺，寺中新竹隔簾多。","齋官禁與僧相見，院院開門不得過。"]', '["晚到金光门外寺，寺中新竹隔簾多。","斋官禁與僧相见，院院开门不得過。"]', '诗', 'shi', '', NULL, '寺宿齋 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ede77c0-4b3e-46d1-b196-bf7894fb10b9', '贈施肩吾', '贈施肩吾', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["世間漸覺無多事，雖有空名未著身。","合取藥成相待喫，不須先作上天人。"]', '["世间漸覺無多事，雖有空名未著身。","合取藥成相待喫，不須先作上天人。"]', '诗', 'shi', '', NULL, '贈施肩吾 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5d817cf-5bc3-489c-a7a0-3c8579c679bd', '贈王建', '贈王建', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["白君去後交遊少，東野亡來篋笥貧。","賴有白頭王建在，眼前猶見詠詩人。"]', '["白君去後交游少，东野亡来篋笥貧。","賴有白头王建在，眼前猶见詠诗人。"]', '诗', 'shi', '', NULL, '贈王建 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2a58a7a-bed8-4d97-9c8f-7632cd235987', '逢賈島', '逢賈島', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["僧房逢着欵冬花，出寺行吟日已斜。","十二街中春雪遍，馬蹄今去入誰家。"]', '["僧房逢着欵冬花，出寺行吟日已斜。","十二街中春雪遍，马蹄今去入誰家。"]', '诗', 'shi', '', NULL, '逢賈島 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('042adab4-fd33-403a-81fb-9facc9416757', '山中酬人', '山中酬人', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["山中日暖春鳩鳴，逐水看花任意行。","向晚歸來石窗下，菖蒲葉上見題名。"]', '["山中日暖春鳩鳴，逐水看花任意行。","向晚归来石窗下，菖蒲葉上见題名。"]', '诗', 'shi', '', NULL, '山中酬人 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02e21292-cdf8-45b7-b793-e4dc228be4fa', '弱栢院僧影堂', '弱栢院僧影堂', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["弱栢倒垂如線蔓，簷頭不見有枝柯。","影堂香火長相續，應得人來禮拜多。"]', '["弱栢倒垂如線蔓，簷头不见有枝柯。","影堂香火长相續，應得人来禮拜多。"]', '诗', 'shi', '', NULL, '弱栢院僧影堂 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e979ddc0-7d65-46c3-bb3a-10a65869481c', '題故僧影堂', '題故僧影堂', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["香消雲鎖舊僧家，僧剎殘形半壁斜。","日暮松煙寒漠漠，秋風吹破紙蓮花。"]', '["香消云鎖旧僧家，僧剎殘形半壁斜。","日暮松煙寒漠漠，秋风吹破紙蓮花。"]', '诗', 'shi', '', NULL, '題故僧影堂 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2356f0-cb33-4b72-8cd1-6d45df9976a3', '無題', '無題', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["桃溪柳陌好經過，燈下妝成月下歌。","爲是襄王故宮地，至今猶有細腰多。"]', '["桃溪柳陌好經過，灯下妝成月下歌。","爲是襄王故宮地，至今猶有細腰多。"]', '诗', 'shi', '', NULL, '無題 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('437d4117-56b3-48e0-ac38-a24e4b01a0a4', '山禽', '山禽', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["山禽毛如白練帶，栖我庭前栗樹枝。","獮猴半夜來取栗，一雙中林向月飛。"]', '["山禽毛如白練带，栖我庭前栗樹枝。","獮猴半夜来取栗，一雙中林向月飞。"]', '诗', 'shi', '', NULL, '山禽 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b1e24a6-7cad-411b-8da6-e8e77713a608', '秋山', '秋山', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋山無雲復無風，溪頭看月出深松。","草堂不閉石牀靜，葉間墜露聲重重。"]', '["秋山無云复無风，溪头看月出深松。","草堂不閉石牀静，葉间墜露声重重。"]', '诗', 'shi', '', NULL, '秋山 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31e6512c-2261-4dfa-9963-7c5fa2bb2f10', '玉真觀', '玉真观', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["臺殿曾爲貴主家，春風吹盡竹窗紗。","院中仙女脩香火，不許閑人入看花。"]', '["台殿曾爲貴主家，春风吹尽竹窗紗。","院中仙女脩香火，不許闲人入看花。"]', '诗', 'shi', '', NULL, '玉真觀 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40dbacae-77ed-446d-bd71-8d917ceac572', '蠻中', '蠻中', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["銅柱南邊毒草春，行人幾日到金麟。","玉鐶穿耳誰家女，自抱琵琶迎海神。"]', '["銅柱南邊毒草春，行人幾日到金麟。","玉鐶穿耳誰家女，自抱琵琶迎海神。"]', '诗', 'shi', '', NULL, '蠻中 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e87c9c65-0c5b-4f40-9d65-051899546e23', '贈道士', '贈道士', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["茅山近別剡溪逢，玉節青旄十二重。","自說年年上天去，羅浮最近海邊峰。"]', '["茅山近別剡溪逢，玉節青旄十二重。","自说年年上天去，羅浮最近海邊峰。"]', '诗', 'shi', '', NULL, '贈道士 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f69298b8-1c08-4839-9f42-e38104f153ec', '重平驛作', '重平驛作', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["茫茫菰草平如地，渺渺長堤曲似城。","日暮未知投宿處，逢人更問向前程。"]', '["茫茫菰草平如地，渺渺长堤曲似城。","日暮未知投宿处，逢人更问向前程。"]', '诗', 'shi', '', NULL, '重平驛作 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89d241bf-37ef-4ce6-9230-1354cb508faa', '宿天竺寺寄靈隱寺僧', '宿天竺寺寄靈隐寺僧', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["夜向靈溪息此身，風泉竹露淨衣塵。","月明石上堪同宿，那作山南山北人。"]', '["夜向靈溪息此身，风泉竹露淨衣塵。","月明石上堪同宿，那作山南山北人。"]', '诗', 'shi', '', NULL, '宿天竺寺寄靈隱寺僧 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98737665-5fb0-4215-95cf-2c90cb4fb547', '酬朱慶餘', '酬朱慶餘', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["越女新妝出鏡心，自知明豔更沈吟。","齊紈未是人間貴，一曲菱歌敵萬金。"]', '["越女新妝出镜心，自知明豔更沈吟。","齊紈未是人间貴，一曲菱歌敵万金。"]', '诗', 'shi', '', NULL, '酬朱慶餘 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c806e007-141f-442e-8578-8bb9833a58f4', '寒食憶歸', '寒食憶归', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["京中曹局無多事，寒食貧兒要在家。","遮莫杏園勝別處，亦須歸看傍村花。"]', '["京中曹局無多事，寒食貧兒要在家。","遮莫杏园勝別处，亦須归看傍村花。"]', '诗', 'shi', '', NULL, '寒食憶歸 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2ed217a-8573-490c-b436-71d4a23f99a8', '寒食', '寒食', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["綠楊枝上五絲繩，枝弱春多欲不勝。","唯有一年寒食日，女郎相喚擺階𤺩。"]', '["綠楊枝上五絲繩，枝弱春多欲不勝。","唯有一年寒食日，女郎相喚擺階𤺩。"]', '诗', 'shi', '', NULL, '寒食 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f331687-0d39-43b8-b6e2-eb2cab965ff9', '賦花', '賦花', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["花，花。","落早，開賒。","對酒客，興詩家。","能迴遊騎，每駐行車。","宛宛清風起，茸茸麗日斜。","且願相留懽洽，惟愁虛棄光華。","明年攀折知不遠，對此誰能更歎嗟。"]', '["花，花。","落早，开賒。","对酒客，兴诗家。","能迴游騎，每駐行车。","宛宛清风起，茸茸丽日斜。","且願相留懽洽，惟愁虛棄光华。","明年攀折知不远，对此誰能更歎嗟。"]', '诗', 'shi', '', NULL, '賦花 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('817fe88c-137c-45fc-95e3-73f6baabe907', '句', '句', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["韓公國大賢，道德赫已聞。","時出爲陽山，爾區來趨奔。","韓官遷掾曹，子隨至荆門。","韓入爲博士，崎嶇送歸輪。"]', '["韓公国大賢，道德赫已闻。","时出爲陽山，爾區来趨奔。","韓官遷掾曹，子隨至荆门。","韓入爲博士，崎嶇送归輪。"]', '诗', 'shi', '', NULL, '句 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaf1094e-b116-4d91-819b-df1a80e1c991', '月蝕詩', '月蝕诗', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["新天子即位五年，歲次庚寅。","斗柄插子，律調黃鐘。","森森萬木夜殭立，寒氣贔屭頑無風。","爛銀盤從海底出，出來照我草屋東。","天色紺滑凝不流，冰光交貫寒朣朧。","初疑白蓮花，浮出龍王宮。","八月十五夜，比並不可雙。","此時怪事發，有物吞食來。","輪如壯士斧斫壞，桂似雪山風拉摧。","百鍊鏡，照見膽。","平地埋寒灰，火龍珠。","飛出腦，却入蚌蛤胎。","摧環破璧眼看盡，當天一搭如煤炲。","磨蹤滅跡須臾間，便似萬古不可開。","不料至神物，有此大狼狽。","星如撒沙出，爭頭事光大。","奴婢炷暗燈，揜菼如玳瑁。","今夜吐燄長如虹，孔隙千道射戶外。","玉川子，涕泗下。","中庭獨自行，念此日月者。","太陰太陽精，皇天要識物。","日月乃化生，走天汲汲勞四體。","與天作眼行光明，此眼不自保。","天公行道何由行，吾見陰陽家有說。","望日蝕月月光滅，朔月掩日日光缺。","兩眼不相攻，此說吾不容。","又孔子師老子云，五色令人目盲。","吾恐天似人，好色即喪明。","幸且非春時，萬物不嬌榮。","青山破瓦色，綠水冰崢嶸。","花枯無女豔，鳥死沈歌聲。","頑冬何所好，偏使一目盲。","傳聞古老說，蝕月蝦蟇精。","徑圓千里入汝腹，汝此癡骸阿誰生。","可從海窟來，便解緣青冥。","恐是眶睫間，揜塞所化成。","黃帝有二目，帝舜重瞳明。","二帝懸四目，四海生光輝。","吾不遇二帝，滉漭不可知。","何故瞳子上，坐受蟲豸欺。","長嗟白兔搗靈藥，恰似有意防姦非。","藥成滿臼不中度，委任白兔夫何爲。","憶昔堯爲天，十日燒九州。","金爍水銀流，玉煼丹砂焦。","六合烘爲窯，堯心增百憂。","帝見堯心憂，勃然發怒決洪流。","立擬沃殺九日妖，天高日走沃不及。","但見萬國赤子𧥄𧥄生魚頭，此時九御導九日。","爭持節幡麾幢旒，駕車六九五十四頭蛟螭虬。","掣電九火輈，汝若蝕開齱齵輪。","御轡執索相爬鉤，推蕩轟訇入汝喉。","紅鱗燄鳥燒口快，翎鬣倒側聲醆鄒。","撐腸拄肚礧傀如山丘，自可飽死更不偷。","不獨填飢坑，亦解堯心憂。","恨汝時當食，藏頭擫腦不肯食。","不當食，張脣哆觜食不休。","食天之眼養逆命，安得上帝請汝劉。","嗚呼！人養虎，被虎齧。","天媚蟇，被蟇瞎。","乃知恩非類，一一自作孽。","吾見患眼人，必索良工訣。","想天不異人，愛眼固應一。","安得常娥氏，來習扁鵲術。","手操舂喉戈，去此睛上物。","其初猶朦朧，既久如抹漆。","但恐功業成，便此不吐出。","玉川子又涕泗下，心禱再拜額榻砂土中。","地上蟣虱臣仝告愬帝天皇，臣心有鐵一寸。","可刳妖蟇癡腸，上天不爲臣立梯磴。","臣血肉身，無由飛上天。","揚天光，封詞付與小心風。","颰排閶闔入紫宮，密邇玉几前擘坼。","奏上臣仝頑愚胸，敢死橫干天。","代天謀其長，東方蒼龍角。","插戟尾捭風，當心開明堂。","統領三百六十鱗蟲，坐理東方宮。","月蝕不救援，安用東方龍。","南方火鳥赤潑血，項長尾短飛跋躠。","頭戴井冠高逵枿，月蝕鳥宮十三度。","鳥爲居停主人不覺察，貪向何人家。","行赤口毒舌，毒蟲頭上喫却月。","不啄殺，虛眨鬼眼明䆕䆷。","鳥罪不可雪，西方攫虎立踦踦。","斧爲牙，鑿爲齒。","偷犧牲，食封豕。","大蟇一臠，固當軟美。","見似不見，是何道理。","爪牙根天不念天，天若准擬錯准擬。","北方寒龜被虵縛，藏頭入殼如入獄。","虵筋束緊束破殼，寒龜夏鼈一種味。","且當以其肉充臛，死殼沒信處。","唯堪支牀脚不堪鑽灼與天卜，歲星主福德。","官爵奉董秦，忍使黔婁生。","覆尸無衣巾，天失眼不弔。","歲星胡其仁，熒惑矍鑠翁。","執法大不中，月明無罪過。","不糾蝕月蟲，年年十月朝太微。","支盧謫罰何災凶，土星與土性相背。","反養福德生禍害，到人頭上死破敗。","今夜月蝕安可會，太白真將軍。","怒激鋒鋩生，恆州陣斬酈定進。","項骨脃甚春蔓菁，天唯兩眼失一眼。","將軍何處行天兵，辰星任廷尉。","天律自主持，人命在盆底。","固應樂見天盲時，天若不肯信。","試喚臯陶鬼一問，一如今日。","三台文昌宮，作上天紀綱。","環天二十八宿，磊磊尚書郎。","整頓排班行，劒握他人將。","一四太陽側，一四天市傍。","操斧代大匠，兩手不怕傷。","弧矢引滿反射人，天狼呀啄明煌煌。","癡牛與騃女，不肯勤農桑。","徒勞含淫思，旦夕遙相望。","蚩尤簸旗弄旬朔，始搥天鼓鳴璫琅。","枉矢能蛇行，眊目森森張。","天狗下舐地，血流何滂滂。","譎險萬萬黨，架搆何可當。","眯目釁成就，害我光明王。","請留北斗一星相北極，指麾萬國懸中央。","此外盡掃除，堆積如山岡。","贖我父母光，當時常星沒。","殞雨如迸漿，似天會事發。","叱喝誅奸強，何故中道廢。","自遺今日殃，善善又惡惡。","郭公所以亡，願天神聖心。","無信他人忠，玉川子詞訖。","風色緊格格，近月黑暗邊。","有似動劒戟，須臾癡蟇精。","兩吻自決坼，初露半箇璧。","漸吐滿輪魄，衆星盡原赦。","一蟇獨誅磔，腹肚忽脫落。","依舊挂穹碧，光彩未蘇來。","慘澹一片白，奈何萬里光。","受此吞吐厄，再得見天眼。","感荷天地力，或問玉川子。","孔子修春秋，二百四十年。","月蝕盡不收，今子咄咄詞。","頗合孔意不，玉川子笑荅。","或請聽逗留，孔子父母魯。","諱魯不諱周，書外書大惡。","故月蝕不見收，予命唐天。","口食唐土，唐禮過三。","唐樂過五，小猶不說。","大不可數，災沴無有小大瘉。","安得引衰周，研覈其可否。","日分晝，月分夜。","辨寒暑，一主刑。","二主德，政乃舉。","孰爲人面上，一目偏可去。","願天完兩目，照下萬方土。","萬古更不瞽，萬萬古。","更不瞽，照萬古。"]', '["新天子即位五年，歲次庚寅。","斗柄插子，律調黄鐘。","森森万木夜殭立，寒氣贔屭頑無风。","爛銀盤從海底出，出来照我草屋东。","天色紺滑凝不流，冰光交貫寒朣朧。","初疑白蓮花，浮出龙王宮。","八月十五夜，比並不可雙。","此时怪事發，有物吞食来。","輪如壯士斧斫壞，桂似雪山风拉摧。","百鍊镜，照见膽。","平地埋寒灰，火龙珠。","飞出腦，却入蚌蛤胎。","摧环破璧眼看尽，當天一搭如煤炲。","磨蹤滅跡須臾间，便似万古不可开。","不料至神物，有此大狼狽。","星如撒沙出，爭头事光大。","奴婢炷暗灯，揜菼如玳瑁。","今夜吐燄长如虹，孔隙千道射戶外。","玉川子，涕泗下。","中庭独自行，念此日月者。","太陰太陽精，皇天要識物。","日月乃化生，走天汲汲勞四體。","與天作眼行光明，此眼不自保。","天公行道何由行，吾见陰陽家有说。","望日蝕月月光滅，朔月掩日日光缺。","兩眼不相攻，此说吾不容。","又孔子師老子云，五色令人目盲。","吾恐天似人，好色即喪明。","幸且非春时，万物不嬌榮。","青山破瓦色，綠水冰崢嶸。","花枯無女豔，鸟死沈歌声。","頑冬何所好，偏使一目盲。","傳闻古老说，蝕月蝦蟇精。","徑圓千里入汝腹，汝此癡骸阿誰生。","可從海窟来，便解緣青冥。","恐是眶睫间，揜塞所化成。","黄帝有二目，帝舜重瞳明。","二帝懸四目，四海生光輝。","吾不遇二帝，滉漭不可知。","何故瞳子上，坐受蟲豸欺。","长嗟白兔捣靈藥，恰似有意防姦非。","藥成满臼不中度，委任白兔夫何爲。","憶昔堯爲天，十日燒九州。","金爍水銀流，玉煼丹砂焦。","六合烘爲窯，堯心增百憂。","帝见堯心憂，勃然發怒決洪流。","立擬沃殺九日妖，天高日走沃不及。","但见万国赤子𧥄𧥄生鱼头，此时九御導九日。","爭持節幡麾幢旒，駕车六九五十四头蛟螭虬。","掣電九火輈，汝若蝕开齱齵輪。","御轡執索相爬鉤，推蕩轟訇入汝喉。","紅鱗燄鸟燒口快，翎鬣倒側声醆鄒。","撐腸拄肚礧傀如山丘，自可飽死更不偷。","不独填飢坑，亦解堯心憂。","恨汝时當食，藏头擫腦不肯食。","不當食，張脣哆觜食不休。","食天之眼養逆命，安得上帝請汝劉。","嗚呼！人養虎，被虎齧。","天媚蟇，被蟇瞎。","乃知恩非類，一一自作孽。","吾见患眼人，必索良工訣。","想天不異人，愛眼固應一。","安得常娥氏，来習扁鵲術。","手操舂喉戈，去此睛上物。","其初猶朦朧，既久如抹漆。","但恐功業成，便此不吐出。","玉川子又涕泗下，心禱再拜額榻砂土中。","地上蟣虱臣仝告愬帝天皇，臣心有鐵一寸。","可刳妖蟇癡腸，上天不爲臣立梯磴。","臣血肉身，無由飞上天。","揚天光，封词付與小心风。","颰排閶闔入紫宮，密邇玉几前擘坼。","奏上臣仝頑愚胸，敢死橫干天。","代天謀其长，东方蒼龙角。","插戟尾捭风，當心开明堂。","統領三百六十鱗蟲，坐理东方宮。","月蝕不救援，安用东方龙。","南方火鸟赤潑血，項长尾短飞跋躠。","头戴井冠高逵枿，月蝕鸟宮十三度。","鸟爲居停主人不覺察，貪向何人家。","行赤口毒舌，毒蟲头上喫却月。","不啄殺，虛眨鬼眼明䆕䆷。","鸟罪不可雪，西方攫虎立踦踦。","斧爲牙，鑿爲齒。","偷犧牲，食封豕。","大蟇一臠，固當軟美。","见似不见，是何道理。","爪牙根天不念天，天若准擬錯准擬。","北方寒龟被虵縛，藏头入殼如入獄。","虵筋束緊束破殼，寒龟夏鼈一種味。","且當以其肉充臛，死殼沒信处。","唯堪支牀脚不堪鑽灼與天卜，歲星主福德。","官爵奉董秦，忍使黔婁生。","覆尸無衣巾，天失眼不弔。","歲星胡其仁，熒惑矍鑠翁。","執法大不中，月明無罪過。","不糾蝕月蟲，年年十月朝太微。","支盧謫罰何災凶，土星與土性相背。","反養福德生禍害，到人头上死破敗。","今夜月蝕安可會，太白真將軍。","怒激鋒鋩生，恆州陣斬酈定進。","項骨脃甚春蔓菁，天唯兩眼失一眼。","將軍何处行天兵，辰星任廷尉。","天律自主持，人命在盆底。","固應乐见天盲时，天若不肯信。","試喚臯陶鬼一问，一如今日。","三台文昌宮，作上天紀綱。","环天二十八宿，磊磊尚书郎。","整頓排班行，劒握他人將。","一四太陽側，一四天市傍。","操斧代大匠，兩手不怕傷。","弧矢引满反射人，天狼呀啄明煌煌。","癡牛與騃女，不肯勤農桑。","徒勞含淫思，旦夕遙相望。","蚩尤簸旗弄旬朔，始搥天鼓鳴璫琅。","枉矢能蛇行，眊目森森張。","天狗下舐地，血流何滂滂。","譎險万万黨，架搆何可當。","眯目釁成就，害我光明王。","請留北斗一星相北極，指麾万国懸中央。","此外尽掃除，堆積如山岡。","贖我父母光，當时常星沒。","殞雨如迸漿，似天會事發。","叱喝誅奸強，何故中道廢。","自遺今日殃，善善又惡惡。","郭公所以亡，願天神聖心。","無信他人忠，玉川子词訖。","风色緊格格，近月黑暗邊。","有似动劒戟，須臾癡蟇精。","兩吻自決坼，初露半箇璧。","漸吐满輪魄，衆星尽原赦。","一蟇独誅磔，腹肚忽脫落。","依旧挂穹碧，光彩未蘇来。","慘澹一片白，奈何万里光。","受此吞吐厄，再得见天眼。","感荷天地力，或问玉川子。","孔子修春秋，二百四十年。","月蝕尽不收，今子咄咄词。","頗合孔意不，玉川子笑荅。","或請听逗留，孔子父母魯。","諱魯不諱周，书外书大惡。","故月蝕不见收，予命唐天。","口食唐土，唐禮過三。","唐乐過五，小猶不说。","大不可數，災沴無有小大瘉。","安得引衰周，研覈其可否。","日分晝，月分夜。","辨寒暑，一主刑。","二主德，政乃舉。","孰爲人面上，一目偏可去。","願天完兩目，照下万方土。","万古更不瞽，万万古。","更不瞽，照万古。"]', '诗', 'shi', '', NULL, '月蝕詩 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fb73d6d-2a39-466f-959b-5bfb91c87fd7', '哭玉碑子', '哭玉碑子', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["山有洞左頰，拾得玉碑子。","其長一周尺，其闊一藥匕。","顏色九秋天，稜角四面起。","輕敲吐寒流，清悲動神鬼。","稽首置手中，只似一片水。","至文反無文，上帝應有以。","予疑仙石靈，願以仙人比。","心期香湯洗，歸送籙堂裏。","頗奈窮相驢，行動如跛鼈。","十里五里行，百蹶復千蹶。","顏子不少夭，玉碑中路折。","橫文尋龜兆，直理任瓦裂。","劈竹不可合，破環永離別。","向人如有情，似痛滴無血。","勘鬬平地上，罅坼多齧缺。","百見百傷心，不堪再提挈。","怪哉堅貞姿，忽脃不堅固。","矧曰人間人，安能保常度。","敢問生物成，敗爲有真素。","爲稟靈異氣，不得受穢汚。","驢罪真不厚，驢生亦錯誤。","更將前前行，復恐山神怒。","白雲蓊閉嶺，高松吟古墓。","置此忍其傷，驅驢下山路。"]', '["山有洞左頰，拾得玉碑子。","其长一周尺，其闊一藥匕。","顏色九秋天，稜角四面起。","轻敲吐寒流，清悲动神鬼。","稽首置手中，只似一片水。","至文反無文，上帝應有以。","予疑仙石靈，願以仙人比。","心期香湯洗，归送籙堂裏。","頗奈窮相驢，行动如跛鼈。","十里五里行，百蹶复千蹶。","顏子不少夭，玉碑中路折。","橫文尋龟兆，直理任瓦裂。","劈竹不可合，破环永離別。","向人如有情，似痛滴無血。","勘鬬平地上，罅坼多齧缺。","百见百傷心，不堪再提挈。","怪哉堅貞姿，忽脃不堅固。","矧曰人间人，安能保常度。","敢问生物成，敗爲有真素。","爲稟靈異氣，不得受穢汚。","驢罪真不厚，驢生亦錯誤。","更將前前行，复恐山神怒。","白云蓊閉嶺，高松吟古墓。","置此忍其傷，驱驢下山路。"]', '诗', 'shi', '', NULL, '哭玉碑子 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d746a56b-a083-4549-b107-30764a8726b2', '觀放魚歌', '观放鱼歌', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["常州賢刺史，從諫議大夫除。","天地好生物，刺史性與天地俱。","見山客，狎魚鳥。","坐山客，北亭湖。","命舟人，駕舫子。","漾漾菰蒲，酒興引行處。","正見漁人魚，刺史密會山客意。","復念網羅嬰無辜，忽脫身上殷緋袍。","盡買罟擭盡有無，鰻鱣鲇鱧鰌。","涎惡最頑愚，鱒舫見豳風。","質幹稍高流，時白噴雪鯽鯉𦛇。","此輩肥脃爲絕尤，老鯉變化頗神異。","三十六鱗如抹朱，水苞弘窟有蛟鼉。","餌非龍餌唯無鱸，叢雜百千頭。","性命懸須臾，天心應刺史。","刺史盡活諸，一一投深泉。","跳脫不復拘，得水競騰突。","動作詭怪殊，或透藻而出。","或破浪而趨，或掉尾孑孑。","或奮鬣愉愉，或如鶯擲梭。","或如虵銜珠，四散漸不見。","島嶼徒縈紆，鸂鶒鴒鷗鳧。","喜觀爭呌呼，小蝦亦相慶。","繞岸搖其鬚，乃知貪生不獨頑癡夫。","可憐百千命，幾爲中腸葅。","若養聖賢真，大烹龍髓敢惜乎。","苦痛如今人，盡是魚食魚。","族類恣飲噉，強力無親疏。","明明刺史心，不欲與物相欺誣。","岸蟲兩與命，無意殺此活彼用賊徒。","亦憶清江使，橫遭乎余且。","聖神七十鑽，不及泥中鰌。","哀哉託非賢，五臟生冤讐。","若當刺史時，聖物保不囚。","不疑且不卜，二子安能諛。","二子儻故諛，吾知心受誅。","禮重一草木，易卦稱中孚。","又曰釣不綱，又曰遠庖廚。","故仁人用心，刺史盡合符。","昔魯公觀棠距箴，遂被孔子貶而書。","今刺史好生，德洽民心。","誰爲刺史一褒譽，刺史自上來。","德風如草鋪，衣冠興廢禮。","百姓減暴租，豪猾不豪猾。","鰥孤不鰥孤，開古孟瀆三十里。","四千頃泥坑爲膏腴，刺史視之總若無。","訟庭雀噪坐不得，湖上拔茭植芙蕖。","勝業莊中二桑門，時時對坐談真如。","因說十千天子事，福力當與刺史俱。","天雨曼陀羅花深沒膝，四十千真珠瓔珞堆高樓。","此中怪特不可會，但慕刺史仁有餘。","刺史敕左右兼小家奴，慎勿背我沈毒鉤。","念魚承奉刺史仁，深僻處，遠遠遊。","刺史官職小，教化未能敷。","第一莫近人，惡人唯口腴。","第一莫出境，四境多網罟。","重傷刺史心，喪爾微賤軀。"]', '["常州賢刺史，從諫議大夫除。","天地好生物，刺史性與天地俱。","见山客，狎鱼鸟。","坐山客，北亭湖。","命舟人，駕舫子。","漾漾菰蒲，酒兴引行处。","正见漁人鱼，刺史密會山客意。","复念網羅嬰無辜，忽脫身上殷緋袍。","尽買罟擭尽有無，鰻鱣鲇鱧鰌。","涎惡最頑愚，鱒舫见豳风。","質幹稍高流，时白噴雪鯽鯉𦛇。","此輩肥脃爲絕尤，老鯉变化頗神異。","三十六鱗如抹朱，水苞弘窟有蛟鼉。","餌非龙餌唯無鱸，叢杂百千头。","性命懸須臾，天心應刺史。","刺史尽活諸，一一投深泉。","跳脫不复拘，得水競腾突。","动作詭怪殊，或透藻而出。","或破浪而趨，或掉尾孑孑。","或奮鬣愉愉，或如鶯擲梭。","或如虵銜珠，四散漸不见。","島嶼徒縈紆，鸂鶒鴒鷗鳧。","喜观爭呌呼，小蝦亦相慶。","繞岸搖其鬚，乃知貪生不独頑癡夫。","可怜百千命，幾爲中腸葅。","若養聖賢真，大烹龙髓敢惜乎。","苦痛如今人，尽是鱼食鱼。","族類恣饮噉，強力無親疏。","明明刺史心，不欲與物相欺誣。","岸蟲兩與命，無意殺此活彼用賊徒。","亦憶清江使，橫遭乎余且。","聖神七十鑽，不及泥中鰌。","哀哉託非賢，五臟生冤讐。","若當刺史时，聖物保不囚。","不疑且不卜，二子安能諛。","二子儻故諛，吾知心受誅。","禮重一草木，易卦稱中孚。","又曰釣不綱，又曰远庖廚。","故仁人用心，刺史尽合符。","昔魯公观棠距箴，遂被孔子貶而书。","今刺史好生，德洽民心。","誰爲刺史一褒譽，刺史自上来。","德风如草鋪，衣冠兴廢禮。","百姓減暴租，豪猾不豪猾。","鰥孤不鰥孤，开古孟瀆三十里。","四千頃泥坑爲膏腴，刺史視之總若無。","訟庭雀噪坐不得，湖上拔茭植芙蕖。","勝業莊中二桑门，时时对坐談真如。","因说十千天子事，福力當與刺史俱。","天雨曼陀羅花深沒膝，四十千真珠瓔珞堆高楼。","此中怪特不可會，但慕刺史仁有餘。","刺史敕左右兼小家奴，慎勿背我沈毒鉤。","念鱼承奉刺史仁，深僻处，远远游。","刺史官職小，教化未能敷。","第一莫近人，惡人唯口腴。","第一莫出境，四境多網罟。","重傷刺史心，喪爾微賤軀。"]', '诗', 'shi', '', NULL, '觀放魚歌 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a1736c7-f4b2-40ac-b7cd-e5ad31ba8794', '示添丁', '示添丁', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["春風苦不仁，呼逐馬蹄行人家。","慚愧瘴氣却憐我，入我憔悴骨中爲生涯。","數日不食強強行，何忍索我抱看滿樹花。","不知四體正困𢞎，泥人啼哭聲呀呀。","忽來案上翻墨汁，塗抹詩書如老鵶。","父憐母惜摑不得，却生癡笑令人嗟。","宿舂連曉不成米，日高始進一椀茶。","氣力龍鍾頭欲白，憑仗添丁莫惱爺。"]', '["春风苦不仁，呼逐马蹄行人家。","慚愧瘴氣却怜我，入我憔悴骨中爲生涯。","數日不食強強行，何忍索我抱看满樹花。","不知四體正困𢞎，泥人啼哭声呀呀。","忽来案上翻墨汁，塗抹诗书如老鵶。","父怜母惜摑不得，却生癡笑令人嗟。","宿舂連晓不成米，日高始進一椀茶。","氣力龙鍾头欲白，憑仗添丁莫惱爺。"]', '诗', 'shi', '', NULL, '示添丁 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b36420a-c7bd-412f-b5ae-34b845d79afc', '寄男抱孫', '寄男抱孫', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["別來三得書，書道違離久。","書處甚麤殺，且喜見汝手。","殷十七又報，汝文頗新有。","別來纔經年，囊盎未合斗。","當是汝母賢，日夕加訓誘。","尚書當畢功，禮記速須剖。","嘍囉兒讀書，何異摧枯朽。","尋義低作聲，便可養年壽。","莫學村學生，麤氣強呌吼。","下學偷功夫，新宅鋤䔧莠。","乘涼勸奴婢，園裏耨葱韭。","遠籬編榆棘，近眼栽桃柳。","引水灌竹中，蒲池種蓮藕。","撈漉蛙𢋙脚，莫遣生科斗。","竹林吾最惜，新筍好看守。","萬籜苞龍兒，攢迸溢林藪。","吾眼恨不見，心腸痛如搊。","宅錢都未還，債利日日厚。","籜龍正稱冤，莫殺入汝口。","丁寧囑託汝，汝活籜龍不。","殷十七老儒，是汝父師友。","傳讀有疑悞，輙告諮問取。","兩手莫破拳，一吻莫飲酒。","莫學捕鳩鴿，莫學打雞狗。","小時無大傷，習性防已後。","頑發苦惱人，汝母必不受。","任汝惱弟妹，任汝惱姨舅。","姨舅非吾親，弟妹多老醜。","莫惱添丁郎，淚子作面垢。","莫引添丁郎，赫赤日裏走。","添丁郎小小，別吾來久久。","脯脯不得喫，兄兄莫撚搜。","他日吾歸來，家人若彈糺。","一百放一下，打汝九十九。"]', '["別来三得书，书道違離久。","书处甚麤殺，且喜见汝手。","殷十七又報，汝文頗新有。","別来纔經年，囊盎未合斗。","當是汝母賢，日夕加訓誘。","尚书當畢功，禮記速須剖。","嘍囉兒读书，何異摧枯朽。","尋義低作声，便可養年壽。","莫学村学生，麤氣強呌吼。","下学偷功夫，新宅鋤䔧莠。","乘涼勸奴婢，园裏耨葱韭。","远籬編榆棘，近眼栽桃柳。","引水灌竹中，蒲池種蓮藕。","撈漉蛙𢋙脚，莫遣生科斗。","竹林吾最惜，新筍好看守。","万籜苞龙兒，攢迸溢林藪。","吾眼恨不见，心腸痛如搊。","宅錢都未還，債利日日厚。","籜龙正稱冤，莫殺入汝口。","丁寧囑託汝，汝活籜龙不。","殷十七老儒，是汝父師友。","傳读有疑悞，輙告諮问取。","兩手莫破拳，一吻莫饮酒。","莫学捕鳩鴿，莫学打雞狗。","小时無大傷，習性防已後。","頑發苦惱人，汝母必不受。","任汝惱弟妹，任汝惱姨舅。","姨舅非吾親，弟妹多老醜。","莫惱添丁郎，泪子作面垢。","莫引添丁郎，赫赤日裏走。","添丁郎小小，別吾来久久。","脯脯不得喫，兄兄莫撚搜。","他日吾归来，家人若彈糺。","一百放一下，打汝九十九。"]', '诗', 'shi', '', NULL, '寄男抱孫 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('022d23cb-86f8-444d-8d79-be5ab78ae495', '自詠三首 一', '自詠三首 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["爲報玉川子，知君未是賢。","低頭雖有地，仰面輙無天。","骨肉清成瘦，萵蔓老覺羶。","家書與心事，相伴過流年。"]', '["爲報玉川子，知君未是賢。","低头雖有地，仰面輙無天。","骨肉清成瘦，萵蔓老覺羶。","家书與心事，相伴過流年。"]', '诗', 'shi', '', NULL, '自詠三首 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('490f56b2-c972-4c28-a4d2-0af9e7aa7b68', '自詠三首 二', '自詠三首 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["盧子躘踵也，賢愚總莫驚。","蚊蝱當家口，草石是親情。","萬卷堆胸朽，三光撮眼明。","翻悲廣成子，閑氣說長生。"]', '["盧子躘踵也，賢愚總莫驚。","蚊蝱當家口，草石是親情。","万卷堆胸朽，三光撮眼明。","翻悲廣成子，闲氣说长生。"]', '诗', 'shi', '', NULL, '自詠三首 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d6d2bfe-caa5-421f-901e-d1d8a2b3a0d7', '自詠三首 三', '自詠三首 三', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["物外無知己，人間一癖王。","生涯身是夢，耽樂酒爲鄉。","日月黏髭鬚，雲山鎖肺腸。","愚公只公是，不用謾驚張。"]', '["物外無知己，人间一癖王。","生涯身是梦，耽乐酒爲乡。","日月黏髭鬚，云山鎖肺腸。","愚公只公是，不用謾驚張。"]', '诗', 'shi', '', NULL, '自詠三首 三 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b58760b-e78a-4364-abca-7d70d797939d', '送王儲詹事西遊獻兵書', '送王儲詹事西游獻兵书', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["美酒撥醅酌，楊花飛盡時。","落日長安道，方寸無人知。","篋中制勝術，氣雄屈指筭。","半醉千殷勤，仰天一長歎。","玉匣百鍊劒，龜文又龍吼。","抽贈王將軍，勿使虛白首。"]', '["美酒撥醅酌，楊花飞尽时。","落日长安道，方寸無人知。","篋中制勝術，氣雄屈指筭。","半醉千殷勤，仰天一长歎。","玉匣百鍊劒，龟文又龙吼。","抽贈王將軍，勿使虛白首。"]', '诗', 'shi', '', NULL, '送王儲詹事西遊獻兵書 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99332531-4755-4c27-9e58-f8edb49a47c1', '送邵兵曹歸江南', '送邵兵曹归江南', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["春風楊柳陌，連騎醉離觴。","千里遠山碧，一條歸路長。","花開愁北渚，雲去渡南湘。","東望濛濛處，煙波是故鄉。"]', '["春风楊柳陌，連騎醉離觴。","千里远山碧，一條归路长。","花开愁北渚，云去渡南湘。","东望濛濛处，煙波是故乡。"]', '诗', 'shi', '', NULL, '送邵兵曹歸江南 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52bb4abd-fd0d-4c83-8966-98c4fdbcba34', '寄外兄魏澈', '寄外兄魏澈', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["何處堪惆悵，情親不得親。","興寧樓上月，辜負酒家春。"]', '["何处堪惆悵，情親不得親。","兴寧楼上月，辜負酒家春。"]', '诗', 'shi', '', NULL, '寄外兄魏澈 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f73524-3069-43f0-8dbf-bd18fd1ac51f', '喜逢鄭三遊山', '喜逢鄭三游山', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["相逢之處花茸茸，石壁攢峰千萬重。","他日期君何處好，寒流石上一株松。"]', '["相逢之处花茸茸，石壁攢峰千万重。","他日期君何处好，寒流石上一株松。"]', '诗', 'shi', '', NULL, '喜逢鄭三遊山 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a428197-24d7-49a5-9fed-7cd545ef45af', '卓女怨', '卓女怨', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["妾本懷春女，春愁不自任。","迷魂隨鳳客，嬌思入琴心。","託援交情重，當壚酌意深。","誰家有夫壻，作賦得黃金。"]', '["妾本懷春女，春愁不自任。","迷魂隨鳳客，嬌思入琴心。","託援交情重，當壚酌意深。","誰家有夫壻，作賦得黄金。"]', '诗', 'shi', '', NULL, '卓女怨 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16677134-de54-4cf8-84bc-4322f7aa47c0', '守歲二首 一', '守歲二首 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["去年留不住，年來也任他。","當壚一榼酒，爭奈兩年何。"]', '["去年留不住，年来也任他。","當壚一榼酒，爭奈兩年何。"]', '诗', 'shi', '', NULL, '守歲二首 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e5b0860-39b1-46ee-aa71-d772bd24bbc5', '守歲二首 二', '守歲二首 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["老來經節臘，樂事甚悠悠。","不及兒童日，都盧不解愁。"]', '["老来經節臘，乐事甚悠悠。","不及兒童日，都盧不解愁。"]', '诗', 'shi', '', NULL, '守歲二首 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('848eba6c-b222-4d42-92c5-c40f4d9fc35d', '新月', '新月', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["仙宮雲箔卷，露出玉簾鉤。","清光無所贈，相憶鳳皇樓。"]', '["仙宮云箔卷，露出玉簾鉤。","清光無所贈，相憶鳳皇楼。"]', '诗', 'shi', '', NULL, '新月 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8251441b-49cc-4e10-a2b7-04f29a180df3', '解悶', '解悶', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["人生都幾日，一半是離憂。","但有尊中物，從他萬事休。"]', '["人生都幾日，一半是離憂。","但有尊中物，從他万事休。"]', '诗', 'shi', '', NULL, '解悶 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd6c448-bd3c-43dd-bdde-066f63af4013', '楊子津', '楊子津', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["風卷魚龍暗楚關，白波沈却海門山。","鵬騰鼇倒且快性，地坼天開總是閑。"]', '["风卷鱼龙暗楚关，白波沈却海门山。","鵬腾鼇倒且快性，地坼天开總是闲。"]', '诗', 'shi', '', NULL, '楊子津 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('920bb4e9-69cb-4226-a45c-04ba744e19c3', '人日立春', '人日立春', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["春度春歸無限春，今朝方始覺成人。","從今尅己應猶及，顏與梅花俱自新。"]', '["春度春归無限春，今朝方始覺成人。","從今尅己應猶及，顏與梅花俱自新。"]', '诗', 'shi', '', NULL, '人日立春 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f414cae-e8ad-4929-b0db-72336a855944', '送尉遲羽之歸宣州', '送尉遲羽之归宣州', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["君歸呼，君歸興不孤。","謝朓澄江今夜月，也應憶著此山夫。"]', '["君归呼，君归兴不孤。","謝朓澄江今夜月，也應憶著此山夫。"]', '诗', 'shi', '', NULL, '送尉遲羽之歸宣州 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b675645-500d-44b9-a70d-0bee63b0f7aa', '悲新年', '悲新年', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["新年何事最堪悲，病客遙聽百舌兒。","太歲只遊桃李徑，春風肯管歲寒枝。"]', '["新年何事最堪悲，病客遙听百舌兒。","太歲只游桃李徑，春风肯管歲寒枝。"]', '诗', 'shi', '', NULL, '悲新年 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d46a47e0-dacf-4ae3-ae54-69db477abb28', '憶酒寄劉侍郎', '憶酒寄劉侍郎', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["愛酒如偷蜜，憎醒似見刀。","君爲麯糵主，酒醴莫辭勞。"]', '["愛酒如偷蜜，憎醒似见刀。","君爲麯糵主，酒醴莫辞勞。"]', '诗', 'shi', '', NULL, '憶酒寄劉侍郎 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b3dfcbb-be3e-4168-8e5f-19ce1e5fac80', '白鷺鷥', '白鷺鷥', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["刻成片玉白鷺鷥，欲捉纖鱗心自急。","翹足沙頭不得時，傍人不知謂閑立。"]', '["刻成片玉白鷺鷥，欲捉纖鱗心自急。","翹足沙头不得时，傍人不知謂闲立。"]', '诗', 'shi', '', NULL, '白鷺鷥 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03f8a03b-c23c-49bc-8ee1-50de17d40c23', '風中琴', '风中琴', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["五音六律十三徽，龍吟鶴響思庖羲。","一彈流水一彈月，水月風生松樹枝。"]', '["五音六律十三徽，龙吟鹤响思庖羲。","一彈流水一彈月，水月风生松樹枝。"]', '诗', 'shi', '', NULL, '風中琴 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f548c1e1-4ec6-450e-8a5e-bf7f91fa1248', '感秋別怨', '感秋別怨', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["霜秋自斷魂，楚調怨離分。","魄散瑤臺月，心隨巫峽雲。","蛾眉誰共畫，鳳曲不同聞。","莫似湘妃淚，斑斑點翠裙。"]', '["霜秋自斷魂，楚調怨離分。","魄散瑤台月，心隨巫峽云。","蛾眉誰共畫，鳳曲不同闻。","莫似湘妃泪，斑斑点翠裙。"]', '诗', 'shi', '', NULL, '感秋別怨 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('174ab978-0f84-4865-957e-80d9f1a346d7', '新蟬', '新蟬', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["泉溜潛幽咽，琴鳴乍往還。","長風翦不斷，還在樹枝間。"]', '["泉溜潛幽咽，琴鳴乍往還。","长风翦不斷，還在樹枝间。"]', '诗', 'shi', '', NULL, '新蟬 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('755f9536-506a-47a2-a6bf-f83de74da4e8', '題褚遂良孫庭竹', '題褚遂良孫庭竹', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["負霜停雪舊根枝，龍笙鳳管君莫截。","春風一番琴上來，搖碎金尊碧天月。"]', '["負霜停雪旧根枝，龙笙鳳管君莫截。","春风一番琴上来，搖碎金尊碧天月。"]', '诗', 'shi', '', NULL, '題褚遂良孫庭竹 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e121d784-e855-4bc0-b69f-342c12d3e93d', '訪含曦上人', '訪含曦上人', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["三入寺，曦未來。","轆轤無人井百尺，渴心歸去生塵埃。"]', '["三入寺，曦未来。","轆轤無人井百尺，渴心归去生塵埃。"]', '诗', 'shi', '', NULL, '訪含曦上人 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('070f7ff7-71cb-4969-b3b5-d138eaaddfed', '客淮南病', '客淮南病', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["揚州蒸毒似燂湯，客病清枯鬢欲霜。","且喜閉門無俗物，四肢安穩一張牀。"]', '["揚州蒸毒似燂湯，客病清枯鬢欲霜。","且喜閉门無俗物，四肢安穩一張牀。"]', '诗', 'shi', '', NULL, '客淮南病 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a2ac536-d749-4430-b92c-aa82369da683', '村醉', '村醉', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["昨夜村飲歸，健倒三四五。","摩挲青莓苔，莫嗔驚著汝。"]', '["昨夜村饮归，健倒三四五。","摩挲青莓苔，莫嗔驚著汝。"]', '诗', 'shi', '', NULL, '村醉 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da7785f1-3aaa-4274-a55a-da81028024df', '村醉', '村醉', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["村醉黄昏歸，健倒三四五。","摩娑莓苔背，嗔我驚爾不。"]', '["村醉黄昏归，健倒三四五。","摩娑莓苔背，嗔我驚爾不。"]', '诗', 'shi', '', NULL, '村醉 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59e3f594-bbfb-4574-ab2e-69b415d8468c', '蕭宅二三子贈答詩二十首 客贈石', '蕭宅二三子贈答诗二十首 客贈石', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["竹下青莎中，細長三四片。","主人雖不歸，長見主人面。"]', '["竹下青莎中，細长三四片。","主人雖不归，长见主人面。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客贈石 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d3be722-0840-4501-a2f8-d9c13878355d', '蕭宅二三子贈答詩二十首 石讓竹', '蕭宅二三子贈答诗二十首 石讓竹', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["自顧撥不轉，何敢當主人。","竹弟有清風，可以娛嘉賓。"]', '["自顧撥不轉，何敢當主人。","竹弟有清风，可以娛嘉賓。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 石讓竹 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1199d7f-9101-4e0e-9498-072a9bdee1d2', '蕭宅二三子贈答詩二十首 竹荅客', '蕭宅二三子贈答诗二十首 竹荅客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["竹弟謝石兄，清風非所任。","隨分有蕭瑟，實無堅重心。"]', '["竹弟謝石兄，清风非所任。","隨分有蕭瑟，實無堅重心。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 竹荅客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bb357ff-c3f3-43bb-ba83-43ac708f5a44', '蕭宅二三子贈答詩二十首 石請客', '蕭宅二三子贈答诗二十首 石請客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["竹弟雖讓客，不敢當客恩。","自慙埋沒久，滿面蒼苔痕。"]', '["竹弟雖讓客，不敢當客恩。","自慙埋沒久，满面蒼苔痕。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 石請客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1177d8e-a46f-48f9-b280-bc2b6179f59e', '蕭宅二三子贈答詩二十首 客荅石', '蕭宅二三子贈答诗二十首 客荅石', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["遍索天地間，彼此最癡癖。","主人幸未來，與君爲莫逆。"]', '["遍索天地间，彼此最癡癖。","主人幸未来，與君爲莫逆。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客荅石 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('769a722c-3e1e-4b9a-adee-e6592eaa96c7', '蕭宅二三子贈答詩二十首 石荅竹', '蕭宅二三子贈答诗二十首 石荅竹', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["石報孤竹君，此客甚高調。","共我相共癡，不怕主人天下笑。","我非蛺蝶兒，我非桃李枝。","不要兒女撲，不要春風吹。","苔蘚印我面，雨露皴我皮。","此故不嫌我，突兀蒙相知。","此客即西歸，我心徒依依。","我欲隨客去，累重不解飛。","知弟虛心亦待客，此客何以共報之。"]', '["石報孤竹君，此客甚高調。","共我相共癡，不怕主人天下笑。","我非蛺蝶兒，我非桃李枝。","不要兒女撲，不要春风吹。","苔蘚印我面，雨露皴我皮。","此故不嫌我，突兀蒙相知。","此客即西归，我心徒依依。","我欲隨客去，累重不解飞。","知弟虛心亦待客，此客何以共報之。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 石荅竹 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e8e6eed-cb19-49b2-979a-ec1d3a0e3729', '蕭宅二三子贈答詩二十首 竹請客', '蕭宅二三子贈答诗二十首 竹請客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["我本泰山阿，避地到南國。","主人欲移家，我亦要歸北。","上客幸先歸，願託歸飛翼。","唯將翛翛風，累路報恩德。"]', '["我本泰山阿，避地到南国。","主人欲移家，我亦要归北。","上客幸先归，願託归飞翼。","唯將翛翛风，累路報恩德。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 竹請客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2ad5a4a-4de4-4f9e-85d3-7147996b9b11', '蕭宅二三子贈答詩二十首 客謝竹', '蕭宅二三子贈答诗二十首 客謝竹', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["揚州駮雜地，不辨龍𧈼蜴。","客身正乾枯，行處無膏澤。","太山道不遠，相庇實無力。","君若隨我行，必有煎茶厄。"]', '["揚州駮杂地，不辨龙𧈼蜴。","客身正乾枯，行处無膏澤。","太山道不远，相庇實無力。","君若隨我行，必有煎茶厄。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客謝竹 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebe156b5-edc2-4eb7-8537-c6c694e1c02b', '蕭宅二三子贈答詩二十首 石請客', '蕭宅二三子贈答诗二十首 石請客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["啓母是諸母，三十六峰是諸父。","知君家近父母家，小人安得不懷土。","憐君與我金石交，君歸可得共載否。","小人無以報君恩，使君池亭風月古。"]', '["啓母是諸母，三十六峰是諸父。","知君家近父母家，小人安得不懷土。","怜君與我金石交，君归可得共載否。","小人無以報君恩，使君池亭风月古。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 石請客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fecc3a7-92f6-42d1-9dca-1a82a0f1cee4', '蕭宅二三子贈答詩二十首 客謝石', '蕭宅二三子贈答诗二十首 客謝石', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["我有水竹莊，甚近嵩之巔。","是君歸休處，可以終天年。","雖有提攜勞，不憂糧食錢。","但恐主人心，疑我相釣竿。"]', '["我有水竹莊，甚近嵩之巔。","是君归休处，可以終天年。","雖有提携勞，不憂糧食錢。","但恐主人心，疑我相釣竿。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客謝石 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a26f6d1-4f79-4ee4-ae75-7c4d32ffd227', '蕭宅二三子贈答詩二十首 石再請客', '蕭宅二三子贈答诗二十首 石再請客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["主人若知我，應喜我結得君。","主人不知我，我住何求于主人。","我在天地間，自是一片物。","可得杠壓我，使我頭不出。"]', '["主人若知我，應喜我結得君。","主人不知我，我住何求于主人。","我在天地间，自是一片物。","可得杠壓我，使我头不出。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 石再請客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f905ae5b-7950-494f-88b4-44b5d4041f2c', '蕭宅二三子贈答詩二十首 客許石', '蕭宅二三子贈答诗二十首 客許石', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["石公說道理，句句出凡格。","相知貴知心，豈恨主爲客。","過須歸去來，旦晚上無厄。","主人誠賢人，多應不相責。"]', '["石公说道理，句句出凡格。","相知貴知心，豈恨主爲客。","過須归去来，旦晚上無厄。","主人誠賢人，多應不相責。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客許石 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('705f9582-c56d-4641-80a7-e1c8638d9649', '蕭宅二三子贈答詩二十首 井請客', '蕭宅二三子贈答诗二十首 井請客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["我生天地間，頗是往還數。","已効炊爨勞，我亦不願住。","君有造化力，在君一降顧。","我願拔黃泉，輕舉隨君去。"]', '["我生天地间，頗是往還數。","已効炊爨勞，我亦不願住。","君有造化力，在君一降顧。","我願拔黄泉，轻舉隨君去。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 井請客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f1d3111-022a-4153-9476-1a1356ca575e', '蕭宅二三子贈答詩二十首 客謝井', '蕭宅二三子贈答诗二十首 客謝井', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["改邑不改井，此是井卦辭。","井公莫怪驚，說我成憨癡。","我縱有神力，爭敢將公歸。","揚州惡百姓，疑我卷地皮。"]', '["改邑不改井，此是井卦辞。","井公莫怪驚，说我成憨癡。","我縱有神力，爭敢將公归。","揚州惡百姓，疑我卷地皮。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客謝井 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a8d087c-afdb-4acd-9ef0-e670f627b0b7', '蕭宅二三子贈答詩二十首 馬蘭請客', '蕭宅二三子贈答诗二十首 马蘭請客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["蘭蘭是小草，不怕郎君駡。","願得隨君行，暫到嵩山下。"]', '["蘭蘭是小草，不怕郎君駡。","願得隨君行，暫到嵩山下。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 馬蘭請客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e610c414-386a-433d-98d3-f8ac508574ec', '蕭宅二三子贈答詩二十首 客請馬蘭', '蕭宅二三子贈答诗二十首 客請马蘭', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["嵩山未必憐蘭蘭，蘭蘭已受郎君恩。","不須刷帚跳蹤走，只擬蘭浪出其門。"]', '["嵩山未必怜蘭蘭，蘭蘭已受郎君恩。","不須刷帚跳蹤走，只擬蘭浪出其门。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客請馬蘭 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d010bccc-64dd-44be-ad5c-6821e9fab47c', '蕭宅二三子贈答詩二十首 蛺蝶請客', '蕭宅二三子贈答诗二十首 蛺蝶請客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["粉末爲四體，春風爲生涯。","願得紛飛去，與君爲眼花。"]', '["粉末爲四體，春风爲生涯。","願得紛飞去，與君爲眼花。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 蛺蝶請客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5092fe9b-fd4c-4145-99e9-281d5a979652', '蕭宅二三子贈答詩二十首 客荅蛺蝶', '蕭宅二三子贈答诗二十首 客荅蛺蝶', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["君是輕薄子，莫窺君子腸。","且須看雀兒，雀兒銜爾將。"]', '["君是轻薄子，莫窺君子腸。","且須看雀兒，雀兒銜爾將。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客荅蛺蝶 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d32dbdef-e399-4e2c-a322-bafa0404e934', '蕭宅二三子贈答詩二十首 蝦𢋙請客', '蕭宅二三子贈答诗二十首 蝦𢋙請客', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["凡有水竹處，我曹長先行。","願君借我一勺水，與君晝夜歌德聲。"]', '["凡有水竹处，我曹长先行。","願君借我一勺水，與君晝夜歌德声。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 蝦𢋙請客 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4093bcad-73b0-44dc-90f7-8b2d48364c11', '蕭宅二三子贈答詩二十首 客請蝦𢋙', '蕭宅二三子贈答诗二十首 客請蝦𢋙', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["蝦𢋙𢋙，叩頭莫語人聞聲，揚州蝦蜆忽得便。","腥臊臭穢逐我行，我身化作青泥坑。"]', '["蝦𢋙𢋙，叩头莫語人闻声，揚州蝦蜆忽得便。","腥臊臭穢逐我行，我身化作青泥坑。"]', '诗', 'shi', '', NULL, '蕭宅二三子贈答詩二十首 客請蝦𢋙 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b80d6611-a75f-46ca-a380-6d5af8fc7713', '龜銘', '龟銘', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["龜，汝靈於人，不靈於身。","致網於津，吾靈於身。","不靈於人，致走於塵。","龜，吾與汝鄰。"]', '["龟，汝靈於人，不靈於身。","致網於津，吾靈於身。","不靈於人，致走於塵。","龟，吾與汝鄰。"]', '诗', 'shi', '', NULL, '龜銘 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46fd2d2-c301-4a2d-b2dc-d711002dc368', '梳銘', '梳銘', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["有髮兮朝朝思理，有身兮胡不如是。"]', '["有髮兮朝朝思理，有身兮胡不如是。"]', '诗', 'shi', '', NULL, '梳銘 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc34b08a-2f2f-4e84-83e7-5ec4bf590d97', '小婦吟', '小婦吟', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["小婦欲入門，隈門勻紅妝。","大婦出門迎，正頓羅衣裳。","門邊兩相見，笑樂不可當。","夫子於傍聊斷腸，小婦哆㖷上高堂。","開玉匣，取琴張。","陳金罍，酌滿觴。","顧言兩相樂，永與同心事我郎。","夫子於傍剩欲狂，珠簾風度百花香。","翠帳雲屏白玉牀，啼鳥休啼花莫笑，女英新喜得娥皇。"]', '["小婦欲入门，隈门勻紅妝。","大婦出门迎，正頓羅衣裳。","门邊兩相见，笑乐不可當。","夫子於傍聊斷腸，小婦哆㖷上高堂。","开玉匣，取琴張。","陳金罍，酌满觴。","顧言兩相乐，永與同心事我郎。","夫子於傍剩欲狂，珠簾风度百花香。","翠帳云屏白玉牀，啼鸟休啼花莫笑，女英新喜得娥皇。"]', '诗', 'shi', '', NULL, '小婦吟 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fc2889f-6a5b-4219-bac2-26d55463ade5', '月下寄徐希仁', '月下寄徐希仁', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["夜半沙上行，月瑩天心明。","沙月浩無際，此中離思生。","上天何寥廓，下地何崢嶸。","吾道豈已矣，爲君傾兕觥。"]', '["夜半沙上行，月瑩天心明。","沙月浩無際，此中離思生。","上天何寥廓，下地何崢嶸。","吾道豈已矣，爲君傾兕觥。"]', '诗', 'shi', '', NULL, '月下寄徐希仁 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc21d4e2-2331-4059-b838-60c1576202d1', '贈徐希仁石硯別', '贈徐希仁石硯別', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["靈山一片不靈石，手斲成器心所惜。","鳳鳥不至池不成，蛟龍乾蟠水空滴。","青松火鍊翠煙凝，寒竹風搖遠天碧。","今日贈君離別心，此中至淺造化深。","用之可以過珪璧，棄置還爲一片石。"]', '["靈山一片不靈石，手斲成器心所惜。","鳳鸟不至池不成，蛟龙乾蟠水空滴。","青松火鍊翠煙凝，寒竹风搖远天碧。","今日贈君離別心，此中至淺造化深。","用之可以過珪璧，棄置還爲一片石。"]', '诗', 'shi', '', NULL, '贈徐希仁石硯別 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25009c82-a1b6-47cb-9a8c-56050539f556', '有所思', '有所思', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["當時我醉美人家，美人顏色嬌如花。","今日美人棄我去，青樓珠箔天之涯。","天涯娟娟姮娥月，三五二八盈又缺。","翠眉蟬鬢生別離，一望不見心斷絕。","心斷絕，幾千里。","夢中醉臥巫山雲，覺來淚滴湘江水。","湘江兩岸花木深，美人不見愁人心。","含愁更奏綠綺琴，調高弦絕無知音。","美人兮美人，不知爲暮雨兮爲朝雲。","相思一夜梅花發，忽到窗前疑是君。"]', '["當时我醉美人家，美人顏色嬌如花。","今日美人棄我去，青楼珠箔天之涯。","天涯娟娟姮娥月，三五二八盈又缺。","翠眉蟬鬢生別離，一望不见心斷絕。","心斷絕，幾千里。","梦中醉臥巫山云，覺来泪滴湘江水。","湘江兩岸花木深，美人不见愁人心。","含愁更奏綠綺琴，調高弦絕無知音。","美人兮美人，不知爲暮雨兮爲朝云。","相思一夜梅花發，忽到窗前疑是君。"]', '诗', 'shi', '', NULL, '有所思 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ceeebbc-4292-4d5a-ac04-4f224e649636', '樓上女兒曲', '楼上女兒曲', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["誰家女兒樓上頭，指揮婢子挂簾鉤。","林花撩亂心之愁，卷却羅袖彈箜篌。","箜篌歷亂五六弦，羅袖掩面啼向天。","相思弦斷情不斷，落花紛紛心欲穿。","心欲穿，憑欄干。","相憶柳條綠，相思錦帳寒。","直緣感君恩愛一迴顧，使我雙淚長珊珊。","我有嬌靨待君笑，我有嬌蛾待君掃。","鶯花爛熳君不來，及至君來花已老。","心腸寸斷誰得知，玉堦冪歷生青草。"]', '["誰家女兒楼上头，指揮婢子挂簾鉤。","林花撩亂心之愁，卷却羅袖彈箜篌。","箜篌歷亂五六弦，羅袖掩面啼向天。","相思弦斷情不斷，落花紛紛心欲穿。","心欲穿，憑欄干。","相憶柳條綠，相思錦帳寒。","直緣感君恩愛一迴顧，使我雙泪长珊珊。","我有嬌靨待君笑，我有嬌蛾待君掃。","鶯花爛熳君不来，及至君来花已老。","心腸寸斷誰得知，玉堦冪歷生青草。"]', '诗', 'shi', '', NULL, '樓上女兒曲 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c683683-1221-476c-be6e-0e7a0e34c25e', '秋夢行', '秋梦行', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["客行一夜秋風起，客夢南遊渡湘水。","湘水泠泠徹底清，二妃怨處無限情。","娥皇不語啓嬌靨，女英目成轉心愜。","長眉入鬢何連娟，肌膚白玉秀且鮮。","裴回共詠東方日，沈吟再理南風弦。","聲斷續，思綿綿，中含幽意兩不宣。","殷勤纖手驚破夢，中宵寂寞心悽然。","心悽然，腸亦絕。","寐不寐兮玉枕寒，夜深夜兮霜似雪。","鏡中不見雙翠眉，臺前空挂纖纖月。","纖纖月，盈復缺，娟娟似眉意難訣。","願此眉兮如此月，千里萬里光不滅。"]', '["客行一夜秋风起，客梦南游渡湘水。","湘水泠泠徹底清，二妃怨处無限情。","娥皇不語啓嬌靨，女英目成轉心愜。","长眉入鬢何連娟，肌膚白玉秀且鲜。","裴回共詠东方日，沈吟再理南风弦。","声斷續，思綿綿，中含幽意兩不宣。","殷勤纖手驚破梦，中宵寂寞心悽然。","心悽然，腸亦絕。","寐不寐兮玉枕寒，夜深夜兮霜似雪。","镜中不见雙翠眉，台前空挂纖纖月。","纖纖月，盈复缺，娟娟似眉意难訣。","願此眉兮如此月，千里万里光不滅。"]', '诗', 'shi', '', NULL, '秋夢行 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81f82a1d-d40f-407d-8a33-ae6d458c0e3e', '自君之出矣', '自君之出矣', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["自君之出矣，壁上蜘蛛織。","近取見妾心，夜夜無休息。","妾有雙玉環，寄君表相憶。","環是妾之心，玉是君之德。","馳情增悴容，蓄思損精力。","玉簟寒悽悽，延想心惻惻。","風含霜月明，水泛碧天色。","此水有盡時，此情無終極。"]', '["自君之出矣，壁上蜘蛛织。","近取见妾心，夜夜無休息。","妾有雙玉环，寄君表相憶。","环是妾之心，玉是君之德。","驰情增悴容，蓄思損精力。","玉簟寒悽悽，延想心惻惻。","风含霜月明，水泛碧天色。","此水有尽时，此情無終極。"]', '诗', 'shi', '', NULL, '自君之出矣 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f33754e-1fb7-4140-8654-d729e9254a10', '走筆謝孟諫議寄新茶', '走笔謝孟諫議寄新茶', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["日高丈五睡正濃，軍將打門驚周公。","口云諫議送書信，白絹斜封三道印。","開緘宛見諫議面，手閱月團三百片。","聞道新年入山裏，蟄蟲驚動春風起。","天子須嘗陽羨茶，百草不敢先開花。","仁風暗結珠琲瓃，先春抽出黃金芽。","摘鮮焙芳旋封裹，至精至好且不奢。","至尊之餘合王公，何事便到山人家。","柴門反關無俗客，紗帽籠頭自煎喫。","碧雲引風吹不斷，白花浮光凝椀面。","一椀喉吻潤，兩椀破孤悶。","三椀搜枯腸，唯有文字五千卷。","四椀發輕汗，平生不平事。","盡向毛孔散，五椀肌骨清。","六椀通仙靈，七椀喫不得也。","唯覺兩腋習習清風生，蓬萊山，在何處？","玉川子，乘此清風欲歸去。","山上羣仙司下土，地位清高隔風雨。","安得知百萬億蒼生命，墮在巔崖受辛苦。","便爲諫議問蒼生，到頭還得蘇息否。"]', '["日高丈五睡正濃，軍將打门驚周公。","口云諫議送书信，白絹斜封三道印。","开緘宛见諫議面，手閱月團三百片。","闻道新年入山裏，蟄蟲驚动春风起。","天子須嘗陽羨茶，百草不敢先开花。","仁风暗結珠琲瓃，先春抽出黄金芽。","摘鲜焙芳旋封裹，至精至好且不奢。","至尊之餘合王公，何事便到山人家。","柴门反关無俗客，紗帽籠头自煎喫。","碧云引风吹不斷，白花浮光凝椀面。","一椀喉吻潤，兩椀破孤悶。","三椀搜枯腸，唯有文字五千卷。","四椀發轻汗，平生不平事。","尽向毛孔散，五椀肌骨清。","六椀通仙靈，七椀喫不得也。","唯覺兩腋習習清风生，蓬萊山，在何处？","玉川子，乘此清风欲归去。","山上羣仙司下土，地位清高隔风雨。","安得知百万億蒼生命，墮在巔崖受辛苦。","便爲諫議问蒼生，到头還得蘇息否。"]', '诗', 'shi', '', NULL, '走筆謝孟諫議寄新茶 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fac0cea-b4ee-419b-9802-786d508141f9', '冬行三首 一', '冬行三首 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["蟲豸臘月皆在蟄，吾獨何乃勞其形。","小大無由知天命，但怪守道不得寧。","老母妻子一揮手，涕下便作千里行。","自顧不及遭霜葉，旦夕保得同飄零。","達生何足云，偶然苦樂經其身。","古來堯孔與桀跖，善惡何補如今人。"]', '["蟲豸臘月皆在蟄，吾独何乃勞其形。","小大無由知天命，但怪守道不得寧。","老母妻子一揮手，涕下便作千里行。","自顧不及遭霜葉，旦夕保得同飄零。","達生何足云，偶然苦乐經其身。","古来堯孔與桀跖，善惡何補如今人。"]', '诗', 'shi', '', NULL, '冬行三首 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1afe4765-24bf-4454-9663-7d3f5fdbcefd', '冬行三首 二', '冬行三首 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["長年愛伊洛，決計卜長久。","賒買里仁宅，水竹且小有。","賣宅將還資，舊業苦不厚。","債家徵利心，餓虎血染口。","臘風刀刻肌，遂向東南走。","賢哉韓員外，勸我莫強取。","憑風謝長者，敢不愧心苟。","賃載得估舟，估雜非吾偶。","壯色排榻席，別座夸羊酒。","落日無精光，啞暝被掣肘。","漕石生齒牙，洗灘亂相掫。","奔澌嚼篙杖，夾岸雪龍吼。","可憐聖明朝，還爲喪家狗。","通運隔南溟，債利拄北斗。","揚州屋舍賤，還債堪了不。","此宅貯書籍，地濕憂蠹朽。","賈僎舊相識，十年與營守。","貧交多變態，僎得君子不。","利命子罕言，我誠孔門醜。","且貴終焉圖，死免慙狐首。","何當歸帝鄉，白雲永相友。"]', '["长年愛伊洛，決計卜长久。","賒買里仁宅，水竹且小有。","賣宅將還資，旧業苦不厚。","債家徵利心，餓虎血染口。","臘风刀刻肌，遂向东南走。","賢哉韓員外，勸我莫強取。","憑风謝长者，敢不愧心苟。","賃載得估舟，估杂非吾偶。","壯色排榻席，別座夸羊酒。","落日無精光，啞暝被掣肘。","漕石生齒牙，洗灘亂相掫。","奔澌嚼篙杖，夾岸雪龙吼。","可怜聖明朝，還爲喪家狗。","通運隔南溟，債利拄北斗。","揚州屋舍賤，還債堪了不。","此宅貯书籍，地濕憂蠹朽。","賈僎旧相識，十年與營守。","貧交多变態，僎得君子不。","利命子罕言，我誠孔门醜。","且貴終焉圖，死免慙狐首。","何當归帝乡，白云永相友。"]', '诗', 'shi', '', NULL, '冬行三首 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56148045-3c5d-4d26-ac33-0fab19d30e23', '冬行三首 三', '冬行三首 三', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["不敢唾汴水，汴水入東海。","汚泥龍王宮，恐獲不敬罪。","不敢蹋汴堤，汴堤連秦宮。","蹋盡天子土，饋餫無由通。","此言雖太闊，且是臣心腸。","野風結陰兵，千里鳴刀槍。","海月護羇魄，到曉點孤光。","上不事天子，下不識侯王。","夜半睡獨覺，爽氣盈心堂。","顏子甚年少，孔聖同行藏。","我年過顏子，敢道不自強。","船人雖奴兵，亦有意智長。","問我何所得，樂色填清揚。","我報果有爲，孔經在衣裳。"]', '["不敢唾汴水，汴水入东海。","汚泥龙王宮，恐獲不敬罪。","不敢蹋汴堤，汴堤連秦宮。","蹋尽天子土，饋餫無由通。","此言雖太闊，且是臣心腸。","野风結陰兵，千里鳴刀槍。","海月護羇魄，到晓点孤光。","上不事天子，下不識侯王。","夜半睡独覺，爽氣盈心堂。","顏子甚年少，孔聖同行藏。","我年過顏子，敢道不自強。","船人雖奴兵，亦有意智长。","问我何所得，乐色填清揚。","我報果有爲，孔經在衣裳。"]', '诗', 'shi', '', NULL, '冬行三首 三 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ab323d7-8bea-45ff-8bc0-5a018dbb7707', '常州孟諫議座上聞韓員外職方貶國子博士有感五首 一', '常州孟諫議座上闻韓員外職方貶国子博士有感五首 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["忽見除書到，韓君又學官。","死生縱有命，人事始知難。","烈火先燒玉，庭蕪不養蘭。","山夫與刺史，相對兩巑岏。"]', '["忽见除书到，韓君又学官。","死生縱有命，人事始知难。","烈火先燒玉，庭蕪不養蘭。","山夫與刺史，相对兩巑岏。"]', '诗', 'shi', '', NULL, '常州孟諫議座上聞韓員外職方貶國子博士有感五首 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f6cb8bf-c3fd-410b-abe2-01174beb3dbb', '常州孟諫議座上聞韓員外職方貶國子博士有感五首 二', '常州孟諫議座上闻韓員外職方貶国子博士有感五首 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["干祿無便佞，宜知黜此身。","員郎猶小小，國學大頻頻。","孤宦心肝直，天王苦死嗔。","朝廷無諫議，誰是雪韓人。"]', '["干祿無便佞，宜知黜此身。","員郎猶小小，国学大頻頻。","孤宦心肝直，天王苦死嗔。","朝廷無諫議，誰是雪韓人。"]', '诗', 'shi', '', NULL, '常州孟諫議座上聞韓員外職方貶國子博士有感五首 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44d6bf6-f460-4736-bca8-39ac88e509d4', '常州孟諫議座上聞韓員外職方貶國子博士有感五首 三', '常州孟諫議座上闻韓員外職方貶国子博士有感五首 三', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["何事遭朝貶，知何被不容。","不如思所自，只欲涕無從。","爵服何曾好，荷衣已慣縫。","朝官莫相識，歸去老巖松。"]', '["何事遭朝貶，知何被不容。","不如思所自，只欲涕無從。","爵服何曾好，荷衣已慣縫。","朝官莫相識，归去老巖松。"]', '诗', 'shi', '', NULL, '常州孟諫議座上聞韓員外職方貶國子博士有感五首 三 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf43c26-4521-4b77-841b-27df85b36a01', '常州孟諫議座上聞韓員外職方貶國子博士有感五首 四', '常州孟諫議座上闻韓員外職方貶国子博士有感五首 四', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["力小垂垂上，天高又不登。","致身唯一己，獲罪則顏朋。","祿位埋坑穽，康莊壘劒稜。","公卿共惜取，莫遣玉山崩。"]', '["力小垂垂上，天高又不登。","致身唯一己，獲罪則顏朋。","祿位埋坑穽，康莊壘劒稜。","公卿共惜取，莫遣玉山崩。"]', '诗', 'shi', '', NULL, '常州孟諫議座上聞韓員外職方貶國子博士有感五首 四 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29f67424-a9c8-4065-895b-d0ab93422b9a', '常州孟諫議座上聞韓員外職方貶國子博士有感五首 五', '常州孟諫議座上闻韓員外職方貶国子博士有感五首 五', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["誰憐野田子，海內一韓侯。","左道官雖樂，剛腸得健無。","功名生地獄，禮教死天囚。","莫言耕種好，須避蒺藜秋。"]', '["誰怜野田子，海內一韓侯。","左道官雖乐，剛腸得健無。","功名生地獄，禮教死天囚。","莫言耕種好，須避蒺藜秋。"]', '诗', 'shi', '', NULL, '常州孟諫議座上聞韓員外職方貶國子博士有感五首 五 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ee0b9cd-d5c0-4ae2-99cd-84f862aaa02b', '夏夜聞蚯蚓吟', '夏夜闻蚯蚓吟', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["夏夜雨欲作，傍砌蚯蚓吟。","念爾無筋骨，也應天地心。","汝無親朋累，汝無名利侵。","孤韻似有說，哀怨何其深。","泛泛輕薄子，旦夕還謳吟。","肝膽異汝輩，熱血徒相侵。"]', '["夏夜雨欲作，傍砌蚯蚓吟。","念爾無筋骨，也應天地心。","汝無親朋累，汝無名利侵。","孤韻似有说，哀怨何其深。","泛泛轻薄子，旦夕還謳吟。","肝膽異汝輩，熱血徒相侵。"]', '诗', 'shi', '', NULL, '夏夜聞蚯蚓吟 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f658ef82-ee49-4fc2-b63f-81fe26a6bc06', '揚州送伯齡過江', '揚州送伯齡過江', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["伯齡不厭山，山不養伯齡。","松顛有樵墮，石上無禾生。","不忍六尺軀，遂作東南行。","諸侯盡食肉，壯氣吞八紘。","不唧溜鈍漢，何由通姓名。","夷齊餓死日，武王稱聖明。","節義士枉死，何異鴻毛輕。","努力事干謁，我心終不平。"]', '["伯齡不厭山，山不養伯齡。","松顛有樵墮，石上無禾生。","不忍六尺軀，遂作东南行。","諸侯尽食肉，壯氣吞八紘。","不唧溜鈍漢，何由通姓名。","夷齊餓死日，武王稱聖明。","節義士枉死，何異鴻毛轻。","努力事干謁，我心終不平。"]', '诗', 'shi', '', NULL, '揚州送伯齡過江 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c71c254-efaf-47d0-bee9-057f1136e0b7', '憶金鵝山沈山人二首 一', '憶金鵝山沈山人二首 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["君家山頭松樹風，適來入我竹林裏。","一片新茶破鼻香，請君速來助我喜。","莫合九轉大還丹，莫讀三十六部大洞經。","閑來共我說真意，齒下領取真長生。","不須服藥求神仙，神仙意智或偶然。","自古聖賢放入土，淮南雞犬驅上天。","白日上昇應不惡，藥成且輙一丸藥。","暫時上天少問天，蛇頭蝎尾誰安著。"]', '["君家山头松樹风，適来入我竹林裏。","一片新茶破鼻香，請君速来助我喜。","莫合九轉大還丹，莫读三十六部大洞經。","闲来共我说真意，齒下領取真长生。","不須服藥求神仙，神仙意智或偶然。","自古聖賢放入土，淮南雞犬驱上天。","白日上昇應不惡，藥成且輙一丸藥。","暫时上天少问天，蛇头蝎尾誰安著。"]', '诗', 'shi', '', NULL, '憶金鵝山沈山人二首 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a51666c-2ed6-4b2e-97f8-dfbc457fd9ec', '憶金鵝山沈山人二首 二', '憶金鵝山沈山人二首 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["君愛鍊藥藥欲成，我愛鍊骨骨已清。","試自比校得仙者，也應合得天上行。","天門九重高崔嵬，清空鑿出黃金堆。","夜叉守門晝不啓，夜半醮祭夜半開。","夜叉喜歡動關鎖，鎖聲㩧地生風雷。","地上禽獸重血食，性命血化飛黃埃。","太上道君蓮花臺，九門隔闊安在哉？","嗚呼！沈君大藥成，兼須巧會鬼物情，無求長生喪厥生。"]', '["君愛鍊藥藥欲成，我愛鍊骨骨已清。","試自比校得仙者，也應合得天上行。","天门九重高崔嵬，清空鑿出黄金堆。","夜叉守门晝不啓，夜半醮祭夜半开。","夜叉喜歡动关鎖，鎖声㩧地生风雷。","地上禽獸重血食，性命血化飞黄埃。","太上道君蓮花台，九门隔闊安在哉？","嗚呼！沈君大藥成，兼須巧會鬼物情，無求长生喪厥生。"]', '诗', 'shi', '', NULL, '憶金鵝山沈山人二首 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b0d49ff-7769-43a0-b6e4-976cd4faa115', '寄蕭二十三慶中', '寄蕭二十三慶中', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["蕭乎蕭乎，憶蕭者嵩山之盧。","盧揚州，蕭歙州。","相思過春花，鬢毛生麥秋。","千災萬怪天南道，猩猩鸚鵡皆人言。","山魈吹火蟲入椀，鴆鳥咒詛鮫吐涎。","就中南瘴欺北客，憑君數磨犀角喫。","我憶君心千百間，千百間君何時還，使我夜夜勞魂魄。"]', '["蕭乎蕭乎，憶蕭者嵩山之盧。","盧揚州，蕭歙州。","相思過春花，鬢毛生麦秋。","千災万怪天南道，猩猩鸚鵡皆人言。","山魈吹火蟲入椀，鴆鸟咒詛鮫吐涎。","就中南瘴欺北客，憑君數磨犀角喫。","我憶君心千百间，千百间君何时還，使我夜夜勞魂魄。"]', '诗', 'shi', '', NULL, '寄蕭二十三慶中 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a24a9f0-a89c-4b78-910f-ee4d8e51ea31', '贈金鵝山人沈師魯', '贈金鵝山人沈師魯', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["金鵝山中客，來到揚州市。","買藥牀頭一破顏，撇然便有上天意。","日月高挂玄關深，金膏切淬肌骨異。","人皆食穀與五味，獨食太和陰陽氣。","浩浩流珠走百關，綿綿若存有深致。","種玉不耕山外非內粹，鑿儒關決文泉彰。","風雅因君不復墜，光不外照刃不磨。","迴避人間惡富貴，三日四日五六日。","盤礴化元搜萬類，晝飲興酣陶天和。","夜話造微□精魅，示我插血不死方。","賞我風格不肥膩，肉眼不識天上書。","小儒安敢窺奧祕，崑崙路隔西北天。","三山後浮不著地，君到頭來憶我時，金簡爲吾鐫一字。"]', '["金鵝山中客，来到揚州市。","買藥牀头一破顏，撇然便有上天意。","日月高挂玄关深，金膏切淬肌骨異。","人皆食穀與五味，独食太和陰陽氣。","浩浩流珠走百关，綿綿若存有深致。","種玉不耕山外非內粹，鑿儒关決文泉彰。","风雅因君不复墜，光不外照刃不磨。","迴避人间惡富貴，三日四日五六日。","盤礴化元搜万類，晝饮兴酣陶天和。","夜話造微□精魅，示我插血不死方。","賞我风格不肥膩，肉眼不識天上书。","小儒安敢窺奧祕，崑崙路隔西北天。","三山後浮不著地，君到头来憶我时，金簡爲吾鐫一字。"]', '诗', 'shi', '', NULL, '贈金鵝山人沈師魯 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('085d992c-6234-4aa5-98bf-0aa2189f3353', '歎昨日三首 一', '歎昨日三首 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["昨日之日不可追，今日之日須臾期。","如此如此復如此，壯心死盡生鬢絲。","秋風落葉客腸斷，不辦斗酒開愁眉。","賢名聖行甚辛苦，周公孔子徒自欺。"]', '["昨日之日不可追，今日之日須臾期。","如此如此复如此，壯心死尽生鬢絲。","秋风落葉客腸斷，不辦斗酒开愁眉。","賢名聖行甚辛苦，周公孔子徒自欺。"]', '诗', 'shi', '', NULL, '歎昨日三首 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5179515-796e-467d-b744-3ab3494f1238', '歎昨日三首 二', '歎昨日三首 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["天下薄夫苦耽酒，玉川先生也耽酒。","薄夫有錢恣張樂，先生無錢養恬漠。","有錢無錢俱可憐，百年驟過如流川。","平生心事消散盡，天上白日悠悠懸。"]', '["天下薄夫苦耽酒，玉川先生也耽酒。","薄夫有錢恣張乐，先生無錢養恬漠。","有錢無錢俱可怜，百年驟過如流川。","平生心事消散尽，天上白日悠悠懸。"]', '诗', 'shi', '', NULL, '歎昨日三首 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27e447ee-3210-40f1-8e5a-299cda7ccc9b', '歎昨日三首 三', '歎昨日三首 三', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["上帝板板主何物，日車劫劫西向沒。","自古賢聖無奈何，道行不得皆白骨。","白骨土化鬼入泉，生人莫負平生年。","何時出得禁酒國，滿甕釀酒曝背眠。"]', '["上帝板板主何物，日车劫劫西向沒。","自古賢聖無奈何，道行不得皆白骨。","白骨土化鬼入泉，生人莫負平生年。","何时出得禁酒国，满甕釀酒曝背眠。"]', '诗', 'shi', '', NULL, '歎昨日三首 三 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b79b11a-be68-48be-ad32-9920a6b12b77', '月蝕詩', '月蝕诗', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["東海出明月，清明照毫髮。","朱弦初罷彈，金兔正奇絕。","三五與二八，此時光滿時。","頗奈蝦𢋙兒，吞我芳桂枝。","我愛明鏡潔，爾乃痕翳之。","爾且無六翮，焉得升天涯。","方寸有白刃，無由揚清輝。","如何萬里光，遭爾小物欺。","却吐天漢中，良久素魄微。","日月尚如此，人情良可知。"]', '["东海出明月，清明照毫髮。","朱弦初罷彈，金兔正奇絕。","三五與二八，此时光满时。","頗奈蝦𢋙兒，吞我芳桂枝。","我愛明镜潔，爾乃痕翳之。","爾且無六翮，焉得升天涯。","方寸有白刃，無由揚清輝。","如何万里光，遭爾小物欺。","却吐天漢中，良久素魄微。","日月尚如此，人情良可知。"]', '诗', 'shi', '', NULL, '月蝕詩 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34abb2d3-a044-4ea5-aa2e-232ac5dd93aa', '直鉤吟', '直鉤吟', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["初歲學釣魚，自謂魚易得。","三十持釣竿，一魚釣不得。","人鉤曲，我鉤直，哀哉我鉤又無食。"]', '["初歲学釣鱼，自謂鱼易得。","三十持釣竿，一鱼釣不得。","人鉤曲，我鉤直，哀哉我鉤又無食。"]', '诗', 'shi', '', NULL, '直鉤吟 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49d493f7-226a-4782-a0aa-cbe9b0ea4671', '與馬異結交詩', '與马異結交诗', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["天地日月如等閑，盧仝四十無往還。","唯有一片心脾骨，巉巖崒硉兀鬱律。","刀劒爲峰㟧，平地放著高如崑崙山。","天不容，地不受，日月不敢偷照耀。","神農畫八卦，鑿破天心胸。","女媧本是伏羲婦，恐天怒。","擣鍊五色石，引日月之針，五星之縷把天補。","補了三日不肯歸壻家，走向日中放老鵶。","月裏栽桂養蝦𢋙，天公發怒化龍蛇。","此龍此蛇得死病，神農合藥救死命。","天怪神農黨龍蛇，罰神農爲牛頭。","令載元氣車，不知藥中有毒藥。","藥殺元氣天不覺，爾來天地不神聖。","日月之光無正定，不知元氣元不死。","忽聞空中喚馬異，馬異若不是祥瑞。","空中敢道不容易，昨日仝不仝，異自異，是謂大仝而小異。","今日仝自仝，異不異，是謂仝不往兮異不至。","直當中兮動天地，白玉璞裏斵出相思心。","黃金鑛裏鑄出相思淚，忽聞空中崩崖倒谷聲。","絕勝明珠千萬斛，買得西施南威一雙婢。","此婢嬌饒惱殺人，凝脂爲膚翡翠裙。","唯解畫眉朱點脣，自從獲得君。","敲金摐玉凌浮雲，却返顧。","一雙婢子何足云，平生結交若少人。","憶君眼前如見君，青雲欲開白日沒。","天眼不見此奇骨，此骨縱橫奇又奇。","千歲萬歲枯松枝，半折半殘壓山谷。","盤根蹙節成蛟螭，忽雷霹靂卒風暴雨撼不動。","欲動不動千變萬化總是鱗皴皮，此奇怪物不可欺。","盧仝見馬異文章，酌得馬異胸中事。","風姿骨本恰如此，是不是。"]', '["天地日月如等闲，盧仝四十無往還。","唯有一片心脾骨，巉巖崒硉兀鬱律。","刀劒爲峰㟧，平地放著高如崑崙山。","天不容，地不受，日月不敢偷照耀。","神農畫八卦，鑿破天心胸。","女媧本是伏羲婦，恐天怒。","擣鍊五色石，引日月之針，五星之縷把天補。","補了三日不肯归壻家，走向日中放老鵶。","月裏栽桂養蝦𢋙，天公發怒化龙蛇。","此龙此蛇得死病，神農合藥救死命。","天怪神農黨龙蛇，罰神農爲牛头。","令載元氣车，不知藥中有毒藥。","藥殺元氣天不覺，爾来天地不神聖。","日月之光無正定，不知元氣元不死。","忽闻空中喚马異，马異若不是祥瑞。","空中敢道不容易，昨日仝不仝，異自異，是謂大仝而小異。","今日仝自仝，異不異，是謂仝不往兮異不至。","直當中兮动天地，白玉璞裏斵出相思心。","黄金鑛裏鑄出相思泪，忽闻空中崩崖倒谷声。","絕勝明珠千万斛，買得西施南威一雙婢。","此婢嬌饒惱殺人，凝脂爲膚翡翠裙。","唯解畫眉朱点脣，自從獲得君。","敲金摐玉凌浮云，却返顧。","一雙婢子何足云，平生結交若少人。","憶君眼前如见君，青云欲开白日沒。","天眼不见此奇骨，此骨縱橫奇又奇。","千歲万歲枯松枝，半折半殘壓山谷。","盤根蹙節成蛟螭，忽雷霹靂卒风暴雨撼不动。","欲动不动千变万化總是鱗皴皮，此奇怪物不可欺。","盧仝见马異文章，酌得马異胸中事。","风姿骨本恰如此，是不是。"]', '诗', 'shi', '', NULL, '與馬異結交詩 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0605938-ef92-4d3e-b031-e8cb113851ac', '感古四首 一', '感古四首 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["天生聖明君，必資忠賢臣。","舜禹竭股肱，共佐堯爲君。","四載成地理，七政齊天文。","階下蓂莢生，琴上南風薰。","輪轉夏殷周，時復猶一人。","秦漢事讒巧，魏晉忘機鈞。","猜忌相翦滅，爾來迷恩親。","以愚保其身，不覺身沈淪。","以智理其國，遂爲國之賊。","苟圖容一身，萬事良可惻。","可憐萬乘君，聰明受沈惑。","忠良伏草莽，無因施羽翼。","日月異又蝕，天地晦如墨。","既亢而後求，異哉龍之德。"]', '["天生聖明君，必資忠賢臣。","舜禹竭股肱，共佐堯爲君。","四載成地理，七政齊天文。","階下蓂莢生，琴上南风薰。","輪轉夏殷周，时复猶一人。","秦漢事讒巧，魏晉忘機鈞。","猜忌相翦滅，爾来迷恩親。","以愚保其身，不覺身沈淪。","以智理其国，遂爲国之賊。","苟圖容一身，万事良可惻。","可怜万乘君，聰明受沈惑。","忠良伏草莽，無因施羽翼。","日月異又蝕，天地晦如墨。","既亢而後求，異哉龙之德。"]', '诗', 'shi', '', NULL, '感古四首 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7cbf2e2-135e-4220-931b-aa406aff8545', '感古四首 二', '感古四首 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["人生何所貴，所貴有終始。","昨日盈尺璧，今朝盡瑕棄。","蒼蠅點垂棘，巧舌成錦綺。","箕子爲之奴，比干諫而死。","仲尼魯司寇，出走爲羣婢。","假如屈原醒，其奈一國醉。","一國醉號呶，一人行清高。","便欲激頹波，此事真徒勞。","上山逢猛虎，入海逢巨鼇。","王者苟不死，腰下魚鱗刀。","東海波連天，三度成桑田。","高岸高於屋，斯須變溪谷。","天地猶尚然，人情難久全。","夜半白刃讐，旦來金石堅。","蕭綬既解坼，陳印亦棄捐。","竭節遇刀割，輸忠遭禍纏。","不予衾之眠，信予衾之穿。","鏡明不自照，膏潤徒自煎。","抱劍長太息，淚墮秋風前。"]', '["人生何所貴，所貴有終始。","昨日盈尺璧，今朝尽瑕棄。","蒼蠅点垂棘，巧舌成錦綺。","箕子爲之奴，比干諫而死。","仲尼魯司寇，出走爲羣婢。","假如屈原醒，其奈一国醉。","一国醉號呶，一人行清高。","便欲激頹波，此事真徒勞。","上山逢猛虎，入海逢巨鼇。","王者苟不死，腰下鱼鱗刀。","东海波連天，三度成桑田。","高岸高於屋，斯須变溪谷。","天地猶尚然，人情难久全。","夜半白刃讐，旦来金石堅。","蕭綬既解坼，陳印亦棄捐。","竭節遇刀割，輸忠遭禍纏。","不予衾之眠，信予衾之穿。","镜明不自照，膏潤徒自煎。","抱劍长太息，泪墮秋风前。"]', '诗', 'shi', '', NULL, '感古四首 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5482de02-7c4d-4eee-9c39-550fa181d847', '感古四首 三', '感古四首 三', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["古來不患寡，所患患不均。","單醪投長河，三軍盡沈淪。","今人異古人，結託唯親賓。","毀坼維鵲巢，不行鳲鳩仁。","鄙恡不識分，有心占陽春。","鸞鶴日已疎，燕雀日已親。","小物無大志，安測棲松筠。","恩眷多棄故，物情尚逐新。","瓦礫暫拂拭，光掩連城珍。","脣吻恣談鑠，黃金同灰塵。","蘇秦北遊趙，張祿西入秦。","既變嫂叔節，仍擯華陽君。","萬世金石交，一餉如浮雲。","骨肉且不顧，何況長羈貧。"]', '["古来不患寡，所患患不均。","單醪投长河，三軍尽沈淪。","今人異古人，結託唯親賓。","毀坼維鵲巢，不行鳲鳩仁。","鄙恡不識分，有心占陽春。","鸾鹤日已疎，燕雀日已親。","小物無大志，安測棲松筠。","恩眷多棄故，物情尚逐新。","瓦礫暫拂拭，光掩連城珍。","脣吻恣談鑠，黄金同灰塵。","蘇秦北游趙，張祿西入秦。","既变嫂叔節，仍擯华陽君。","万世金石交，一餉如浮云。","骨肉且不顧，何況长羈貧。"]', '诗', 'shi', '', NULL, '感古四首 三 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c8a4fd5-ec11-47b9-9fa9-f593c78f1dd6', '感古四首 四', '感古四首 四', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["君莫以富貴，輕忽他年少。","聽我暫話會稽朱太守，正受凍餓時。","索得人家貴傲婦，讀書書史未潤身。","負薪辛苦胝生肘，謂言琴與瑟。","糟糠結長久，不分殺人羽翮成。","臨臨沖天婦嫌醜，□□□□□□□。","其奈一朝太守振羽儀，鄉關晝行衣錦衣。","哀哉舊婦何眉目，新壻隨行向天哭。","寸心金石徒爾爲，杯水庭沙空自覆。","乃知愚婦人，妬忌陰毒心。","唯救眼底事，不思日月深。","等閑取羞死，豈如甘布衾。"]', '["君莫以富貴，轻忽他年少。","听我暫話會稽朱太守，正受凍餓时。","索得人家貴傲婦，读书书史未潤身。","負薪辛苦胝生肘，謂言琴與瑟。","糟糠結长久，不分殺人羽翮成。","臨臨沖天婦嫌醜，□□□□□□□。","其奈一朝太守振羽儀，乡关晝行衣錦衣。","哀哉旧婦何眉目，新壻隨行向天哭。","寸心金石徒爾爲，杯水庭沙空自覆。","乃知愚婦人，妬忌陰毒心。","唯救眼底事，不思日月深。","等闲取羞死，豈如甘布衾。"]', '诗', 'shi', '', NULL, '感古四首 四 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f008105c-31b5-4425-a657-0190d8ccb568', '雜興', '杂兴', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["意志未成百不解，見人富貴亦心愛。","等閑對酒呼三達，屠羊殺牛皆自在。","放心爲樂笙歌攢，壯氣激作風霜寒。","廚中玉饌盈金盤，方丈厭見嫌不餐。","飛鷹躍馬實快性，脣腐齒爛空巑岏。","豈期福極翻成禍，禍成身誅家亦破。","昨朝惆悵不如君，今日悲君不如我。","否泰交加無定主，嬾學風雲戢翎羽。","綠酒清琴好養生，出將入相無心取。","三五圖書舊揣摩，五千道德新䂓矩。"]', '["意志未成百不解，见人富貴亦心愛。","等闲对酒呼三達，屠羊殺牛皆自在。","放心爲乐笙歌攢，壯氣激作风霜寒。","廚中玉饌盈金盤，方丈厭见嫌不餐。","飞鷹躍马實快性，脣腐齒爛空巑岏。","豈期福極翻成禍，禍成身誅家亦破。","昨朝惆悵不如君，今日悲君不如我。","否泰交加無定主，嬾学风云戢翎羽。","綠酒清琴好養生，出將入相無心取。","三五圖书旧揣摩，五千道德新䂓矩。"]', '诗', 'shi', '', NULL, '雜興 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6e9c969b-01de-455e-9897-95790e017031', '酬徐公以新文見招', '酬徐公以新文见招', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["昨夜霜月明，果有清音生。","便欲走相和，愁聞寒玉聲。"]', '["昨夜霜月明，果有清音生。","便欲走相和，愁闻寒玉声。"]', '诗', 'shi', '', NULL, '酬徐公以新文見招 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a33c0ea-0d03-4d50-83c1-ca030bbd4628', '門箴', '门箴', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["貪殘奸酗，狡佞訐愎。","身之八殺，背惠，恃己。","狎不肖，妬賢能。","命之四孽，有是有此予敢辭。","無是無此予之師，一日不見予心思。","思其人，懼其人。","其交其難，敢告于門。"]', '["貪殘奸酗，狡佞訐愎。","身之八殺，背惠，恃己。","狎不肖，妬賢能。","命之四孽，有是有此予敢辞。","無是無此予之師，一日不见予心思。","思其人，懼其人。","其交其难，敢告于门。"]', '诗', 'shi', '', NULL, '門箴 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7a08144-c10f-44ef-8558-7064cc123c68', '孟夫子生生亭賦', '孟夫子生生亭賦', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["玉川子沿孟冬之寒流兮，輟櫂上登生生亭。","夫子何之兮，面逐雲沒兮南行。","百川注海而心不寫兮，落日千里凝寒精。","予日衰期人生之世斯已矣，爰爲今日猶猶岐路之心生。","悲夫！南國風濤，魚龍畜伏。","予小子戇朴，必不能濟夫子欲。","嗟自慙承夫子而不失予兮，傳古道甚分明。","予且廣孤目遐賷于天壤兮，庶得外盡萬物變化之幽情。","然後慙愧而來歸兮，大息吾躬于夫子之亭。"]', '["玉川子沿孟冬之寒流兮，輟櫂上登生生亭。","夫子何之兮，面逐云沒兮南行。","百川注海而心不寫兮，落日千里凝寒精。","予日衰期人生之世斯已矣，爰爲今日猶猶岐路之心生。","悲夫！南国风濤，鱼龙畜伏。","予小子戇朴，必不能濟夫子欲。","嗟自慙承夫子而不失予兮，傳古道甚分明。","予且廣孤目遐賷于天壤兮，庶得外尽万物变化之幽情。","然後慙愧而来归兮，大息吾躬于夫子之亭。"]', '诗', 'shi', '', NULL, '孟夫子生生亭賦 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a55ca5a-de6c-4286-90a0-e57ed2adfeec', '走筆追王內丘', '走笔追王內丘', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["自識夫子面，便獲夫子心。","夫子一啓顏，義重千黃金。","平原孟嘗骨已土，始有夫子堪知音。","忽然夫子不語，帶蓆帽，騎驢去。","余對醁醽不能斟，君且來，余之瞻望心悠哉。","零雨其濛愁不散，閑花寂寂斑堦苔。","不如對此景，含笑傾金罍。","莫問四肢暢，暫取眉頭開。","弦琴待夫子，夫子來不來。"]', '["自識夫子面，便獲夫子心。","夫子一啓顏，義重千黄金。","平原孟嘗骨已土，始有夫子堪知音。","忽然夫子不語，带蓆帽，騎驢去。","余对醁醽不能斟，君且来，余之瞻望心悠哉。","零雨其濛愁不散，闲花寂寂斑堦苔。","不如对此景，含笑傾金罍。","莫问四肢暢，暫取眉头开。","弦琴待夫子，夫子来不来。"]', '诗', 'shi', '', NULL, '走筆追王內丘 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f07f68a9-44c3-46d2-ba95-d54b51080a77', '思君吟寄□□生', '思君吟寄□□生', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["我思君兮河之壖，我爲河中之泉，君爲河中之青天。","天青青，泉泠泠。","泉含青天天隔泉，我思君兮心亦然。","心亦然，此心復在天之側。","我心爲風兮淅淅，君身爲雲兮羃羃。","此風引此雲兮雲不來，此風此雲兮何悠哉，與我身心雙裴回。"]', '["我思君兮河之壖，我爲河中之泉，君爲河中之青天。","天青青，泉泠泠。","泉含青天天隔泉，我思君兮心亦然。","心亦然，此心复在天之側。","我心爲风兮淅淅，君身爲云兮羃羃。","此风引此云兮云不来，此风此云兮何悠哉，與我身心雙裴回。"]', '诗', 'shi', '', NULL, '思君吟寄□□生 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7adf7cb1-c2fc-48b8-b0da-afc846ccfbda', '將歸山招冰僧', '將归山招冰僧', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["買得一片田，濟源花洞前。","千里石壁坼，一條流泌泉。","青松盤樛枝，森森上插青冥天。","枝上有□猨，宿處近鶴巢。","清唳孤吟聲相交，月輪下射空洞響，絲篁成韻風蕭蕭。","我心塵外心，愛此塵外物。","欲結塵外交，苦無塵外骨。","泌泉有冰公，心靜見真佛。","可結塵外交，占此松與月。"]', '["買得一片田，濟源花洞前。","千里石壁坼，一條流泌泉。","青松盤樛枝，森森上插青冥天。","枝上有□猨，宿处近鹤巢。","清唳孤吟声相交，月輪下射空洞响，絲篁成韻风蕭蕭。","我心塵外心，愛此塵外物。","欲結塵外交，苦無塵外骨。","泌泉有冰公，心静见真佛。","可結塵外交，占此松與月。"]', '诗', 'shi', '', NULL, '將歸山招冰僧 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8cf8714-e532-4480-b383-40518617e24c', '詶願公雪中見寄', '詶願公雪中见寄', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["積雪三十日，車馬路不通。","貧病交親絕，想憶唯願公。","春鳩報春歸，苦寒生暗風。","簷乳墮懸玉，日脚浮輕紅。","梅柳意却活，園圃冰始融。","更候四體好，方可到寺中。"]', '["積雪三十日，车马路不通。","貧病交親絕，想憶唯願公。","春鳩報春归，苦寒生暗风。","簷乳墮懸玉，日脚浮轻紅。","梅柳意却活，园圃冰始融。","更候四體好，方可到寺中。"]', '诗', 'shi', '', NULL, '詶願公雪中見寄 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edd3c229-3ebe-407a-bdb4-c68a740456b2', '苦雪寄退之', '苦雪寄退之', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["天王二月行時令，白銀作雪漫天涯。","山人門前徧受賜，平地一尺白玉沙。","雲頹月壞桂英下，鶴毛風剪亂參差。","山人屋中[凍]欲死，千樹萬樹飛春花。","菜頭出土膠入地，山莊取粟埋却車。","冷絮刀生削峭骨，冷虀斧破慰老牙。","病妻煙眼淚滴滴，飢嬰哭乳聲呶呶。","市頭博米不用物，酒店買酒不肯賒。","聞道西風弄劒戟，長堦殺人如亂麻。","天眼高開欺草芽，我死未肯興歎嗟。","但恨口中無酒氣，劉伶見我相揄揶。","清風攪腸筋力絕，白灰壓屋梁柱斜。","聖明有道□命漢，可得再見朝日耶。","柴門沒脛晝不埽，黃昏遶樹棲寒鴉。","唯有河南韓縣令，時時醉飽過貧家。"]', '["天王二月行时令，白銀作雪漫天涯。","山人门前徧受賜，平地一尺白玉沙。","云頹月壞桂英下，鹤毛风剪亂參差。","山人屋中[凍]欲死，千樹万樹飞春花。","菜头出土膠入地，山莊取粟埋却车。","冷絮刀生削峭骨，冷虀斧破慰老牙。","病妻煙眼泪滴滴，飢嬰哭乳声呶呶。","市头博米不用物，酒店買酒不肯賒。","闻道西风弄劒戟，长堦殺人如亂麻。","天眼高开欺草芽，我死未肯兴歎嗟。","但恨口中無酒氣，劉伶见我相揄揶。","清风攪腸筋力絕，白灰壓屋梁柱斜。","聖明有道□命漢，可得再见朝日耶。","柴门沒脛晝不埽，黄昏遶樹棲寒鴉。","唯有河南韓縣令，时时醉飽過貧家。"]', '诗', 'shi', '', NULL, '苦雪寄退之 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9b43b1b-2edd-4129-9f05-4eea40538815', '寄贈含曦上人', '寄贈含曦上人', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["楞伽大師兄，誇曦識道理。","破鏁推玄關，高辯果難揣。","論語老莊易，搜索通神鬼。","起信中百門，敲骨得佛髓。","此外雜經律，泛讀一萬紙。","高殿排名僧，執卷坐纍纍。","化物自一心，三教齊發起。","隨鐘嚼宮商，滿口文字美。","商賈女郎輩，不曾道生死。","縱遇彊禮拜，雅語不露齒。","劈破天地來，節義可屈指。","季展即此僧，孤立無依倚。","近來愛作詩，新奇頗煩委。","忽忽造古格，削盡俗綺靡。","假如慵裹頭，但勤讀書史。","切磋併工夫，休遠不可比。","憐僧無遠□，信佛殊未已。","貌古饒風情，清論興亹亹。","訪余十數度，相去三五里。","見時心亦喜，不見心亦喜。","見時談謔樂，四座盡角嘴。","不見養天和，無人聒人耳。","昨朝披雪來，面色赤韡韡。","封竈養黃金，許割方寸匕。","泥丸佛□教，怛化莊亦耻。","未達不敢嘗，孔子疑季子。","藥成必分余，余必投泥裏。","不如向陽堂，撥醅泛浮蟻。","麴米本無愆，酒成是法水。","行道不見心，毀譽徒云爾。","雪晴天氣和，日光弄梅李。","春鳥嬌關關，春風醉旎旎。","道上正無塵，人家有花卉。","高僧有拄杖，願得數覯止。"]', '["楞伽大師兄，誇曦識道理。","破鏁推玄关，高辯果难揣。","論語老莊易，搜索通神鬼。","起信中百门，敲骨得佛髓。","此外杂經律，泛读一万紙。","高殿排名僧，執卷坐纍纍。","化物自一心，三教齊發起。","隨鐘嚼宮商，满口文字美。","商賈女郎輩，不曾道生死。","縱遇彊禮拜，雅語不露齒。","劈破天地来，節義可屈指。","季展即此僧，孤立無依倚。","近来愛作诗，新奇頗煩委。","忽忽造古格，削尽俗綺靡。","假如慵裹头，但勤读书史。","切磋併工夫，休远不可比。","怜僧無远□，信佛殊未已。","貌古饒风情，清論兴亹亹。","訪余十數度，相去三五里。","见时心亦喜，不见心亦喜。","见时談謔乐，四座尽角嘴。","不见養天和，無人聒人耳。","昨朝披雪来，面色赤韡韡。","封竈養黄金，許割方寸匕。","泥丸佛□教，怛化莊亦耻。","未達不敢嘗，孔子疑季子。","藥成必分余，余必投泥裏。","不如向陽堂，撥醅泛浮蟻。","麴米本無愆，酒成是法水。","行道不见心，毀譽徒云爾。","雪晴天氣和，日光弄梅李。","春鸟嬌关关，春风醉旎旎。","道上正無塵，人家有花卉。","高僧有拄杖，願得數覯止。"]', '诗', 'shi', '', NULL, '寄贈含曦上人 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d159bac-5591-4cea-b4be-a8189dcd002e', '聽蕭君姬人彈琴', '听蕭君姬人彈琴', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["彈琴人似膝上琴，聽琴人似匣中弦。","二物各一處，音韻何由傳。","無風質氣兩相感，萬般悲意方纏綿。","初時天山之外飛白雪，漸漸萬丈澗地生流泉。","風梅花落輕揚揚，十指乾淨聲涓涓。","昭君可惜嫁單于，沙場不遠只眼前。","蔡琰薄命沒胡虜，烏梟啾唧啼胡天。","關山險隔一萬里，顏色錯漠生風煙。","形魄散逐五音盡，雙蛾結草空嬋娟。","中腹苦恨杳不極，新心愁絕難復傳。","金尊湛湛夜沈沈，餘音疊發清聯綿。","主人醉盈有得色，座客向隅增內然。","孔子怪責顏回瑟，野夫何事蕭君筵。","拂衣屢命請中廢，月照書窗歸獨眠。"]', '["彈琴人似膝上琴，听琴人似匣中弦。","二物各一处，音韻何由傳。","無风質氣兩相感，万般悲意方纏綿。","初时天山之外飞白雪，漸漸万丈澗地生流泉。","风梅花落轻揚揚，十指乾淨声涓涓。","昭君可惜嫁單于，沙場不远只眼前。","蔡琰薄命沒胡虜，烏梟啾唧啼胡天。","关山險隔一万里，顏色錯漠生风煙。","形魄散逐五音尽，雙蛾結草空嬋娟。","中腹苦恨杳不極，新心愁絕难复傳。","金尊湛湛夜沈沈，餘音叠發清聯綿。","主人醉盈有得色，座客向隅增內然。","孔子怪責顏回瑟，野夫何事蕭君筵。","拂衣屢命請中廢，月照书窗归独眠。"]', '诗', 'shi', '', NULL, '聽蕭君姬人彈琴 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd604a5e-6500-41f4-91cb-37957d8d961f', '蜻蜓歌', '蜻蜓歌', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["黃河中流日影斜，水天一色無津涯。","處處驚波噴流飛雪花，篙工檝師力且武。","進寸退尺莫能度，吾甚懼。","念汝小蟲子，造化借羽翼。","隨風戲中流，翩然有餘力。","吾不如汝無他，無羽翼。","吾若有羽翼，則上叩天關。","爲聖君請賢臣，布惠化于人間。","然後東飛浴東溟，吸日精。","撼若木之英，紛而零。","使地上學仙之子，得而食之皆長生。","不學汝無端小蟲子，葉葉水上無一事，忽遭風雨水中死。"]', '["黄河中流日影斜，水天一色無津涯。","处处驚波噴流飞雪花，篙工檝師力且武。","進寸退尺莫能度，吾甚懼。","念汝小蟲子，造化借羽翼。","隨风戲中流，翩然有餘力。","吾不如汝無他，無羽翼。","吾若有羽翼，則上叩天关。","爲聖君請賢臣，布惠化于人间。","然後东飞浴东溟，吸日精。","撼若木之英，紛而零。","使地上学仙之子，得而食之皆长生。","不学汝無端小蟲子，葉葉水上無一事，忽遭风雨水中死。"]', '诗', 'shi', '', NULL, '蜻蜓歌 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe37afc9-aa87-4bd6-963c-18680677f581', '出山作', '出山作', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["出山忘掩山門路，釣竿插在枯桑樹。","當時只有鳥窺窬，更亦無人得知處。","家僮若失釣魚竿，定是猨猴把將去。"]', '["出山忘掩山门路，釣竿插在枯桑樹。","當时只有鸟窺窬，更亦無人得知处。","家僮若失釣鱼竿，定是猨猴把將去。"]', '诗', 'shi', '', NULL, '出山作 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35ba3b04-173b-479d-a01f-d90e9f988722', '寄崔柳州', '寄崔柳州', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["使者立取書，疊紙生百憂。","使君若不信，他時看白頭。","三百六十州，尅情惟柳州。","柳州蠻天末，鄙夫嵩之幽。","花落隴水頭，各自東西流。","凜凜長相逐，爲謝池上鷗。"]', '["使者立取书，叠紙生百憂。","使君若不信，他时看白头。","三百六十州，尅情惟柳州。","柳州蠻天末，鄙夫嵩之幽。","花落隴水头，各自东西流。","凜凜长相逐，爲謝池上鷗。"]', '诗', 'shi', '', NULL, '寄崔柳州 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d11d433d-29f4-47e8-99a3-91bb21b3f50b', '贈稚禪師', '贈稚禪師', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["春風滿禪院，師獨坐南軒。","萬化見中盡，始覺靜性尊。","我來契平生，目擊道自存。","與師不動遊，遊此無迹門。"]', '["春风满禪院，師独坐南軒。","万化见中尽，始覺静性尊。","我来契平生，目擊道自存。","與師不动游，游此無迹门。"]', '诗', 'shi', '', NULL, '贈稚禪師 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fefc1f8-1294-4635-a7c8-31354af6cace', '送好約法師歸江南', '送好約法師归江南', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["杯度度一身，法度度萬民。","爲報江南三二日，這回應見雪中人。"]', '["杯度度一身，法度度万民。","爲報江南三二日，這回應见雪中人。"]', '诗', 'shi', '', NULL, '送好約法師歸江南 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c200cc4-403f-415b-a379-d1f52f4b1e3c', '蕭二十三赴歙州婚期二首 一', '蕭二十三赴歙州婚期二首 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["淮上客情殊冷落，蠻方春早客何如。","相思莫道無來使，迴雁峯前好寄書。"]', '["淮上客情殊冷落，蠻方春早客何如。","相思莫道無来使，迴雁峯前好寄书。"]', '诗', 'shi', '', NULL, '蕭二十三赴歙州婚期二首 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0cf5ac-21e0-44fe-9a34-b3d4f1912d5a', '蕭二十三赴歙州婚期二首 二', '蕭二十三赴歙州婚期二首 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["南方山水生時興，教有新詩得寄余。","路帶長安迢遰急，多應不逐使君書。"]', '["南方山水生时兴，教有新诗得寄余。","路带长安迢遰急，多應不逐使君书。"]', '诗', 'shi', '', NULL, '蕭二十三赴歙州婚期二首 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d1553c3-e3fc-4073-9512-1e6b16f06046', '掩關銘', '掩关銘', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["蛇毒毒有形，藥毒毒有名。","人毒毒在心，對面如弟兄。","美言不可聽，深於千丈坑。","不如掩關坐，幽鳥時一聲。"]', '["蛇毒毒有形，藥毒毒有名。","人毒毒在心，对面如弟兄。","美言不可听，深於千丈坑。","不如掩关坐，幽鸟时一声。"]', '诗', 'shi', '', NULL, '掩關銘 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80fc47d5-a784-443d-ac9c-b4d17845d161', '逢病軍人', '逢病軍人', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["行多有病住無糧，萬里還鄉未到鄉。","蓬鬢哀吟古城下，不堪秋氣入金瘡。"]', '["行多有病住無糧，万里還乡未到乡。","蓬鬢哀吟古城下，不堪秋氣入金瘡。"]', '诗', 'shi', '', NULL, '逢病軍人 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f23edbec-77aa-4290-9908-8f2cedccdc15', '山中', '山中', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["飢拾松花渴飲泉，偶從山後到山前。","陽坡軟草厚如織，困與鹿麛相伴眠。"]', '["飢拾松花渴饮泉，偶從山後到山前。","陽坡軟草厚如织，困與鹿麛相伴眠。"]', '诗', 'shi', '', NULL, '山中 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc767cf6-5731-4a4c-9cf9-7df7e0a9b31e', '除夜 一', '除夜 一', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["衰殘歸未遂，寂寞此宵情。","舊國餘千里，新年隔數更。","寒猶近北峭，風漸向東生。","惟見長安陌，晨鐘度火城。"]', '["衰殘归未遂，寂寞此宵情。","旧国餘千里，新年隔數更。","寒猶近北峭，风漸向东生。","惟见长安陌，晨鐘度火城。"]', '诗', 'shi', '', NULL, '除夜 一 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55dc5769-3159-4269-b65f-081c50d3664c', '除夜 二', '除夜 二', 'bb2cc027-a0c0-48e8-9064-b2de26f2c78b', '唐', '["殷勤惜此夜，此夜在逡巡。","燭盡年還別，雞鳴老更新。","儺聲方去病，酒色已迎春。","明日持杯處，誰爲最後人。"]', '["殷勤惜此夜，此夜在逡巡。","燭尽年還別，雞鳴老更新。","儺声方去病，酒色已迎春。","明日持杯处，誰爲最後人。"]', '诗', 'shi', '', NULL, '除夜 二 盧仝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af691759-fafe-4b65-893b-e37af39cbf6a', '李憑箜篌引', '李憑箜篌引', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["吳絲蜀桐張高秋，空白凝雲頹不流。","江娥啼竹素女愁，李憑中國彈箜篌。","崑山玉碎鳳皇呌，芙蓉泣露香蘭笑。","十二門前融冷光，二十三絲動紫皇。","女媧鍊石補天處，石破天驚逗秋雨。","夢入坤山教神嫗，老魚跳波瘦蛟舞。","吳質不眠倚桂樹，露脚斜飛溼寒兔。"]', '["吳絲蜀桐張高秋，空白凝云頹不流。","江娥啼竹素女愁，李憑中国彈箜篌。","崑山玉碎鳳皇呌，芙蓉泣露香蘭笑。","十二门前融冷光，二十三絲动紫皇。","女媧鍊石補天处，石破天驚逗秋雨。","梦入坤山教神嫗，老鱼跳波瘦蛟舞。","吳質不眠倚桂樹，露脚斜飞溼寒兔。"]', '诗', 'shi', '', NULL, '李憑箜篌引 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60f418f1-447d-4916-b885-1cbab41f3bb8', '殘絲曲', '殘絲曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["垂楊葉老鶯哺兒，殘絲欲斷黃蜂歸。","綠鬢年少金釵客，縹粉壺中沈琥珀。","花臺欲暮春辭去，落花起作迴風舞。","榆莢相催不知數，沈郎青錢夾城路。"]', '["垂楊葉老鶯哺兒，殘絲欲斷黄蜂归。","綠鬢年少金釵客，縹粉壺中沈琥珀。","花台欲暮春辞去，落花起作迴风舞。","榆莢相催不知數，沈郎青錢夾城路。"]', '诗', 'shi', '', NULL, '殘絲曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb9c11f4-96b8-4445-9ca8-7a6f7c87da21', '還自會稽歌', '還自會稽歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["野粉椒壁黃，溼螢滿梁殿。","臺城應教人，秋衾夢銅輦。","吳霜點歸鬢，身與塘蒲晚。","脈脈辭金魚，羈臣守迍賤。"]', '["野粉椒壁黄，溼螢满梁殿。","台城應教人，秋衾梦銅輦。","吳霜点归鬢，身與塘蒲晚。","脈脈辞金鱼，羈臣守迍賤。"]', '诗', 'shi', '', NULL, '還自會稽歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28565010-46b8-4425-a301-c7127f25b0cd', '出城寄權璩楊敬之', '出城寄權璩楊敬之', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["草暖雲昏萬里春，宮花拂面送行人。","自言漢劒當飛去，何事還車載病身。"]', '["草暖云昏万里春，宮花拂面送行人。","自言漢劒當飞去，何事還车載病身。"]', '诗', 'shi', '', NULL, '出城寄權璩楊敬之 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('114321a4-5ada-4be8-8bae-1e6fb19d4e6f', '示弟', '示弟', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["別弟三年後，還家一日餘。","醁醽今夕酒，緗帙去時書。","病骨猶能在，人間底事無。","何須問牛馬，拋擲任梟盧。"]', '["別弟三年後，還家一日餘。","醁醽今夕酒，緗帙去时书。","病骨猶能在，人间底事無。","何須问牛马，拋擲任梟盧。"]', '诗', 'shi', '', NULL, '示弟 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('67cdba49-3ca4-4a9c-a2c2-ba0e179c93f4', '竹', '竹', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["入水文光動，抽空綠影春。","露華生筍逕，苔色拂霜根。","織可承香汗，裁堪釣錦鱗。","三梁曾入用，一節奉王孫。"]', '["入水文光动，抽空綠影春。","露华生筍逕，苔色拂霜根。","织可承香汗，裁堪釣錦鱗。","三梁曾入用，一節奉王孫。"]', '诗', 'shi', '', NULL, '竹 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06007eea-c3e4-4a76-86c1-c2917fdff50f', '同沈駙馬賦得御溝水', '同沈駙马賦得御溝水', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["入苑白泱泱，宮入正靨黃。","遶堤龍骨冷，拂岸鴨頭香。","別館驚殘夢，停杯泛小觴。","幸因流浪處，暫得見何郎。"]', '["入苑白泱泱，宮入正靨黄。","遶堤龙骨冷，拂岸鴨头香。","別館驚殘梦，停杯泛小觴。","幸因流浪处，暫得见何郎。"]', '诗', 'shi', '', NULL, '同沈駙馬賦得御溝水 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1bec046f-3d2a-4202-8402-29a7f60269ee', '始爲奉禮憶昌谷山居', '始爲奉禮憶昌谷山居', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["掃斷馬蹄痕，衙迴自閉門。","長鎗江米熟，小樹棗花春。","向壁懸如意，當簾閱角巾。","犬書曾去洛，鶴病悔遊秦。","土甑封茶葉，山盃鎖竹根。","不知船上月，誰櫂滿溪雲。"]', '["掃斷马蹄痕，衙迴自閉门。","长鎗江米熟，小樹棗花春。","向壁懸如意，當簾閱角巾。","犬书曾去洛，鹤病悔游秦。","土甑封茶葉，山盃鎖竹根。","不知船上月，誰櫂满溪云。"]', '诗', 'shi', '', NULL, '始爲奉禮憶昌谷山居 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('833084ff-f269-4288-ad2b-6a62817f4c49', '七夕', '七夕', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["別浦今朝暗，羅帷午夜愁。","鵲辭穿線月，花入曝衣樓。","天上分金鏡，人間望玉鉤。","錢塘蘇小小，更值一年秋。"]', '["別浦今朝暗，羅帷午夜愁。","鵲辞穿線月，花入曝衣楼。","天上分金镜，人间望玉鉤。","錢塘蘇小小，更值一年秋。"]', '诗', 'shi', '', NULL, '七夕 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7251348-a89b-45a4-aa43-ac2156854063', '過華清宮', '過华清宮', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["春月夜啼鴉，宮簾隔御花。","雲生朱絡暗，石斷紫錢斜。","玉椀盛殘露，銀燈點舊紗。","蜀王無近信，泉上有芹芽。"]', '["春月夜啼鴉，宮簾隔御花。","云生朱絡暗，石斷紫錢斜。","玉椀盛殘露，銀灯点旧紗。","蜀王無近信，泉上有芹芽。"]', '诗', 'shi', '', NULL, '過華清宮 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('851cd22f-1855-4daf-8578-dc0d3170570a', '送沈亞之歌', '送沈亞之歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["吳興才人怨春風，桃花滿陌千里紅。","紫絲竹斷騘馬小，家住錢塘東復東。","白藤交穿織書笈，短策齊裁如梵夾。","雄光寶礦獻春卿，煙底驀波乘一葉。","春卿拾材白日下，擲置黃金解龍馬。","攜笈歸江重入門，勞勞誰是憐君者。","吾聞壯夫重心骨，古人三走無摧捽。","請君待旦事長鞭，他日還轅及秋律。"]', '["吳兴才人怨春风，桃花满陌千里紅。","紫絲竹斷騘马小，家住錢塘东复东。","白藤交穿织书笈，短策齊裁如梵夾。","雄光寶礦獻春卿，煙底驀波乘一葉。","春卿拾材白日下，擲置黄金解龙马。","携笈归江重入门，勞勞誰是怜君者。","吾闻壯夫重心骨，古人三走無摧捽。","請君待旦事长鞭，他日還轅及秋律。"]', '诗', 'shi', '', NULL, '送沈亞之歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e4aa75a-c9d0-42d6-b470-3c933525d99d', '詠懷二首 一', '詠懷二首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長卿懷茂陵，綠草垂石井。","彈琴看文君，春風吹鬢影。","梁王與武帝，棄之如斷梗。","惟留一簡書，金泥泰山頂。"]', '["长卿懷茂陵，綠草垂石井。","彈琴看文君，春风吹鬢影。","梁王與武帝，棄之如斷梗。","惟留一簡书，金泥泰山頂。"]', '诗', 'shi', '', NULL, '詠懷二首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08f4c7c2-b546-4c58-ab26-d07d53c83330', '詠懷二首 二', '詠懷二首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["日夕著書罷，驚霜落素絲。","鏡中聊自笑，詎是南山期。","頭上無幅巾，苦蘗已染衣。","不見清溪魚，飲水得自宜。"]', '["日夕著书罷，驚霜落素絲。","镜中聊自笑，詎是南山期。","头上無幅巾，苦蘗已染衣。","不见清溪鱼，饮水得自宜。"]', '诗', 'shi', '', NULL, '詠懷二首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('285d8546-7dc9-41ef-97ce-fbe35e8bb9c0', '追和柳惲', '追和柳惲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["汀洲白蘋草，柳惲乘馬歸。","江頭樝樹香，岸上蝴蝶飛。","酒盃箬葉露，玉軫蜀桐虛。","朱樓通水陌，沙暖一雙魚。"]', '["汀洲白蘋草，柳惲乘马归。","江头樝樹香，岸上蝴蝶飞。","酒盃箬葉露，玉軫蜀桐虛。","朱楼通水陌，沙暖一雙鱼。"]', '诗', 'shi', '', NULL, '追和柳惲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14bb787d-e384-4568-a9b7-d6dd6a447125', '春坊正字劒子歌', '春坊正字劒子歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["先輩匣中三尺水，曾入吳潭斬龍子。","隙月斜明刮露寒，練帶平鋪吹不起。","蛟胎皮老蒺藜刺，鸊鵜淬花白鷴尾。","直是荆軻一片心，莫教照見春坊字。","挼絲團金懸䍡𦌉，神光欲截藍田玉。","提出西方白帝驚，嗷嗷鬼母秋郊哭。"]', '["先輩匣中三尺水，曾入吳潭斬龙子。","隙月斜明刮露寒，練带平鋪吹不起。","蛟胎皮老蒺藜刺，鸊鵜淬花白鷴尾。","直是荆軻一片心，莫教照见春坊字。","挼絲團金懸䍡𦌉，神光欲截藍田玉。","提出西方白帝驚，嗷嗷鬼母秋郊哭。"]', '诗', 'shi', '', NULL, '春坊正字劒子歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f873896-d13b-474f-a111-3c36beb1455c', '貴公子夜闌曲', '貴公子夜闌曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["褭褭沈水煙，烏啼夜闌景。","曲沼芙蓉波，腰圍白玉冷。"]', '["褭褭沈水煙，烏啼夜闌景。","曲沼芙蓉波，腰圍白玉冷。"]', '诗', 'shi', '', NULL, '貴公子夜闌曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec77a99-b8d7-4845-b03e-47704d8f4fd9', '雁門太守行', '雁门太守行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["黑雲壓城城欲摧，甲光向日金鱗開。","角聲滿天秋色裏，塞上燕脂凝夜紫。","半卷紅旗臨易水，霜重鼓寒聲不起。","報君黃金臺上意，提攜玉龍爲君死。"]', '["黑云壓城城欲摧，甲光向日金鱗开。","角声满天秋色裏，塞上燕脂凝夜紫。","半卷紅旗臨易水，霜重鼓寒声不起。","報君黄金台上意，提携玉龙爲君死。"]', '诗', 'shi', '', NULL, '雁門太守行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62f91b86-6227-4527-bb0b-21cd0bb40c68', '大堤曲', '大堤曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["妾家住橫塘，紅紗滿桂香。","青雲教綰頭上髻，明月與作耳邊璫。","蓮風起，江畔春。","大堤上，留北人。","郎食鯉魚尾，妾食猩猩脣。","莫指襄陽道，綠浦歸帆少。","今日菖蒲花，明朝楓樹老。"]', '["妾家住橫塘，紅紗满桂香。","青云教綰头上髻，明月與作耳邊璫。","蓮风起，江畔春。","大堤上，留北人。","郎食鯉鱼尾，妾食猩猩脣。","莫指襄陽道，綠浦归帆少。","今日菖蒲花，明朝楓樹老。"]', '诗', 'shi', '', NULL, '大堤曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cdb9ef73-95e2-4c70-8ab7-3512bdd7899a', '蜀國弦', '蜀国弦', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["楓香晚花靜，錦水南山影。","驚石墜猨哀，竹雲愁半嶺。","涼月生秋浦，玉沙粼粼光。","誰家紅淚客，不忍過瞿塘。"]', '["楓香晚花静，錦水南山影。","驚石墜猨哀，竹云愁半嶺。","涼月生秋浦，玉沙粼粼光。","誰家紅泪客，不忍過瞿塘。"]', '诗', 'shi', '', NULL, '蜀國弦 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5123af54-01dd-4aa8-aa3d-0f4147076fb3', '蘇小小墓', '蘇小小墓', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["幽蘭露，如啼眼。","無物結同心，煙花不堪剪。","草如茵，松如蓋。","風爲裳，水爲珮。","油壁車，夕相待。","冷翠燭，勞光彩。","西陵下，風吹雨。"]', '["幽蘭露，如啼眼。","無物結同心，煙花不堪剪。","草如茵，松如蓋。","风爲裳，水爲珮。","油壁车，夕相待。","冷翠燭，勞光彩。","西陵下，风吹雨。"]', '诗', 'shi', '', NULL, '蘇小小墓 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('812cff97-e2ca-447b-abf6-76617a8f77f8', '夢天', '梦天', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["老兔寒蟾泣天色，雲樓半開壁斜白。","玉輪軋露溼團光，鸞珮相逢桂香陌。","黃塵清水三山下，更變千年如走馬。","遙望齊州九點煙，一泓海水杯中瀉。"]', '["老兔寒蟾泣天色，云楼半开壁斜白。","玉輪軋露溼團光，鸾珮相逢桂香陌。","黄塵清水三山下，更变千年如走马。","遙望齊州九点煙，一泓海水杯中瀉。"]', '诗', 'shi', '', NULL, '夢天 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d47b5ddf-b6b3-4cab-b622-9638c75f9d05', '唐兒歌', '唐兒歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["頭玉磽磽眉刷翠，杜郎生得真男子。","骨重神寒天廟器，一雙瞳人剪秋水。","竹馬梢梢搖綠尾，銀鸞睒光踏半臂。","東家嬌娘求對值，濃笑畫空作唐字。","眼大心雄知所以，莫忘作歌人姓李。"]', '["头玉磽磽眉刷翠，杜郎生得真男子。","骨重神寒天廟器，一雙瞳人剪秋水。","竹马梢梢搖綠尾，銀鸾睒光踏半臂。","东家嬌娘求对值，濃笑畫空作唐字。","眼大心雄知所以，莫忘作歌人姓李。"]', '诗', 'shi', '', NULL, '唐兒歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3342f18-e2fa-4cf0-9cb7-22dac3b27996', '綠章封事', '綠章封事', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["青霓扣額呼宮神，鴻龍玉狗開天門。","石榴花發滿溪津，溪女洗花染白雲。","綠章封事諮元父，六街馬蹄浩無主。","虛空風氣不清泠，短衣小冠作塵土。","金家香衖千輪鳴，楊雄秋室無俗聲。","願攜漢戟招書鬼，休令恨骨填蒿里。"]', '["青霓扣額呼宮神，鴻龙玉狗开天门。","石榴花發满溪津，溪女洗花染白云。","綠章封事諮元父，六街马蹄浩無主。","虛空风氣不清泠，短衣小冠作塵土。","金家香衖千輪鳴，楊雄秋室無俗声。","願携漢戟招书鬼，休令恨骨填蒿里。"]', '诗', 'shi', '', NULL, '綠章封事 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('914d9fc8-19ec-440a-bc48-3cef9caa8768', '河南府試十二月樂詞 正月', '河南府試十二月乐词 正月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["上樓迎春新春歸，暗黃著柳宮漏遲。","薄薄淡靄弄野姿，寒綠幽風生短絲。","錦牀曉臥玉肌冷，露臉未開對朝暝。","官街柳帶不堪折，早晚菖蒲勝綰結。"]', '["上楼迎春新春归，暗黄著柳宮漏遲。","薄薄淡靄弄野姿，寒綠幽风生短絲。","錦牀晓臥玉肌冷，露臉未开对朝暝。","官街柳带不堪折，早晚菖蒲勝綰結。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 正月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125b75c6-8e96-40ba-88b9-7ee641cf8f09', '河南府試十二月樂詞 二月', '河南府試十二月乐词 二月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["二月飲酒採桑津，宜男草生蘭笑人。","蒲如交劒風如薰，勞勞胡燕怨酣春。","薇帳逗煙生綠塵，金翹峨髻愁暮雲。","沓颯起舞真珠裙，津頭送別唱流水，酒客背寒南山死。"]', '["二月饮酒採桑津，宜男草生蘭笑人。","蒲如交劒风如薰，勞勞胡燕怨酣春。","薇帳逗煙生綠塵，金翹峨髻愁暮云。","沓颯起舞真珠裙，津头送別唱流水，酒客背寒南山死。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 二月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4cca6a-fe64-4cb3-86af-e9768374ed35', '河南府試十二月樂詞 三月', '河南府試十二月乐词 三月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["東方風來滿眼春，花城柳暗愁殺人。","複宮深殿竹風起，新翠舞衿淨如水。","光風轉蕙百餘里，暖霧驅雲撲天地。","軍裝宮妓掃蛾淺，搖搖錦旗夾城暖。","曲水漂香去不歸，梨花落盡成秋苑。"]', '["东方风来满眼春，花城柳暗愁殺人。","複宮深殿竹风起，新翠舞衿淨如水。","光风轉蕙百餘里，暖霧驱云撲天地。","軍裝宮妓掃蛾淺，搖搖錦旗夾城暖。","曲水漂香去不归，梨花落尽成秋苑。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 三月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2679bd1-a495-4b9b-9388-cdebc0fae71b', '河南府試十二月樂詞 四月', '河南府試十二月乐词 四月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["曉涼暮涼樹如蓋，千山濃綠生雲外。","依微香雨青氛氳，膩葉蟠花照曲門。","金塘閑水搖碧漪，老景沈重無驚飛，墮紅殘萼暗參差。"]', '["晓涼暮涼樹如蓋，千山濃綠生云外。","依微香雨青氛氳，膩葉蟠花照曲门。","金塘闲水搖碧漪，老景沈重無驚飞，墮紅殘萼暗參差。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 四月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0b70e60-687b-4300-a82f-5ef31807f377', '河南府試十二月樂詞 五月', '河南府試十二月乐词 五月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["雕玉押簾額，輕縠籠虛門。","井汲鉛華水，扇織鴛鴦紋。","迴雪舞涼殿，甘露洗空綠。","羅袖從徊翔，香汗沾寶粟。"]', '["雕玉押簾額，轻縠籠虛门。","井汲鉛华水，扇织鴛鴦紋。","迴雪舞涼殿，甘露洗空綠。","羅袖從徊翔，香汗沾寶粟。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 五月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94a3e3ca-a454-4c8d-a7ac-db2972824153', '河南府試十二月樂詞 六月', '河南府試十二月乐词 六月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["裁生羅，伐湘竹。","帔拂疎霜簟秋玉，炎炎紅鏡東方開。","暈如車輪上裴回，啾啾赤帝騎龍來。"]', '["裁生羅，伐湘竹。","帔拂疎霜簟秋玉，炎炎紅镜东方开。","暈如车輪上裴回，啾啾赤帝騎龙来。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 六月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd9c6e48-67cc-4572-ac94-c84fa2fe2102', '河南府試十二月樂詞 七月', '河南府試十二月乐词 七月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["星依雲渚冷，露滴盤中圓。","好花生木末，衰蕙愁空園。","夜天如玉砌，池葉極青錢。","僅厭舞衫薄，稍知花簟寒。","曉風何拂拂，北斗光闌干。"]', '["星依云渚冷，露滴盤中圓。","好花生木末，衰蕙愁空园。","夜天如玉砌，池葉極青錢。","僅厭舞衫薄，稍知花簟寒。","晓风何拂拂，北斗光闌干。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 七月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('449f1e98-a05e-49b7-9889-9ec3b83028f5', '河南府試十二月樂詞 八月', '河南府試十二月乐词 八月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["孀妾怨夜長，獨客夢歸家。","傍簷蟲緝絲，向壁燈垂花。","簾外月光吐，簾內樹影斜。","悠悠飛露姿，點綴池中荷。"]', '["孀妾怨夜长，独客梦归家。","傍簷蟲緝絲，向壁灯垂花。","簾外月光吐，簾內樹影斜。","悠悠飞露姿，点綴池中荷。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 八月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('490c93ea-fe03-429a-bb4a-7449b67b010d', '河南府試十二月樂詞 九月', '河南府試十二月乐词 九月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["離宮散螢天似水，竹黃池冷芙蓉死。","月綴金鋪光脈脈，涼苑虛庭空澹白。","露花飛飛風草草，翠錦斕斑滿層道。","雞人罷唱曉瓏璁𤧚，鴉啼金井下疎桐。"]', '["離宮散螢天似水，竹黄池冷芙蓉死。","月綴金鋪光脈脈，涼苑虛庭空澹白。","露花飞飞风草草，翠錦斕斑满層道。","雞人罷唱晓瓏璁𤧚，鴉啼金井下疎桐。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 九月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('466d4a0b-4f78-42b8-bb58-f82dfd417011', '河南府試十二月樂詞 十月', '河南府試十二月乐词 十月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["玉壺銀箭稍難傾，釭花夜笑凝幽明。","碎霜斜舞上羅幕，燭龍兩行照飛閣。","珠帷怨臥不成眠，金鳳刺衣著體寒，長眉對月鬬彎環。"]', '["玉壺銀箭稍难傾，釭花夜笑凝幽明。","碎霜斜舞上羅幕，燭龙兩行照飞閣。","珠帷怨臥不成眠，金鳳刺衣著體寒，长眉对月鬬彎环。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 十月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f36afa21-659d-4c53-951f-95b112fb00d9', '河南府試十二月樂詞 十一月', '河南府試十二月乐词 十一月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["宮城團迴凜嚴光，白天碎碎墮瓊芳。","撾鍾高飲千日酒，却天凝寒作君壽。"]', '["宮城團迴凜嚴光，白天碎碎墮瓊芳。","撾鍾高饮千日酒，却天凝寒作君壽。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 十一月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e261fc91-5868-45d2-af14-8c55afdecfc8', '河南府試十二月樂詞 十二月', '河南府試十二月乐词 十二月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["日脚淡光紅灑灑，薄霜不銷桂枝下。","依稀和氣排冬嚴，已就長日辭長夜。"]', '["日脚淡光紅灑灑，薄霜不銷桂枝下。","依稀和氣排冬嚴，已就长日辞长夜。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 十二月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('851219e8-5993-4d52-868a-8dfe431c0ddb', '河南府試十二月樂詞 閏月', '河南府試十二月乐词 閏月', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["帝重光，年重時。","七十二候迴環推，天官玉琯灰剩飛。","今歲何長來歲遲，王母移桃獻天子。"]', '["帝重光，年重时。","七十二候迴环推，天官玉琯灰剩飞。","今歲何长来歲遲，王母移桃獻天子。"]', '诗', 'shi', '', NULL, '河南府試十二月樂詞 閏月 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('681fe831-2fb0-4bae-bb2a-41d499309c7a', '天上謠', '天上謠', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["天河夜轉漂迴星，銀浦流雲學水聲。","玉宮桂樹花未落，仙妾採香垂珮纓。","秦妃卷簾北窗曉，窗前植桐青鳳小。","王子吹笙鵞管長，呼龍耕煙種瑤草。","粉霞紅綬藕絲裙，青洲步拾蘭苕春。","東指羲和能走馬，海塵新生石山下。"]', '["天河夜轉漂迴星，銀浦流云学水声。","玉宮桂樹花未落，仙妾採香垂珮纓。","秦妃卷簾北窗晓，窗前植桐青鳳小。","王子吹笙鵞管长，呼龙耕煙種瑤草。","粉霞紅綬藕絲裙，青洲步拾蘭苕春。","东指羲和能走马，海塵新生石山下。"]', '诗', 'shi', '', NULL, '天上謠 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41a7ff30-5f3a-44dd-bdf9-217b0772d04e', '浩歌', '浩歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["南風吹山作平地，帝遣天吳移海水。","王母桃花千遍紅，彭祖巫咸幾回死。","青毛驄馬參差錢，嬌春楊柳含細煙。","箏人勸我金屈巵，神血未凝身問誰。","不須浪飲丁都護，世上英雄本無主。","買絲繡作平原君，有酒惟澆趙州土。","漏催水咽玉蟾蜍，衛娘髮薄不勝梳。","看見秋眉換新綠，二十男兒那刺促。"]', '["南风吹山作平地，帝遣天吳移海水。","王母桃花千遍紅，彭祖巫咸幾回死。","青毛驄马參差錢，嬌春楊柳含細煙。","箏人勸我金屈巵，神血未凝身问誰。","不須浪饮丁都護，世上英雄本無主。","買絲繡作平原君，有酒惟澆趙州土。","漏催水咽玉蟾蜍，衛娘髮薄不勝梳。","看见秋眉換新綠，二十男兒那刺促。"]', '诗', 'shi', '', NULL, '浩歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58301f45-20a8-4430-9da2-73aa936311b0', '秋來', '秋来', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["桐風驚心壯士苦，衰燈絡緯啼寒素。","誰看青簡一編書，不遣花蟲粉空蠹。","思牽今夜腸應直，雨冷香魂弔書客。","秋墳鬼唱鮑家詩，恨血千年土中碧。"]', '["桐风驚心壯士苦，衰灯絡緯啼寒素。","誰看青簡一編书，不遣花蟲粉空蠹。","思牽今夜腸應直，雨冷香魂弔书客。","秋墳鬼唱鲍家诗，恨血千年土中碧。"]', '诗', 'shi', '', NULL, '秋來 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68f64cf6-fb41-4aeb-9649-612828fa994f', '帝子歌', '帝子歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["洞庭明月一千里，涼風雁啼天在水。","九節菖蒲石上死，湘神彈琴迎帝子。","山頭老桂吹古香，雌龍怨吟寒水光。","沙浦走魚白石郎，閑取真珠擲龍堂。"]', '["洞庭明月一千里，涼风雁啼天在水。","九節菖蒲石上死，湘神彈琴迎帝子。","山头老桂吹古香，雌龙怨吟寒水光。","沙浦走鱼白石郎，闲取真珠擲龙堂。"]', '诗', 'shi', '', NULL, '帝子歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20940092-30e7-45fb-b74d-866aa0f9368d', '秦王飲酒', '秦王饮酒', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["秦王騎虎遊八極，劒光照空天自碧。","羲和敲日玻璃聲，劫灰飛盡古今平。","龍頭瀉酒邀酒星，金槽琵琶夜棖棖。","洞庭雨脚來吹笙，酒酣喝月使倒行。","銀雲櫛櫛瑤殿明，宮門掌事報一更。","花樓玉鳳聲嬌獰，海綃紅文香淺清。","黃鵞跌舞千年觥，仙人燭樹蠟煙輕，清琴醉眼淚泓泓。"]', '["秦王騎虎游八極，劒光照空天自碧。","羲和敲日玻璃声，劫灰飞尽古今平。","龙头瀉酒邀酒星，金槽琵琶夜棖棖。","洞庭雨脚来吹笙，酒酣喝月使倒行。","銀云櫛櫛瑤殿明，宮门掌事報一更。","花楼玉鳳声嬌獰，海綃紅文香淺清。","黄鵞跌舞千年觥，仙人燭樹蠟煙轻，清琴醉眼泪泓泓。"]', '诗', 'shi', '', NULL, '秦王飲酒 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ce0824b-965f-482e-bf01-ce11bb71519a', '洛姝真珠', '洛姝真珠', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["真珠小娘下清廓，洛苑香風飛綽綽。","寒鬢斜釵玉燕光，高樓唱月敲懸璫。","蘭風桂露灑幽翠，紅弦褭雲咽深思。","花袍白馬不歸來，濃蛾疊柳香脣醉。","金鵞屏風蜀山夢，鸞裾鳳帶行煙重。","八驄籠晃臉差移，日絲繁散曛羅洞。","市南曲陌無秋涼，楚腰衛鬢四時芳。","玉喉窱窱排空光，牽雲曳雪留陸郎。"]', '["真珠小娘下清廓，洛苑香风飞綽綽。","寒鬢斜釵玉燕光，高楼唱月敲懸璫。","蘭风桂露灑幽翠，紅弦褭云咽深思。","花袍白马不归来，濃蛾叠柳香脣醉。","金鵞屏风蜀山梦，鸾裾鳳带行煙重。","八驄籠晃臉差移，日絲繁散曛羅洞。","市南曲陌無秋涼，楚腰衛鬢四时芳。","玉喉窱窱排空光，牽云曳雪留陸郎。"]', '诗', 'shi', '', NULL, '洛姝真珠 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd22cdb-d78e-4bd5-af73-b08be1974bbe', '李夫人歌', '李夫人歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["紫皇宮殿重重開，夫人飛入瓊瑤臺。","綠香繡帳何時歇，青雲無光宮水咽。","翩聯桂花墜秋月，孤鸞驚啼商絲發。","紅壁闌珊懸珮璫，歌臺小妓遙相望。","玉蟾滴水雞人唱，露華蘭葉參差光。"]', '["紫皇宮殿重重开，夫人飞入瓊瑤台。","綠香繡帳何时歇，青云無光宮水咽。","翩聯桂花墜秋月，孤鸾驚啼商絲發。","紅壁闌珊懸珮璫，歌台小妓遙相望。","玉蟾滴水雞人唱，露华蘭葉參差光。"]', '诗', 'shi', '', NULL, '李夫人歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b8850ed-6675-484b-90da-32b3125eff83', '走馬引', '走马引', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["我有辭鄉劒，玉鋒堪截雲。","襄陽走馬客，意氣自生春。","朝嫌劒花淨，暮嫌劒光冷。","能持劒向人，不解持照身。"]', '["我有辞乡劒，玉鋒堪截云。","襄陽走马客，意氣自生春。","朝嫌劒花淨，暮嫌劒光冷。","能持劒向人，不解持照身。"]', '诗', 'shi', '', NULL, '走馬引 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a61b7143-b9e1-4f90-8377-a0b43ba22469', '湘妃', '湘妃', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["筠竹千年老不死，長伴秦娥蓋湘水。","蠻娘吟弄滿寒空，九山靜綠淚花紅。","離鸞別鳳煙梧中，巫雲蜀雨遙相通。","幽愁秋氣上青楓，涼夜波間吟古龍。"]', '["筠竹千年老不死，长伴秦娥蓋湘水。","蠻娘吟弄满寒空，九山静綠泪花紅。","離鸾別鳳煙梧中，巫云蜀雨遙相通。","幽愁秋氣上青楓，涼夜波间吟古龙。"]', '诗', 'shi', '', NULL, '湘妃 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6766c804-9532-42e3-b85d-d0d4d8bccecf', '南園十三首 一', '南园十三首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["花枝草蔓眼中開，小白長紅越女腮。","可憐日暮嫣香落，嫁與春風不用媒。"]', '["花枝草蔓眼中开，小白长紅越女腮。","可怜日暮嫣香落，嫁與春风不用媒。"]', '诗', 'shi', '', NULL, '南園十三首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7be70b4-9936-4c6b-85fc-0424a0585aaa', '南園十三首 二', '南园十三首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["宮北田塍曉氣酣，黃桑飲露窣宮簾。","長腰健婦偷攀折，將餧吳王八蠒蠶。"]', '["宮北田塍晓氣酣，黄桑饮露窣宮簾。","长腰健婦偷攀折，將餧吳王八蠒蠶。"]', '诗', 'shi', '', NULL, '南園十三首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21e0b774-e999-4b7a-9e1d-25160d5398c8', '南園十三首 三', '南园十三首 三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["竹裏繰絲挑網車，青蟬獨噪日光斜。","桃膠迎夏香琥珀，自課越傭能種瓜。"]', '["竹裏繰絲挑網车，青蟬独噪日光斜。","桃膠迎夏香琥珀，自課越傭能種瓜。"]', '诗', 'shi', '', NULL, '南園十三首 三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daa7ff23-495a-4b06-ac17-e74485a5a79a', '南園十三首 四', '南园十三首 四', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["三十未有二十餘，白日長飢小甲蔬。","橋頭長老相哀念，因遺戎韜一卷書。"]', '["三十未有二十餘，白日长飢小甲蔬。","橋头长老相哀念，因遺戎韜一卷书。"]', '诗', 'shi', '', NULL, '南園十三首 四 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b810b1ca-557d-4589-bebb-766e3bec858d', '南園十三首 五', '南园十三首 五', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["男兒何不帶吳鉤，收取關山五十州。","請君暫上凌煙閣，若箇書生萬戶侯。"]', '["男兒何不带吳鉤，收取关山五十州。","請君暫上凌煙閣，若箇书生万戶侯。"]', '诗', 'shi', '', NULL, '南園十三首 五 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22f75e20-7e62-4c0e-93ca-f71ebba61fa6', '南園十三首 六', '南园十三首 六', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["尋章摘句老雕蟲，曉月當簾挂玉弓。","不見年年遼海上，文章何處哭秋風。"]', '["尋章摘句老雕蟲，晓月當簾挂玉弓。","不见年年遼海上，文章何处哭秋风。"]', '诗', 'shi', '', NULL, '南園十三首 六 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62b591eb-db79-4031-a251-393685fe82ff', '南園十三首 七', '南园十三首 七', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長卿牢落悲空舍，曼倩詼諧取自容。","見買若耶溪水劒，明朝歸去事猨公。"]', '["长卿牢落悲空舍，曼倩詼諧取自容。","见買若耶溪水劒，明朝归去事猨公。"]', '诗', 'shi', '', NULL, '南園十三首 七 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60fb1559-a65f-4dab-97ed-ac5e568e5c77', '南園十三首 八', '南园十三首 八', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["春水初生乳燕飛，黃蜂小尾撲花歸。","窗含遠色通書幌，魚擁香鉤近石磯。"]', '["春水初生乳燕飞，黄蜂小尾撲花归。","窗含远色通书幌，鱼擁香鉤近石磯。"]', '诗', 'shi', '', NULL, '南園十三首 八 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d1ec4bb4-6f3b-4f1b-accf-a861c00c088d', '南園十三首 九', '南园十三首 九', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["泉沙耎臥鴛鴦暖，曲岸迴篙舴艋遲。","瀉酒木欄椒葉蓋，病容扶起種菱絲。"]', '["泉沙耎臥鴛鴦暖，曲岸迴篙舴艋遲。","瀉酒木欄椒葉蓋，病容扶起種菱絲。"]', '诗', 'shi', '', NULL, '南園十三首 九 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19bb5bca-4b8e-48f2-a343-664238cc8f92', '南園十三首 十', '南园十三首 十', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["邊讓今朝憶蔡邕，無心裁曲臥春風。","舍南有竹堪書字，老去溪頭作釣翁。"]', '["邊讓今朝憶蔡邕，無心裁曲臥春风。","舍南有竹堪书字，老去溪头作釣翁。"]', '诗', 'shi', '', NULL, '南園十三首 十 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32f9d2a4-562b-41b6-8908-54ddeae48f90', '南園十三首 十一', '南园十三首 十一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長巒谷口倚嵇家，白晝千峰老翠華。","自履藤鞋收石蜜，手牽苔絮長蒓花。"]', '["长巒谷口倚嵇家，白晝千峰老翠华。","自履藤鞋收石蜜，手牽苔絮长蒓花。"]', '诗', 'shi', '', NULL, '南園十三首 十一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea8a85f0-c040-4d22-a1a5-ac73d071c92d', '南園十三首 十二', '南园十三首 十二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["松溪黑水新龍卵，桂洞生硝舊馬牙。","誰遣虞卿裁道帔，輕綃一匹染朝霞。"]', '["松溪黑水新龙卵，桂洞生硝旧马牙。","誰遣虞卿裁道帔，轻綃一匹染朝霞。"]', '诗', 'shi', '', NULL, '南園十三首 十二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3a57a70-7001-44b7-9027-ba29a150c8bb', '南園十三首 十三', '南园十三首 十三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["小樹開朝逕，長茸溼夜煙。","柳花驚雪浦，麥雨漲溪田。","古剎疎鐘度，遙嵐破月懸。","沙頭敲石火，燒竹照漁船。"]', '["小樹开朝逕，长茸溼夜煙。","柳花驚雪浦，麦雨漲溪田。","古剎疎鐘度，遙嵐破月懸。","沙头敲石火，燒竹照漁船。"]', '诗', 'shi', '', NULL, '南園十三首 十三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56f01a7d-2d53-4191-b6e4-7cc94fa76515', '金銅仙人辭漢歌', '金銅仙人辞漢歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["茂陵劉郎秋風客，夜聞馬嘶曉無跡。","畫欄桂樹懸秋香，三十六宮土花碧。","魏官牽車指千里，東關酸風射眸子。","空將漢月出宮門，憶君清淚如鉛水。","衰蘭送客咸陽道，天若有情天亦老。","攜盤獨出月荒涼，渭城已遠波聲小。"]', '["茂陵劉郎秋风客，夜闻马嘶晓無跡。","畫欄桂樹懸秋香，三十六宮土花碧。","魏官牽车指千里，东关酸风射眸子。","空將漢月出宮门，憶君清泪如鉛水。","衰蘭送客咸陽道，天若有情天亦老。","携盤独出月荒涼，渭城已远波声小。"]', '诗', 'shi', '', NULL, '金銅仙人辭漢歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82db064c-c110-44e1-a74f-c0bc0caa831a', '古悠悠行', '古悠悠行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["白景歸西山，碧華上迢迢。","今古何處盡，千歲隨風飄。","海沙變成石，魚沫吹秦橋。","空光遠流浪，銅柱從年消。"]', '["白景归西山，碧华上迢迢。","今古何处尽，千歲隨风飄。","海沙变成石，鱼沫吹秦橋。","空光远流浪，銅柱從年消。"]', '诗', 'shi', '', NULL, '古悠悠行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05af0540-9332-454f-ad42-e94a93a45df4', '黃頭郎', '黄头郎', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["黃頭郎，撈攏去不歸。","南浦芙蓉影，愁紅獨自垂。","水弄湘娥珮，竹啼山露月。","玉瑟調青門，石雲溼黃葛。","沙上蘼蕪花，秋風已先發。","好持掃羅薦，香出鴛鴦熱。"]', '["黄头郎，撈攏去不归。","南浦芙蓉影，愁紅独自垂。","水弄湘娥珮，竹啼山露月。","玉瑟調青门，石云溼黄葛。","沙上蘼蕪花，秋风已先發。","好持掃羅薦，香出鴛鴦熱。"]', '诗', 'shi', '', NULL, '黃頭郎 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad494dc-1f51-4918-bb12-f85f371d5cc6', '馬詩二十三首 一', '马诗二十三首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["龍脊貼連錢，銀蹄白踏煙。","無人織錦韂，誰爲鑄金鞭。"]', '["龙脊貼連錢，銀蹄白踏煙。","無人织錦韂，誰爲鑄金鞭。"]', '诗', 'shi', '', NULL, '馬詩二十三首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad120d2f-ce6b-47ef-915e-737b8cb5ccca', '馬詩二十三首 二', '马诗二十三首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["臘月草根甜，天街雪似鹽。","未知口硬軟，先擬蒺藜銜。"]', '["臘月草根甜，天街雪似鹽。","未知口硬軟，先擬蒺藜銜。"]', '诗', 'shi', '', NULL, '馬詩二十三首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f8c7c7f-a625-4201-a873-a4d653d64a27', '馬詩二十三首 三', '马诗二十三首 三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["忽憶周天子，驅車上玉山。","鳴騶辭鳳苑，赤驥最承恩。"]', '["忽憶周天子，驱车上玉山。","鳴騶辞鳳苑，赤驥最承恩。"]', '诗', 'shi', '', NULL, '馬詩二十三首 三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0bca75a-a429-449f-abf5-9e1e0c8cc483', '馬詩二十三首 四', '马诗二十三首 四', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["此馬非凡馬，房星本是星。","向前敲瘦骨，猶自帶銅聲。"]', '["此马非凡马，房星本是星。","向前敲瘦骨，猶自带銅声。"]', '诗', 'shi', '', NULL, '馬詩二十三首 四 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1ccc932-7dd7-429c-9868-948a1f91e4f1', '馬詩二十三首 五', '马诗二十三首 五', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["大漠山如雪，燕山月似鉤。","何當金絡腦，快走踏清秋。"]', '["大漠山如雪，燕山月似鉤。","何當金絡腦，快走踏清秋。"]', '诗', 'shi', '', NULL, '馬詩二十三首 五 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e8e4fea-14d1-41d0-a777-ddaf67da6146', '馬詩二十三首 六', '马诗二十三首 六', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["飢臥骨查牙，粗毛刺破花。","鬣焦朱色落，髮斷鋸長麻。"]', '["飢臥骨查牙，粗毛刺破花。","鬣焦朱色落，髮斷鋸长麻。"]', '诗', 'shi', '', NULL, '馬詩二十三首 六 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38b65cdf-a0e4-4590-ada7-2b2538293225', '馬詩二十三首 七', '马诗二十三首 七', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["西母酒將闌，東王飯已乾。","君王若燕去，誰爲拽車轅。"]', '["西母酒將闌，东王飯已乾。","君王若燕去，誰爲拽车轅。"]', '诗', 'shi', '', NULL, '馬詩二十三首 七 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2516db4e-350d-4d95-83b9-ed69ee9687a3', '馬詩二十三首 八', '马诗二十三首 八', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["赤兔無人用，當須呂布騎。","吾聞果下馬，羇策任蠻兒。"]', '["赤兔無人用，當須呂布騎。","吾闻果下马，羇策任蠻兒。"]', '诗', 'shi', '', NULL, '馬詩二十三首 八 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f6a1de-496c-41bf-9454-f06b9e31cd7c', '馬詩二十三首 九', '马诗二十三首 九', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["飂叔去怱怱，如今不豢龍。","夜來霜壓棧，駿骨折西風。"]', '["飂叔去怱怱，如今不豢龙。","夜来霜壓棧，駿骨折西风。"]', '诗', 'shi', '', NULL, '馬詩二十三首 九 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ced668-1a31-4bfb-a688-4a21b6d20301', '馬詩二十三首 十', '马诗二十三首 十', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["摧榜渡烏江，神騅泣向風。"]', '["摧榜渡烏江，神騅泣向风。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68830ff6-060c-4f73-95fc-202d6e1ce252', '馬詩二十三首 十一', '马诗二十三首 十一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["內馬賜宮人，銀韉刺騏驎。","午時鹽坂上，蹭蹬溘風塵。"]', '["內马賜宮人，銀韉刺騏驎。","午时鹽坂上，蹭蹬溘风塵。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3daa457-1d07-4caa-bf36-8b3c379a7333', '馬詩二十三首 十二', '马诗二十三首 十二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["批竹初攢耳，桃花未上身。","他時須攪陣，牽去借將軍。"]', '["批竹初攢耳，桃花未上身。","他时須攪陣，牽去借將軍。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ecb39f4-671a-4916-ac2d-095e3ad44e8f', '馬詩二十三首 十三', '马诗二十三首 十三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["寶玦誰家子，長聞俠骨香。","堆金買駿骨，將送楚襄王。"]', '["寶玦誰家子，长闻俠骨香。","堆金買駿骨，將送楚襄王。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd42be7e-4ad9-4998-87a3-48dbbd9e6be8', '馬詩二十三首 十四', '马诗二十三首 十四', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["香襆赭羅新，盤龍蹙鐙鱗。","迴看南陌上，誰道不逢春。"]', '["香襆赭羅新，盤龙蹙鐙鱗。","迴看南陌上，誰道不逢春。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十四 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('321a9b5e-291a-47ae-bce9-c8d80d8018fa', '馬詩二十三首 十五', '马诗二十三首 十五', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["不從桓公獵，何能伏虎威。","一朝溝隴出，看取拂雲飛。"]', '["不從桓公獵，何能伏虎威。","一朝溝隴出，看取拂云飞。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十五 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9544e82e-2666-4419-aed1-8b941648f6e6', '馬詩二十三首 十六', '马诗二十三首 十六', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["唐劍斬隋公，拳毛屬太宗。","莫嫌金甲重，且去捉𩘶風。"]', '["唐劍斬隋公，拳毛屬太宗。","莫嫌金甲重，且去捉𩘶风。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十六 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1847269f-3877-4dd5-826e-8c912f111efe', '馬詩二十三首 十七', '马诗二十三首 十七', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["白鐵剉青禾，碪間落細莎。","世人憐小頸，金埒畏長牙。"]', '["白鐵剉青禾，碪间落細莎。","世人怜小頸，金埒畏长牙。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十七 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb5a4269-c06a-4c8a-bb03-a65a24b5baeb', '馬詩二十三首 十八', '马诗二十三首 十八', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["伯樂向前看，旋毛在腹間。","祗今掊白草，何日驀青山。"]', '["伯乐向前看，旋毛在腹间。","祗今掊白草，何日驀青山。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十八 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d28d4e75-7433-4044-a078-82547323d997', '馬詩二十三首 十九', '马诗二十三首 十九', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["蕭寺馱經馬，元從竺國來。","空知有善相，不解走章臺。"]', '["蕭寺馱經马，元從竺国来。","空知有善相，不解走章台。"]', '诗', 'shi', '', NULL, '馬詩二十三首 十九 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7062712-dbd0-414b-a528-36496930d3e1', '馬詩二十三首 二十', '马诗二十三首 二十', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["重圍如燕尾，寶劍似魚腸。","欲求千里脚，先采眼中光。"]', '["重圍如燕尾，寶劍似鱼腸。","欲求千里脚，先采眼中光。"]', '诗', 'shi', '', NULL, '馬詩二十三首 二十 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5becd0c-e3f6-432a-ae2b-a17683098860', '馬詩二十三首 二十一', '马诗二十三首 二十一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["暫繫騰黃馬，仙人上綵樓。","須鞭玉勒吏，何事謫高州。"]', '["暫繫腾黄马，仙人上綵楼。","須鞭玉勒吏，何事謫高州。"]', '诗', 'shi', '', NULL, '馬詩二十三首 二十一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e08d02a9-041f-4864-a26c-6e6f5a612d5a', '馬詩二十三首 二十二', '马诗二十三首 二十二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["汗血到王家，隨鸞撼玉珂。","少君騎海上，人見是青騾。"]', '["汗血到王家，隨鸾撼玉珂。","少君騎海上，人见是青騾。"]', '诗', 'shi', '', NULL, '馬詩二十三首 二十二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fe1085b-c5a4-4dd5-a9e0-286066b0d923', '馬詩二十三首 二十三', '马诗二十三首 二十三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["武帝愛神仙，燒金得紫煙。","廐中皆肉馬，不解上青天。"]', '["武帝愛神仙，燒金得紫煙。","廐中皆肉马，不解上青天。"]', '诗', 'shi', '', NULL, '馬詩二十三首 二十三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7344a621-9c5b-435b-ab03-5bce85d24ce2', '申胡子觱篥歌', '申胡子觱篥歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["顏熱感君酒，含嚼蘆中聲。","花娘篸綏妥，休睡芙蓉屏。","誰截太平管，列點排空星。","直貫開花風，天上驅雲行。","今夕歲華落，令人惜平生。","心事如波濤，中坐時時驚。","朔客騎白馬，劍弝懸蘭纓。","俊健如生猱，肯拾蓬中螢。"]', '["顏熱感君酒，含嚼蘆中声。","花娘篸綏妥，休睡芙蓉屏。","誰截太平管，列点排空星。","直貫开花风，天上驱云行。","今夕歲华落，令人惜平生。","心事如波濤，中坐时时驚。","朔客騎白马，劍弝懸蘭纓。","俊健如生猱，肯拾蓬中螢。"]', '诗', 'shi', '', NULL, '申胡子觱篥歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8ca253f-7981-4bcc-a6dc-b7444401d39f', '老夫採玉歌', '老夫採玉歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["採玉採玉須水碧，琢作步搖徒好色。","老夫飢寒龍爲愁，藍溪水氣無清白。","夜雨岡頭食蓁子，杜鵑口血老夫淚。","藍溪之水厭生人，身死千年恨溪水。","斜山柏風雨如嘯，泉脚挂繩青褭褭。","村寒白屋念嬌嬰，古臺石磴懸腸草。"]', '["採玉採玉須水碧，琢作步搖徒好色。","老夫飢寒龙爲愁，藍溪水氣無清白。","夜雨岡头食蓁子，杜鵑口血老夫泪。","藍溪之水厭生人，身死千年恨溪水。","斜山柏风雨如嘯，泉脚挂繩青褭褭。","村寒白屋念嬌嬰，古台石磴懸腸草。"]', '诗', 'shi', '', NULL, '老夫採玉歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfdbb451-5c25-4b22-9e1f-a6632ec76ded', '傷心行', '傷心行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["咽咽學楚吟，病骨傷幽素。","秋姿白髮生，木葉啼風雨。","燈青蘭膏歇，落照飛蛾舞。","古壁生凝塵，羇魂夢中語。"]', '["咽咽学楚吟，病骨傷幽素。","秋姿白髮生，木葉啼风雨。","灯青蘭膏歇，落照飞蛾舞。","古壁生凝塵，羇魂梦中語。"]', '诗', 'shi', '', NULL, '傷心行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aaa9d12-9f44-4cb4-8aac-a78a92553844', '湖中曲', '湖中曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長眉越沙採蘭若，桂葉水葓春漠漠。","橫船醉眠白晝閑，渡口梅風歌扇薄。","燕釵玉股照青渠，越王嬌郎小字書。","蜀紙封巾報雲鬢，晚漏壺中水淋盡。"]', '["长眉越沙採蘭若，桂葉水葓春漠漠。","橫船醉眠白晝闲，渡口梅风歌扇薄。","燕釵玉股照青渠，越王嬌郎小字书。","蜀紙封巾報云鬢，晚漏壺中水淋尽。"]', '诗', 'shi', '', NULL, '湖中曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da48aa4d-256d-4e2f-a2aa-983f13a9c601', '黃家洞', '黄家洞', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["雀步蹙沙聲促促，四尺角弓青石鏃。","黑幡三點銅鼓鳴，高作猨啼搖箭箙。","綵巾纏踍幅半斜，溪頭簇隊暎葛花。","山潭晚霧吟白鼉，竹蛇飛蠹射金沙。","閑驅竹馬緩歸家，官軍自殺容州槎。"]', '["雀步蹙沙声促促，四尺角弓青石鏃。","黑幡三点銅鼓鳴，高作猨啼搖箭箙。","綵巾纏踍幅半斜，溪头簇隊暎葛花。","山潭晚霧吟白鼉，竹蛇飞蠹射金沙。","闲驱竹马緩归家，官軍自殺容州槎。"]', '诗', 'shi', '', NULL, '黃家洞 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1afe006-f5d7-46a5-8c31-d77b80134155', '屏風曲', '屏风曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["蝶棲石竹銀交關，水凝綠鴨瑠璃錢。","團迴六曲抱膏蘭，將鬟鏡上擲金蟬。","沈香火暖茱萸煙，酒觥綰帶新承懽。","月風吹露屏外寒，城上烏啼楚女眠。"]', '["蝶棲石竹銀交关，水凝綠鴨瑠璃錢。","團迴六曲抱膏蘭，將鬟镜上擲金蟬。","沈香火暖茱萸煙，酒觥綰带新承懽。","月风吹露屏外寒，城上烏啼楚女眠。"]', '诗', 'shi', '', NULL, '屏風曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d44c69a-e64a-44d4-9576-9ea3bf805533', '南山田中行', '南山田中行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["秋野明，秋風白，塘水漻漻蟲嘖嘖。","雲根苔蘚山上石，冷紅泣露嬌啼色。","荒畦九月稻叉牙，蟄螢低飛隴逕斜。","石脈水流泉滴沙，鬼燈如漆點松花。"]', '["秋野明，秋风白，塘水漻漻蟲嘖嘖。","云根苔蘚山上石，冷紅泣露嬌啼色。","荒畦九月稻叉牙，蟄螢低飞隴逕斜。","石脈水流泉滴沙，鬼灯如漆点松花。"]', '诗', 'shi', '', NULL, '南山田中行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e5b7ea7-dbf3-4be0-820b-afa48ba1d10d', '貴主征行樂', '貴主征行乐', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["奚騎黃銅連鎖甲，羅旗香幹金畫葉。","中軍留醉河陽城，嬌嘶紫燕踏花行。","春營騎將如紅玉，走馬捎鞭上空綠。","女垣素月角吚吚，牙帳未開分錦衣。"]', '["奚騎黄銅連鎖甲，羅旗香幹金畫葉。","中軍留醉河陽城，嬌嘶紫燕踏花行。","春營騎將如紅玉，走马捎鞭上空綠。","女垣素月角吚吚，牙帳未开分錦衣。"]', '诗', 'shi', '', NULL, '貴主征行樂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('317e061a-3b17-440f-8152-3fed3c0521e2', '酒罷張大徹索贈詩', '酒罷張大徹索贈诗', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長鬣張郎三十八，天遣裁詩花作骨。","往還誰是龍頭人，公主遣秉魚須笏。","太行青草上白衫，匣中章奏密如蠶。","金門石閣知卿有，豸角雞香早晚含。","隴西長吉摧頹客，酒闌感覺中區窄。","葛衣斷碎趙城秋，吟詩一夜東方白。"]', '["长鬣張郎三十八，天遣裁诗花作骨。","往還誰是龙头人，公主遣秉鱼須笏。","太行青草上白衫，匣中章奏密如蠶。","金门石閣知卿有，豸角雞香早晚含。","隴西长吉摧頹客，酒闌感覺中區窄。","葛衣斷碎趙城秋，吟诗一夜东方白。"]', '诗', 'shi', '', NULL, '酒罷張大徹索贈詩 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d48cdb59-2492-497b-a8c3-11a3930448bb', '羅浮山父與葛篇', '羅浮山父與葛篇', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["依依宜織江雨空，雨中六月蘭臺風。","博羅老仙時出洞，千歲石牀啼鬼工。","蛇毒濃凝洞堂溼，江魚不食銜沙立。","欲剪箱中一尺天，吳娥莫道吳刀澀。"]', '["依依宜织江雨空，雨中六月蘭台风。","博羅老仙时出洞，千歲石牀啼鬼工。","蛇毒濃凝洞堂溼，江鱼不食銜沙立。","欲剪箱中一尺天，吳娥莫道吳刀澀。"]', '诗', 'shi', '', NULL, '羅浮山父與葛篇 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acf90853-d3e3-4d49-8495-5052d5f550ba', '仁和里雜敘皇甫湜', '仁和里杂敘皇甫湜', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["大人乞馬癯乃寒，宗人貸宅荒厥垣。","橫庭鼠徑空土澀，出籬大棗垂朱殘。","安定美人截黃綬，脫落纓裾瞑朝酒。","還家白筆未上頭，使我清聲落人後。","枉辱稱知犯君眼，排引纔陞強絙斷。","洛風送馬入長關，闔扇未開逢猰犬。","那知堅都相草草，客枕幽單看春老。","歸來骨薄面無膏，疫氣衝頭鬢莖少。","欲雕小說干天官，宗孫不調爲誰憐。","明朝下元復西道，崆峒敘別長如天。"]', '["大人乞马癯乃寒，宗人貸宅荒厥垣。","橫庭鼠徑空土澀，出籬大棗垂朱殘。","安定美人截黄綬，脫落纓裾瞑朝酒。","還家白笔未上头，使我清声落人後。","枉辱稱知犯君眼，排引纔陞強絙斷。","洛风送马入长关，闔扇未开逢猰犬。","那知堅都相草草，客枕幽單看春老。","归来骨薄面無膏，疫氣衝头鬢莖少。","欲雕小说干天官，宗孫不調爲誰怜。","明朝下元复西道，崆峒敘別长如天。"]', '诗', 'shi', '', NULL, '仁和里雜敘皇甫湜 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0e70d45-6b58-4da7-a310-20eba5f99759', '宮娃歌', '宮娃歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["蠟光高懸照紗空，花房夜擣紅守宮。","象口吹香毾㲪暖，七星挂城聞漏板。","寒入罘罳殿影昏，彩鸞簾額著霜痕。","啼蛄弔月鉤欄下，屈膝銅鋪鎖阿甄。","夢入家門上沙渚，天河落處長洲路。","願君光明如太陽，放妾騎魚撇波去。"]', '["蠟光高懸照紗空，花房夜擣紅守宮。","象口吹香毾㲪暖，七星挂城闻漏板。","寒入罘罳殿影昏，彩鸾簾額著霜痕。","啼蛄弔月鉤欄下，屈膝銅鋪鎖阿甄。","梦入家门上沙渚，天河落处长洲路。","願君光明如太陽，放妾騎鱼撇波去。"]', '诗', 'shi', '', NULL, '宮娃歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b424ec07-c22f-4298-afc7-67867346083e', '堂堂', '堂堂', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["堂堂復堂堂，紅脫梅灰香。","十年粉蠹生畫梁，飢蟲不食推碎黃。","蕙花已老桃葉長，禁院懸簾隔御光。","華清源中礜石湯，裴回白鳳隨君王。"]', '["堂堂复堂堂，紅脫梅灰香。","十年粉蠹生畫梁，飢蟲不食推碎黄。","蕙花已老桃葉长，禁院懸簾隔御光。","华清源中礜石湯，裴回白鳳隨君王。"]', '诗', 'shi', '', NULL, '堂堂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51fc09e9-17cd-49ff-934e-cd19b4f46522', '勉愛行二首送小季之廬山 一', '勉愛行二首送小季之廬山 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["洛郊無俎豆，弊廐慙老馬。","小雁過鑪峰，影落楚水下。","長船倚雲泊，石鏡秋涼夜。","豈解有鄉情，弄月聊嗚啞。"]', '["洛郊無俎豆，弊廐慙老马。","小雁過鑪峰，影落楚水下。","长船倚云泊，石镜秋涼夜。","豈解有乡情，弄月聊嗚啞。"]', '诗', 'shi', '', NULL, '勉愛行二首送小季之廬山 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b724197b-7e08-48dc-ae31-73b45d05f7ba', '勉愛行二首送小季之廬山 二', '勉愛行二首送小季之廬山 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["別柳當馬頭，官槐如兔目。","欲將千里別，持我易斗粟。","南雲北雲空脈斷，靈臺經絡懸春綫。","青軒樹轉月滿牀，下國飢兒夢中見。","維爾之昆二十餘，年來持鏡頗有鬚。","辭家三載今如此，索米王門一事無。","荒溝古水光如刀，庭南拱柳生蠐螬。","江干幼客真可念，郊原晚吹悲號號。"]', '["別柳當马头，官槐如兔目。","欲將千里別，持我易斗粟。","南云北云空脈斷，靈台經絡懸春綫。","青軒樹轉月满牀，下国飢兒梦中见。","維爾之昆二十餘，年来持镜頗有鬚。","辞家三載今如此，索米王门一事無。","荒溝古水光如刀，庭南拱柳生蠐螬。","江干幼客真可念，郊原晚吹悲號號。"]', '诗', 'shi', '', NULL, '勉愛行二首送小季之廬山 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a72113fb-a98f-45a8-8ba3-187f3f48f7aa', '致酒行', '致酒行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["零落棲遲一杯酒，主人奉觴客長壽。","主父西遊困不歸，家人折斷門前柳。","吾聞馬周昔作新豐客，天荒地老無人識。","空將牋上兩行書，直犯龍顏請恩澤。","我有迷魂招不得，雄雞一聲天下白。","少年心事當拏雲，誰念幽寒坐嗚呃。"]', '["零落棲遲一杯酒，主人奉觴客长壽。","主父西游困不归，家人折斷门前柳。","吾闻马周昔作新豐客，天荒地老無人識。","空將牋上兩行书，直犯龙顏請恩澤。","我有迷魂招不得，雄雞一声天下白。","少年心事當拏云，誰念幽寒坐嗚呃。"]', '诗', 'shi', '', NULL, '致酒行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('acb07724-e918-43a3-aa7e-468a38763397', '長歌續短歌', '长歌續短歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長歌破衣襟，短歌斷白髮。","秦王不可見，旦夕成內熱。","渴飲壺中酒，飢拔隴頭粟。","淒淒四月闌，千里一時綠。","夜峰何離離，明月落石底。","裴回沿石尋，照出高峰外。","不得與之遊，歌成鬢先改。"]', '["长歌破衣襟，短歌斷白髮。","秦王不可见，旦夕成內熱。","渴饮壺中酒，飢拔隴头粟。","淒淒四月闌，千里一时綠。","夜峰何離離，明月落石底。","裴回沿石尋，照出高峰外。","不得與之游，歌成鬢先改。"]', '诗', 'shi', '', NULL, '長歌續短歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16957082-263a-4df2-8c19-2089529655ec', '公莫舞歌', '公莫舞歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["方花古礎排九楹，刺豹淋血盛銀甖。","華筵鼓吹無桐竹，長刀直立割鳴箏。","橫楣麤錦生紅緯，日炙錦嫣王未醉。","腰下三看寶玦光，項莊掉箾欄前起。","材官小臣公莫舞，座上真人赤龍子。","芒碭雲端抱天迴，咸陽王氣清如水。","鐵樞鐵楗重束關，大旗五丈撞雙鐶。","漢王今日頒秦印，絕臏刳腸臣不論。"]', '["方花古礎排九楹，刺豹淋血盛銀甖。","华筵鼓吹無桐竹，长刀直立割鳴箏。","橫楣麤錦生紅緯，日炙錦嫣王未醉。","腰下三看寶玦光，項莊掉箾欄前起。","材官小臣公莫舞，座上真人赤龙子。","芒碭云端抱天迴，咸陽王氣清如水。","鐵樞鐵楗重束关，大旗五丈撞雙鐶。","漢王今日頒秦印，絕臏刳腸臣不論。"]', '诗', 'shi', '', NULL, '公莫舞歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9a139ef-ff30-4fc2-9842-d7a9b3574324', '昌谷北園新笋四首 一', '昌谷北园新笋四首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["籜落長竿削玉開，君看母笋是龍材。","更容一夜抽千尺，別却池園數寸泥。"]', '["籜落长竿削玉开，君看母笋是龙材。","更容一夜抽千尺，別却池园數寸泥。"]', '诗', 'shi', '', NULL, '昌谷北園新笋四首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07b8b26f-a5e9-4c40-b74c-eaf253688e9f', '昌谷北園新笋四首 二', '昌谷北园新笋四首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["斫取青光寫楚辭，膩香春粉黑離離。","無情有恨何人見，露壓煙啼千萬枝。"]', '["斫取青光寫楚辞，膩香春粉黑離離。","無情有恨何人见，露壓煙啼千万枝。"]', '诗', 'shi', '', NULL, '昌谷北園新笋四首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c684b750-6e49-4153-8303-905684c0f6fb', '昌谷北園新笋四首 三', '昌谷北园新笋四首 三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["家泉石眼兩三莖，曉看陰根紫脈生。","今年水曲春沙上，笛管新篁拔玉青。"]', '["家泉石眼兩三莖，晓看陰根紫脈生。","今年水曲春沙上，笛管新篁拔玉青。"]', '诗', 'shi', '', NULL, '昌谷北園新笋四首 三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a49d92-891b-44bf-9e83-d2ea5f7ed85f', '昌谷北園新笋四首 四', '昌谷北园新笋四首 四', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["古竹老梢惹碧雲，茂陵歸臥歎清貧。","風吹千畝迎雨嘯，鳥重一枝入酒尊。"]', '["古竹老梢惹碧云，茂陵归臥歎清貧。","风吹千畝迎雨嘯，鸟重一枝入酒尊。"]', '诗', 'shi', '', NULL, '昌谷北園新笋四首 四 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39fe071-dea2-470e-b2b7-b48b12d4304c', '惱公', '惱公', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["宋玉愁空斷，嬌饒粉自紅。","歌聲春草露，門掩杏花叢。","注口櫻桃小，添眉桂葉濃。","曉奩妝秀靨，夜帳減香筒。","鈿鏡飛孤鵲，江圖畫水葓。","陂陀梳碧鳳，腰褭帶金蟲。","杜若含清露，河蒲聚紫茸。","月分蛾黛破，花合靨朱融。","髮重疑盤霧，腰輕乍倚風。","密書題荳蔲，隱語笑芙蓉。","莫鎖茱萸匣，休開翡翠籠。","弄珠驚漢燕，燒蜜引胡蜂。","醉纈拋紅網，單羅挂綠蒙。","數錢教姹女，買藥問巴賨。","勻臉安斜雁，移燈想夢熊。","腸攢非束竹，胘急是張弓。","晚樹迷新蝶，殘蜺憶斷虹。","古時填渤澥，今日鑿崆峒。","繡沓褰長幔，羅裙結短封。","心搖如舞鶴，骨出似飛龍。","井檻淋清漆，門鋪綴白銅。","隈花開兔徑，向壁印狐蹤。","玳瑁釘簾薄，琉璃疊扇烘。","象牀緣素柏，瑤席卷香葱。","細管吟朝幌，芳醪落夜楓。","宜男生楚巷，梔子發金墉。","龜甲開屏澀，鵝毛滲墨濃。","黃庭留衛瓘，綠樹養韓馮。","雞唱星懸柳，鵶啼露滴桐。","黃娥初出座，寵妹始相從。","蠟淚垂蘭燼，秋蕪掃綺櫳。","吹笙翻舊引，沽酒待新豐。","短珮愁填粟，長弦怨削菘。","曲池眠乳鴨，小閣睡娃僮。","褥縫篸雙線，鉤縚辮五總。","蜀煙飛重錦，峽雨濺輕容。","拂鏡羞溫嶠，薰衣避賈充。","魚生玉藕下，人在石蓮中。","含水彎蛾翠，登樓選馬鬉。","使君居曲陌，園令住臨邛。","桂火流蘇暖，金爐細炷通。","春遲王子態，鶯囀謝娘慵。","玉漏三星曙，銅街五馬逢。","犀株防膽怯，銀液鎮心忪。","跳脫看年命，琵琶道吉凶。","王時應七夕，夫位在三宮。","無力塗雲母，多方帶藥翁。","符因青鳥送，囊用絳紗縫。","漢苑尋官柳，河橋閡禁鐘。","月明中婦覺，應笑畫堂空。"]', '["宋玉愁空斷，嬌饒粉自紅。","歌声春草露，门掩杏花叢。","注口櫻桃小，添眉桂葉濃。","晓奩妝秀靨，夜帳減香筒。","鈿镜飞孤鵲，江圖畫水葓。","陂陀梳碧鳳，腰褭带金蟲。","杜若含清露，河蒲聚紫茸。","月分蛾黛破，花合靨朱融。","髮重疑盤霧，腰轻乍倚风。","密书題荳蔲，隐語笑芙蓉。","莫鎖茱萸匣，休开翡翠籠。","弄珠驚漢燕，燒蜜引胡蜂。","醉纈拋紅網，單羅挂綠蒙。","數錢教姹女，買藥问巴賨。","勻臉安斜雁，移灯想梦熊。","腸攢非束竹，胘急是張弓。","晚樹迷新蝶，殘蜺憶斷虹。","古时填渤澥，今日鑿崆峒。","繡沓褰长幔，羅裙結短封。","心搖如舞鹤，骨出似飞龙。","井檻淋清漆，门鋪綴白銅。","隈花开兔徑，向壁印狐蹤。","玳瑁釘簾薄，琉璃叠扇烘。","象牀緣素柏，瑤席卷香葱。","細管吟朝幌，芳醪落夜楓。","宜男生楚巷，梔子發金墉。","龟甲开屏澀，鵝毛滲墨濃。","黄庭留衛瓘，綠樹養韓馮。","雞唱星懸柳，鵶啼露滴桐。","黄娥初出座，寵妹始相從。","蠟泪垂蘭燼，秋蕪掃綺櫳。","吹笙翻旧引，沽酒待新豐。","短珮愁填粟，长弦怨削菘。","曲池眠乳鴨，小閣睡娃僮。","褥縫篸雙線，鉤縚辮五總。","蜀煙飞重錦，峽雨濺轻容。","拂镜羞溫嶠，薰衣避賈充。","鱼生玉藕下，人在石蓮中。","含水彎蛾翠，登楼選马鬉。","使君居曲陌，园令住臨邛。","桂火流蘇暖，金爐細炷通。","春遲王子態，鶯囀謝娘慵。","玉漏三星曙，銅街五马逢。","犀株防膽怯，銀液鎮心忪。","跳脫看年命，琵琶道吉凶。","王时應七夕，夫位在三宮。","無力塗云母，多方带藥翁。","符因青鸟送，囊用絳紗縫。","漢苑尋官柳，河橋閡禁鐘。","月明中婦覺，應笑畫堂空。"]', '诗', 'shi', '', NULL, '惱公 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('560856e3-9708-4efd-9cfe-8a9c5c0fd096', '感諷五首 一', '感諷五首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["合浦無明珠，龍洲無木奴。","足知造化力，不給使君須。","越婦未織作，吳蠶始蠕蠕。","縣官騎馬來，獰色虬紫鬚。","懷中一方板，板上數行書。","不因使君怒，焉得詣爾廬。","越婦拜縣官，桑牙今尚小。","會待春日晏，絲車方擲掉。","越婦通言語，小姑具黃粱。","縣官踏飡去，簿吏復登堂。"]', '["合浦無明珠，龙洲無木奴。","足知造化力，不給使君須。","越婦未织作，吳蠶始蠕蠕。","縣官騎马来，獰色虬紫鬚。","懷中一方板，板上數行书。","不因使君怒，焉得詣爾廬。","越婦拜縣官，桑牙今尚小。","會待春日晏，絲车方擲掉。","越婦通言語，小姑具黄粱。","縣官踏飡去，簿吏复登堂。"]', '诗', 'shi', '', NULL, '感諷五首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4210ab0f-985d-4ca2-bc11-037cee0d3d73', '感諷五首 二', '感諷五首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["奇俊無少年，日車何躃躃。","我待紆雙綬，遺我星星髮。","都門賈生墓，青蠅久斷絕。","寒食搖揚天，憤景長肅殺。","皇漢十二帝，唯帝稱睿哲。","一夕信豎兒，文明永淪歇。"]', '["奇俊無少年，日车何躃躃。","我待紆雙綬，遺我星星髮。","都门賈生墓，青蠅久斷絕。","寒食搖揚天，憤景长肅殺。","皇漢十二帝，唯帝稱睿哲。","一夕信豎兒，文明永淪歇。"]', '诗', 'shi', '', NULL, '感諷五首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44dfe6bb-4c4b-4b21-88ef-4d5699f05068', '感諷五首 三', '感諷五首 三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["南山何其悲，鬼雨灑空草。","長安夜半秋，風前幾人老。","低迷黃昏徑，褭褭青櫟道。","月午樹無影，一山唯白曉。","漆炬迎新人，幽壙螢擾擾。"]', '["南山何其悲，鬼雨灑空草。","长安夜半秋，风前幾人老。","低迷黄昏徑，褭褭青櫟道。","月午樹無影，一山唯白晓。","漆炬迎新人，幽壙螢擾擾。"]', '诗', 'shi', '', NULL, '感諷五首 三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('272efd22-2590-4180-ab3e-245d04c0ade5', '感諷五首 四', '感諷五首 四', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["星盡四方高，萬物知天曙。","己生須己養，荷擔出門去。","君平久不反，康伯循國路。","曉思何譊譊，闤闠千人語。"]', '["星尽四方高，万物知天曙。","己生須己養，荷擔出门去。","君平久不反，康伯循国路。","晓思何譊譊，闤闠千人語。"]', '诗', 'shi', '', NULL, '感諷五首 四 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14142f5f-c6e2-44f4-ac0f-9ba1c1db12ac', '感諷五首 五', '感諷五首 五', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["石根秋水明，石畔秋草瘦。","侵衣野竹香，蟄蟄垂葉厚。","岑中月歸來，蟾光挂空秀。","桂露對仙娥，星星下雲逗。","淒涼梔子落，山璺泣清漏。","下有張仲蔚，披書案將朽。"]', '["石根秋水明，石畔秋草瘦。","侵衣野竹香，蟄蟄垂葉厚。","岑中月归来，蟾光挂空秀。","桂露对仙娥，星星下云逗。","淒涼梔子落，山璺泣清漏。","下有張仲蔚，披书案將朽。"]', '诗', 'shi', '', NULL, '感諷五首 五 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('350ee905-ef68-43ab-9fd0-8e670cd02bff', '三月過行宮', '三月過行宮', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["渠水紅繁擁御牆，風嬌小葉學娥妝。","垂簾幾度青春老，堪鎖千年白日長。"]', '["渠水紅繁擁御牆，风嬌小葉学娥妝。","垂簾幾度青春老，堪鎖千年白日长。"]', '诗', 'shi', '', NULL, '三月過行宮 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccaab9e5-fc07-4957-8394-bded82237057', '追和何謝銅雀妓', '追和何謝銅雀妓', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["佳人一壺酒，秋容滿千里。","石馬臥新煙，憂來何所似。","歌聲且潛弄，陵樹風自起。","長裾壓高臺，淚眼看花机。"]', '["佳人一壺酒，秋容满千里。","石马臥新煙，憂来何所似。","歌声且潛弄，陵樹风自起。","长裾壓高台，泪眼看花机。"]', '诗', 'shi', '', NULL, '追和何謝銅雀妓 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9374b699-91e7-4c44-a4ba-d6612fa297fb', '送秦光祿北征', '送秦光祿北征', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["北虜膠堪折，秋沙亂曉鼙。","髯胡頻犯塞，驕氣似橫霓。","灞水樓船渡，營門細柳開。","將軍馳白馬，豪彥騁雄材。","箭射欃槍落，旗懸日月低。","榆稀山易見，甲重馬頻嘶。","天遠星光沒，沙平草葉齊。","風吹雲路火，雪汙玉關泥。","屢斷呼韓頸，曾然董卓臍。","太常猶舊寵，光祿是新隮。","寶玦麒麟起，銀壺狒狖啼。","桃花連馬發，綵絮撲鞍來。","呵臂懸金斗，當脣注玉罍。","清蘇和碎蟻，紫膩卷浮杯。","虎鞹先蒙馬，魚腸且斷犀。","䟃𧽼西旅狗，蹙額北方奚。","守帳然香暮，看鷹永夜棲。","黃龍就別鏡，青塚念陽臺。","周處長橋役，侯調短弄哀。","錢塘階鳳羽，正室擘鸞釵。","內子攀琪樹，羌兒奏落梅。","今朝擎劒去，何日刺蛟迴。"]', '["北虜膠堪折，秋沙亂晓鼙。","髯胡頻犯塞，驕氣似橫霓。","灞水楼船渡，營门細柳开。","將軍驰白马，豪彥騁雄材。","箭射欃槍落，旗懸日月低。","榆稀山易见，甲重马頻嘶。","天远星光沒，沙平草葉齊。","风吹云路火，雪汙玉关泥。","屢斷呼韓頸，曾然董卓臍。","太常猶旧寵，光祿是新隮。","寶玦麒麟起，銀壺狒狖啼。","桃花連马發，綵絮撲鞍来。","呵臂懸金斗，當脣注玉罍。","清蘇和碎蟻，紫膩卷浮杯。","虎鞹先蒙马，鱼腸且斷犀。","䟃𧽼西旅狗，蹙額北方奚。","守帳然香暮，看鷹永夜棲。","黄龙就別镜，青塚念陽台。","周处长橋役，侯調短弄哀。","錢塘階鳳羽，正室擘鸾釵。","內子攀琪樹，羌兒奏落梅。","今朝擎劒去，何日刺蛟迴。"]', '诗', 'shi', '', NULL, '送秦光祿北征 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0f600ea-90fe-49ef-8c68-fbc1fa2c3be8', '酬荅二首 一', '酬荅二首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["金魚公子夾衫長，密裝腰鞓割玉方。","行處春風隨馬尾，柳花偏打內家香。"]', '["金鱼公子夾衫长，密裝腰鞓割玉方。","行处春风隨马尾，柳花偏打內家香。"]', '诗', 'shi', '', NULL, '酬荅二首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('453b1561-a1c1-4667-995f-4445c2039b97', '酬荅二首 二', '酬荅二首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["雍州二月梅池春，御水鵁鶄暖白蘋。","試問酒旗歌板地，今朝誰是抝花人。"]', '["雍州二月梅池春，御水鵁鶄暖白蘋。","試问酒旗歌板地，今朝誰是抝花人。"]', '诗', 'shi', '', NULL, '酬荅二首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0457707-c9f1-4af6-aaa9-87ad58c36e79', '畫角東城', '畫角东城', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["河轉曙蕭蕭，鴉飛睥睨高。","帆長摽越甸，壁冷挂吳刀。","淡菜生寒日，鮞魚潠白濤。","水花霑抹額，旗鼓夜迎潮。"]', '["河轉曙蕭蕭，鴉飞睥睨高。","帆长摽越甸，壁冷挂吳刀。","淡菜生寒日，鮞鱼潠白濤。","水花霑抹額，旗鼓夜迎潮。"]', '诗', 'shi', '', NULL, '畫角東城 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46c575b1-ebe5-40d7-a165-2e12af5bf58f', '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製詩嘲謝賀復繼四首 一', '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製诗嘲謝賀复繼四首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["誰知泥憶雲，望斷梨花春。","荷絲製機練，竹葉剪花裙。","月明啼阿姊，燈暗會良人。","也識君夫壻，金魚挂在身。"]', '["誰知泥憶云，望斷梨花春。","荷絲製機練，竹葉剪花裙。","月明啼阿姊，灯暗會良人。","也識君夫壻，金鱼挂在身。"]', '诗', 'shi', '', NULL, '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製詩嘲謝賀復繼四首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b6fa89-674a-4fc1-9f16-661d6bb7955b', '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製詩嘲謝賀復繼四首 二', '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製诗嘲謝賀复繼四首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["銅鏡立青鸞，燕脂拂紫綿。","腮花弄暗粉，眼尾淚侵寒。","碧玉破不復，瑤琴重撥弦。","今日非昔日，何人敢正看。"]', '["銅镜立青鸾，燕脂拂紫綿。","腮花弄暗粉，眼尾泪侵寒。","碧玉破不复，瑤琴重撥弦。","今日非昔日，何人敢正看。"]', '诗', 'shi', '', NULL, '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製詩嘲謝賀復繼四首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7ae8fa9-d895-41fc-ad7e-d4c851facc2a', '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製詩嘲謝賀復繼四首 三', '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製诗嘲謝賀复繼四首 三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["洞房思不禁，蜂子作花心。","灰暖殘香炷，髮冷青蟲簪。","夜遙燈焰短，睡熟小屏深。","好作鴛鴦夢，南城罷擣碪。"]', '["洞房思不禁，蜂子作花心。","灰暖殘香炷，髮冷青蟲簪。","夜遙灯焰短，睡熟小屏深。","好作鴛鴦梦，南城罷擣碪。"]', '诗', 'shi', '', NULL, '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製詩嘲謝賀復繼四首 三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1595f955-a610-478e-80f7-2d23500b9a6a', '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製詩嘲謝賀復繼四首 四', '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製诗嘲謝賀复繼四首 四', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["尋常輕宋玉，今日嫁文鴦。","戟幹橫龍簴，刀環倚桂窗。","邀人裁半袖，端坐據胡牀。","淚溼紅輪重，棲烏上井梁。"]', '["尋常轻宋玉，今日嫁文鴦。","戟幹橫龙簴，刀环倚桂窗。","邀人裁半袖，端坐據胡牀。","泪溼紅輪重，棲烏上井梁。"]', '诗', 'shi', '', NULL, '謝秀才有妾縞練改從於人秀才留之不得[後]生感憶座人製詩嘲謝賀復繼四首 四 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90178bb0-a9eb-49a8-9e95-90406ba8e6ee', '昌谷讀書示巴童', '昌谷读书示巴童', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["蟲響燈光薄，宵寒藥氣濃。","君憐垂翅客，辛苦尚相從。"]', '["蟲响灯光薄，宵寒藥氣濃。","君怜垂翅客，辛苦尚相從。"]', '诗', 'shi', '', NULL, '昌谷讀書示巴童 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aee0b0a-cc97-4674-9249-8c4994f3fa28', '巴童荅', '巴童荅', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["巨鼻宜山褐，龐眉入苦吟。","非君唱樂府，誰識怨秋深。"]', '["巨鼻宜山褐，龐眉入苦吟。","非君唱乐府，誰識怨秋深。"]', '诗', 'shi', '', NULL, '巴童荅 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ddc4142a-003e-4f0a-a1c8-8957a8095ec1', '代崔家送客', '代崔家送客', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["行蓋柳煙下，馬蹄白翩翩。","恐隨行處盡，何忍重揚鞭。"]', '["行蓋柳煙下，马蹄白翩翩。","恐隨行处尽，何忍重揚鞭。"]', '诗', 'shi', '', NULL, '代崔家送客 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24d03596-113c-446f-a02d-9eb6fd89e372', '出城', '出城', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["雪下桂花稀，啼烏被彈歸。","關水乘驢影，秦風帽帶垂。","入鄉試萬里，無印自堪悲。","卿卿忍相問，鏡中雙淚姿。"]', '["雪下桂花稀，啼烏被彈归。","关水乘驢影，秦风帽带垂。","入乡試万里，無印自堪悲。","卿卿忍相问，镜中雙泪姿。"]', '诗', 'shi', '', NULL, '出城 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa55e6e0-786a-459f-9e8f-5d7d95b99d74', '莫種樹', '莫種樹', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["園中莫種樹，種樹四時愁。","獨睡南牀月，今秋似去秋。"]', '["园中莫種樹，種樹四时愁。","独睡南牀月，今秋似去秋。"]', '诗', 'shi', '', NULL, '莫種樹 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0059347-876b-42c8-b167-f5087c5c7f34', '將發', '將發', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["東牀卷席罷，[濩]落將行去。","秋白遙遙空，日滿門前路。"]', '["东牀卷席罷，[濩]落將行去。","秋白遙遙空，日满门前路。"]', '诗', 'shi', '', NULL, '將發 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('704657df-b57f-4d75-bea8-5d1e84c521f6', '追賦畫江潭苑四首 一', '追賦畫江潭苑四首 一', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["吳苑曉蒼蒼，宮衣水濺黃。","小鬟紅粉薄，騎馬珮珠長。","路指臺城迥，羅薰袴褶香。","行雲霑翠輦，今日似襄王。"]', '["吳苑晓蒼蒼，宮衣水濺黄。","小鬟紅粉薄，騎马珮珠长。","路指台城迥，羅薰袴褶香。","行云霑翠輦，今日似襄王。"]', '诗', 'shi', '', NULL, '追賦畫江潭苑四首 一 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2df42a4-a3a4-4405-844c-de1bf5f05cb3', '追賦畫江潭苑四首 二', '追賦畫江潭苑四首 二', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["寶袜菊衣單，蕉花密露寒。","水光蘭澤葉，帶重剪刀錢。","角暖盤弓易，靴長上馬難。","淚痕霑寢帳，勻粉照金鞍。"]', '["寶袜菊衣單，蕉花密露寒。","水光蘭澤葉，带重剪刀錢。","角暖盤弓易，靴长上马难。","泪痕霑寢帳，勻粉照金鞍。"]', '诗', 'shi', '', NULL, '追賦畫江潭苑四首 二 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cb76c4b-f352-4602-b624-e1f1e882810f', '追賦畫江潭苑四首 三', '追賦畫江潭苑四首 三', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["剪翅小鷹斜，[縚]根玉鏇花。","鞦垂妝鈿粟，箭箙釘文牙。","●●啼深竹，鵁鶄老溼沙。","宮官燒蠟火，飛燼汚鉛華。"]', '["剪翅小鷹斜，[縚]根玉鏇花。","鞦垂妝鈿粟，箭箙釘文牙。","●●啼深竹，鵁鶄老溼沙。","宮官燒蠟火，飞燼汚鉛华。"]', '诗', 'shi', '', NULL, '追賦畫江潭苑四首 三 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18e0260b-9aeb-41f5-863d-1a536df7375c', '追賦畫江潭苑四首 四', '追賦畫江潭苑四首 四', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["十騎簇芙蓉，宮衣小隊紅。","練香熏宋鵲，尋箭踏盧龍。","旗溼金鈴重，霜乾玉鐙空。","今朝畫眉早，不待景陽鐘。"]', '["十騎簇芙蓉，宮衣小隊紅。","練香熏宋鵲，尋箭踏盧龙。","旗溼金鈴重，霜乾玉鐙空。","今朝畫眉早，不待景陽鐘。"]', '诗', 'shi', '', NULL, '追賦畫江潭苑四首 四 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2fda5c5-2793-4d74-95ab-740b1b76cdfb', '潞州張大宅病酒遇江使寄上十四兄', '潞州張大宅病酒遇江使寄上十四兄', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["秋至昭關後，當知趙國寒。","繫書隨短羽，寫恨破長箋。","病客眠清曉，疎桐墜綠鮮。","城鴉啼粉堞，軍吹壓蘆煙。","岸幘褰沙幌，枯塘臥折蓮。","木窗銀跡畫，石磴水痕錢。","旅酒侵愁肺，離歌繞懦弦。","詩封兩條淚，露折一枝蘭。","莎老沙雞泣，松乾瓦獸殘。","覺騎燕地馬，夢載楚溪船。","椒桂傾長席，鱸魴斫玳筵。","豈能忘舊路，江島滯佳年。"]', '["秋至昭关後，當知趙国寒。","繫书隨短羽，寫恨破长箋。","病客眠清晓，疎桐墜綠鲜。","城鴉啼粉堞，軍吹壓蘆煙。","岸幘褰沙幌，枯塘臥折蓮。","木窗銀跡畫，石磴水痕錢。","旅酒侵愁肺，離歌繞懦弦。","诗封兩條泪，露折一枝蘭。","莎老沙雞泣，松乾瓦獸殘。","覺騎燕地马，梦載楚溪船。","椒桂傾长席，鱸魴斫玳筵。","豈能忘旧路，江島滯佳年。"]', '诗', 'shi', '', NULL, '潞州張大宅病酒遇江使寄上十四兄 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b00fa6-b2d9-48a4-8fdb-54306ce1f937', '難忘曲', '难忘曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["夾道開洞門，弱楊低畫戟。","簾影竹華起，簫聲吹日色。","蜂語繞妝鏡，拂蛾學春碧。","亂繫丁香梢，滿欄花向夕。"]', '["夾道开洞门，弱楊低畫戟。","簾影竹华起，簫声吹日色。","蜂語繞妝镜，拂蛾学春碧。","亂繫丁香梢，满欄花向夕。"]', '诗', 'shi', '', NULL, '難忘曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c107ed9d-e05d-41bd-9e9e-4745173f8255', '賈公閭貴壻曲', '賈公閭貴壻曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["朝衣不須長，分花對袍縫。","嚶嚶白馬來，滿腦黃金重。","今朝香氣苦，珊瑚澀難枕。","且要弄風人，暖蒲沙上飲。","燕語踏簾鉤，日虹屏中碧。","潘令在河陽，無人死芳色。"]', '["朝衣不須长，分花对袍縫。","嚶嚶白马来，满腦黄金重。","今朝香氣苦，珊瑚澀难枕。","且要弄风人，暖蒲沙上饮。","燕語踏簾鉤，日虹屏中碧。","潘令在河陽，無人死芳色。"]', '诗', 'shi', '', NULL, '賈公閭貴壻曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('180e8166-9278-4e03-b344-4f37efabb16a', '夜飲朝眠曲', '夜饮朝眠曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["觴酣出座東方高，腰橫半解星勞勞。","柳苑鴉啼公主醉，薄露壓花蕙園氣。","玉轉溼絲牽曉水，熟粉生香琅玕紫。","夜飲朝眠斷無事，楚羅之幃臥皇子。"]', '["觴酣出座东方高，腰橫半解星勞勞。","柳苑鴉啼公主醉，薄露壓花蕙园氣。","玉轉溼絲牽晓水，熟粉生香琅玕紫。","夜饮朝眠斷無事，楚羅之幃臥皇子。"]', '诗', 'shi', '', NULL, '夜飲朝眠曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7192c1f4-0028-485d-b0fe-ff7b307cd1be', '王濬墓下作', '王濬墓下作', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["人間無阿童，猶唱水中龍。","白草侵煙死，秋梨遶地紅。","古書平黑石，袖劒斷青銅。","耕勢魚鱗起，墳科馬鬣封。","菊花垂溼露，棘徑臥乾蓬。","松柏愁香澀，南原幾夜風。"]', '["人间無阿童，猶唱水中龙。","白草侵煙死，秋梨遶地紅。","古书平黑石，袖劒斷青銅。","耕勢鱼鱗起，墳科马鬣封。","菊花垂溼露，棘徑臥乾蓬。","松柏愁香澀，南原幾夜风。"]', '诗', 'shi', '', NULL, '王濬墓下作 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4750ff6-aa6c-4c46-810d-cf6e80019450', '客遊', '客游', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["悲滿千里心，日暖南山石。","不謁承明廬，老作平原客。","四時別家廟，三年去鄉國。","旅歌屢彈鋏，歸問時裂帛。"]', '["悲满千里心，日暖南山石。","不謁承明廬，老作平原客。","四时別家廟，三年去乡国。","旅歌屢彈鋏，归问时裂帛。"]', '诗', 'shi', '', NULL, '客遊 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('840a294d-06b8-45a1-9751-fa3e97c881ee', '崇義里滯雨', '崇義里滯雨', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["落莫誰家子，來感長安秋。","壯年抱羈恨，夢泣生白頭。","瘦馬秣敗草，雨沫飄寒溝。","南宮古簾暗，溼景傳籤籌。","家山遠千里，雲脚天東頭。","憂眠枕劒匣，客帳夢封侯。"]', '["落莫誰家子，来感长安秋。","壯年抱羈恨，梦泣生白头。","瘦马秣敗草，雨沫飄寒溝。","南宮古簾暗，溼景傳籤籌。","家山远千里，云脚天东头。","憂眠枕劒匣，客帳梦封侯。"]', '诗', 'shi', '', NULL, '崇義里滯雨 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4b44d96-5663-4738-b0e1-e2acff426643', '馮小憐', '馮小怜', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["灣頭見小憐，請上琵琶弦。","破得春風恨，今朝直幾錢。","裙垂竹葉帶，鬢溼杏花煙。","玉冷紅絲重，齊宮妾駕鞭。"]', '["灣头见小怜，請上琵琶弦。","破得春风恨，今朝直幾錢。","裙垂竹葉带，鬢溼杏花煙。","玉冷紅絲重，齊宮妾駕鞭。"]', '诗', 'shi', '', NULL, '馮小憐 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c28456-0138-477b-bcee-9fda818734e1', '贈陳商', '贈陳商', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長安有男兒，二十心已朽。","楞伽堆案前，楚辭繫肘後。","人生有窮拙，日暮聊飲酒。","秪今道已塞，何必須白首。","淒淒陳述聖，披褐鉏俎豆。","學爲堯舜文，時人責衰偶。","柴門車轍凍，日下榆影瘦。","黃昏訪我來，苦節青陽皺。","太華五千仞，劈地抽森秀。","旁古無寸尋，一上戛牛斗。","公卿縱不憐，寧能鎖吾口。","李生師太華，大坐看白晝。","逢霜作樸𣙙，得氣爲春柳。","禮節乃相去，顦顇如芻狗。","風雪直齋壇，墨組貫銅綬。","臣妾氣態間，唯欲承箕帚。","天眼何時開，古劒庸一吼。"]', '["长安有男兒，二十心已朽。","楞伽堆案前，楚辞繫肘後。","人生有窮拙，日暮聊饮酒。","秪今道已塞，何必須白首。","淒淒陳述聖，披褐鉏俎豆。","学爲堯舜文，时人責衰偶。","柴门车轍凍，日下榆影瘦。","黄昏訪我来，苦節青陽皺。","太华五千仞，劈地抽森秀。","旁古無寸尋，一上戛牛斗。","公卿縱不怜，寧能鎖吾口。","李生師太华，大坐看白晝。","逢霜作樸𣙙，得氣爲春柳。","禮節乃相去，顦顇如芻狗。","风雪直斋壇，墨組貫銅綬。","臣妾氣態间，唯欲承箕帚。","天眼何时开，古劒庸一吼。"]', '诗', 'shi', '', NULL, '贈陳商 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('595fe873-891d-44c3-9eb6-06431778e788', '釣魚詩', '釣鱼诗', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["秋水釣紅渠，仙人待素書。","菱絲縈獨繭，蒲米蟄雙魚。","斜竹垂清沼，長綸貫碧虛。","餌懸春[蜥蜴]，鉤墜小蟾蜍。","詹子情無限，龍陽恨有餘。","爲看煙浦上，楚女淚霑裾。"]', '["秋水釣紅渠，仙人待素书。","菱絲縈独繭，蒲米蟄雙鱼。","斜竹垂清沼，长綸貫碧虛。","餌懸春[蜥蜴]，鉤墜小蟾蜍。","詹子情無限，龙陽恨有餘。","爲看煙浦上，楚女泪霑裾。"]', '诗', 'shi', '', NULL, '釣魚詩 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('795f68f3-7560-456d-98f6-34779af12e7f', '奉和二兄罷使遣馬歸延州', '奉和二兄罷使遣马归延州', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["空留三尺劒，不用一丸泥。","馬向沙場去，人歸故國來。","笛愁翻隴水，酒喜瀝春灰。","錦帶休驚雁，羅衣尚鬬雞。","還吳已渺渺，入郢莫淒淒。","自是桃李樹，何畏不成蹊。"]', '["空留三尺劒，不用一丸泥。","马向沙場去，人归故国来。","笛愁翻隴水，酒喜瀝春灰。","錦带休驚雁，羅衣尚鬬雞。","還吳已渺渺，入郢莫淒淒。","自是桃李樹，何畏不成蹊。"]', '诗', 'shi', '', NULL, '奉和二兄罷使遣馬歸延州 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a8188ef-4df5-44d7-8663-5810b6715b84', '荅贈', '荅贈', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["本是張公子，曾名萼綠華。","沈香熏小像，楊柳伴啼鴉。","露重金泥冷，盃闌玉樹斜。","琴堂沽酒客，新買後園花。"]', '["本是張公子，曾名萼綠华。","沈香熏小像，楊柳伴啼鴉。","露重金泥冷，盃闌玉樹斜。","琴堂沽酒客，新買後园花。"]', '诗', 'shi', '', NULL, '荅贈 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b99e7df-1750-406e-8bc2-2db21439bff1', '題趙生壁', '題趙生壁', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["大婦然竹根，中婦舂玉屑。","冬暖拾松枝，日煙坐蒙滅。","木蘚青桐老，石井水聲發。","曝背臥東亭，桃花滿肌骨。"]', '["大婦然竹根，中婦舂玉屑。","冬暖拾松枝，日煙坐蒙滅。","木蘚青桐老，石井水声發。","曝背臥东亭，桃花满肌骨。"]', '诗', 'shi', '', NULL, '題趙生壁 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adec055f-ac09-4e9d-8326-fc651fd2b789', '感春', '感春', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["日暖自蕭條，花悲北郭騷。","榆穿萊子眼，柳斷舞兒腰。","上幕迎神燕，飛絲送百勞。","胡琴今日恨，急語向檀槽。"]', '["日暖自蕭條，花悲北郭騷。","榆穿萊子眼，柳斷舞兒腰。","上幕迎神燕，飞絲送百勞。","胡琴今日恨，急語向檀槽。"]', '诗', 'shi', '', NULL, '感春 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea601ea7-e4e4-4df9-9028-9f427b4fcf67', '仙人', '仙人', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["彈琴石壁上，翻翻一仙人。","手持白鸞尾，夜掃南山雲。","鹿飲寒澗下，魚歸清海濱。","當時漢武帝，書報桃花春。"]', '["彈琴石壁上，翻翻一仙人。","手持白鸾尾，夜掃南山云。","鹿饮寒澗下，鱼归清海濱。","當时漢武帝，书報桃花春。"]', '诗', 'shi', '', NULL, '仙人 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e040a8b4-2c34-4a49-b071-61ea1608b511', '河陽歌', '河陽歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["染羅衣，秋藍難著色。","不是無心人，爲作臺邛客。","花燒中潬城，顏郎身已老。","惜許兩少年，抽心似春草。","今日見銀牌，今夜鳴玉讌。","牛頭高一尺，隔坐應相見。","月從東方來，酒從東方轉。","觥船飫口紅，[蜜]炬千枝爛。"]', '["染羅衣，秋藍难著色。","不是無心人，爲作台邛客。","花燒中潬城，顏郎身已老。","惜許兩少年，抽心似春草。","今日见銀牌，今夜鳴玉讌。","牛头高一尺，隔坐應相见。","月從东方来，酒從东方轉。","觥船飫口紅，[蜜]炬千枝爛。"]', '诗', 'shi', '', NULL, '河陽歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77164c1c-7e9d-4adb-ab34-40e9ee518149', '花遊曲', '花游曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["春柳南陌態，冷花寒露姿。","今朝醉城外，拂鏡濃掃眉。","煙溼愁車重，紅油覆畫衣。","舞裙香不暖，酒色上來遲。"]', '["春柳南陌態，冷花寒露姿。","今朝醉城外，拂镜濃掃眉。","煙溼愁车重，紅油覆畫衣。","舞裙香不暖，酒色上来遲。"]', '诗', 'shi', '', NULL, '花遊曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('449ee08c-9e9a-4b41-bd3b-e1278738e8a6', '春晝', '春晝', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["朱城報春更漏轉，光風催蘭吹小殿。","草細堪梳，柳長如線。","卷衣秦帝，掃粉趙燕。","日含畫幕，蜂上羅薦。","平陽花塢，河陽花縣。","越婦搘機，吳蠶作繭。","菱汀繫帶，荷塘倚扇。","江南有情，塞北無恨。"]', '["朱城報春更漏轉，光风催蘭吹小殿。","草細堪梳，柳长如線。","卷衣秦帝，掃粉趙燕。","日含畫幕，蜂上羅薦。","平陽花塢，河陽花縣。","越婦搘機，吳蠶作繭。","菱汀繫带，荷塘倚扇。","江南有情，塞北無恨。"]', '诗', 'shi', '', NULL, '春晝 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b51fcb2-7c45-4bc8-b433-cb309041d811', '安樂宮', '安乐宮', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["深井桐烏起，尚復牽情水。","未盥邵陵瓜，缾中弄長翠。","新成安樂宮，宮如鳳皇翅。","歌迴蠟板鳴，左悺提壺使。","綠蘩悲水曲，茱萸別秋子。"]', '["深井桐烏起，尚复牽情水。","未盥邵陵瓜，缾中弄长翠。","新成安乐宮，宮如鳳皇翅。","歌迴蠟板鳴，左悺提壺使。","綠蘩悲水曲，茱萸別秋子。"]', '诗', 'shi', '', NULL, '安樂宮 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97f0e647-3011-4b70-9741-2fbdbff85fdd', '胡蝶飛', '胡蝶飞', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["楊花撲帳春雲熱，龜甲屏風醉眼纈。","東家胡蝶西家飛，白騎少年今日歸。"]', '["楊花撲帳春云熱，龟甲屏风醉眼纈。","东家胡蝶西家飞，白騎少年今日归。"]', '诗', 'shi', '', NULL, '胡蝶飛 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0a06901-b758-4f7c-858a-31cd2039db1f', '梁公子', '梁公子', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["風彩出蕭家，本是菖蒲花。","南塘連子熟，洗馬走江沙。","御牋銀沫冷，長簟鳳窠斜。","種柳營中暗，題書賜館娃。"]', '["风彩出蕭家，本是菖蒲花。","南塘連子熟，洗马走江沙。","御牋銀沫冷，长簟鳳窠斜。","種柳營中暗，題书賜館娃。"]', '诗', 'shi', '', NULL, '梁公子 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18063111-e1b2-4859-8a15-9b72efc39279', '牡丹種曲', '牡丹種曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["蓮枝未長秦蘅老，走馬馱金斸春草。","水灌香泥却月盆，一夜綠房迎白曉。","美人醉語園中煙，晚華已散蝶又闌。","梁王老去羅衣在，拂袖風吹蜀國弦。","歸霞帔拖蜀帳昏，嫣紅落粉罷承恩。","檀郎謝女眠何處，樓臺月明燕夜語。"]', '["蓮枝未长秦蘅老，走马馱金斸春草。","水灌香泥却月盆，一夜綠房迎白晓。","美人醉語园中煙，晚华已散蝶又闌。","梁王老去羅衣在，拂袖风吹蜀国弦。","归霞帔拖蜀帳昏，嫣紅落粉罷承恩。","檀郎謝女眠何处，楼台月明燕夜語。"]', '诗', 'shi', '', NULL, '牡丹種曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b791d3a-fd4f-404a-be8a-28299bcd819d', '後園鑿井歌', '後园鑿井歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["井上轆轤牀上轉，水聲繁，弦聲淺。","情若何，荀奉倩。","城頭日，長向城頭住。","一日作千年，不須流下去。"]', '["井上轆轤牀上轉，水声繁，弦声淺。","情若何，荀奉倩。","城头日，长向城头住。","一日作千年，不須流下去。"]', '诗', 'shi', '', NULL, '後園鑿井歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('368be09e-2866-4ac2-8341-95a8f728c4a0', '開愁歌', '开愁歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["秋風吹地百草乾，華容碧影生晚寒。","我當二十不得意，一心愁謝如枯蘭。","衣如飛鶉馬如狗，臨岐擊劍生銅吼。","旗亭下馬解秋衣，請貰宜陽一壺酒。","壺中喚天雲不開，白晝萬里閑淒迷。","主人勸我養心骨，莫受俗物相填𧱉。"]', '["秋风吹地百草乾，华容碧影生晚寒。","我當二十不得意，一心愁謝如枯蘭。","衣如飞鶉马如狗，臨岐擊劍生銅吼。","旗亭下马解秋衣，請貰宜陽一壺酒。","壺中喚天云不开，白晝万里闲淒迷。","主人勸我養心骨，莫受俗物相填𧱉。"]', '诗', 'shi', '', NULL, '開愁歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f41995-ba87-48ef-ba9b-aa927c567099', '秦宮詩', '秦宮诗', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["越羅衫袂迎春風，玉刻麒麟腰帶紅。","樓頭曲宴仙人語，帳底吹笙香霧濃。","人間酒暖春茫茫，花枝入簾白日長。","飛窗複道傳籌飲，十夜銅盤膩燭黃。","禿衿小袖調鸚鵡，紫繡麻䪗踏哮虎。","斫桂燒金待曉筵，白鹿青蘇夜半煮。","桐英永巷騎新馬，內屋深屏生色畫。","開門爛用水衡錢，卷起黃河向身瀉。","皇天厄運猶曾裂，秦宮一生花底活。","鸞篦奪得不還人，醉睡氍毺滿堂月。"]', '["越羅衫袂迎春风，玉刻麒麟腰带紅。","楼头曲宴仙人語，帳底吹笙香霧濃。","人间酒暖春茫茫，花枝入簾白日长。","飞窗複道傳籌饮，十夜銅盤膩燭黄。","禿衿小袖調鸚鵡，紫繡麻䪗踏哮虎。","斫桂燒金待晓筵，白鹿青蘇夜半煮。","桐英永巷騎新马，內屋深屏生色畫。","开门爛用水衡錢，卷起黄河向身瀉。","皇天厄運猶曾裂，秦宮一生花底活。","鸾篦奪得不還人，醉睡氍毺满堂月。"]', '诗', 'shi', '', NULL, '秦宮詩 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c36237e-3433-4874-ad41-a22860fa2a8a', '古鄴城童子謠效王粲刺曹操', '古鄴城童子謠效王粲刺曹操', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["鄴城中，暮塵起。","將黑丸，斫文吏。","棘爲鞭，虎爲馬。","團團走，鄴城下。","切玉劍，射日弓。","獻何人，奉相公。","扶轂來，關右兒。","香掃塗，相公歸。"]', '["鄴城中，暮塵起。","將黑丸，斫文吏。","棘爲鞭，虎爲马。","團團走，鄴城下。","切玉劍，射日弓。","獻何人，奉相公。","扶轂来，关右兒。","香掃塗，相公归。"]', '诗', 'shi', '', NULL, '古鄴城童子謠效王粲刺曹操 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dadedde0-d4fd-44e4-8805-586ed3717ef7', '楊生青花紫石硯歌', '楊生青花紫石硯歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["端州石工巧如神，踏天磨刀割紫雲。","傭刓抱水含滿脣，暗灑萇弘冷血痕。","紗帷晝暖墨花春，輕漚漂沫松麝薰。","乾膩薄重立脚勻，數寸光秋無日昏。","圓毫促點聲靜新，孔硯寬頑何足云。"]', '["端州石工巧如神，踏天磨刀割紫云。","傭刓抱水含满脣，暗灑萇弘冷血痕。","紗帷晝暖墨花春，轻漚漂沫松麝薰。","乾膩薄重立脚勻，數寸光秋無日昏。","圓毫促点声静新，孔硯寬頑何足云。"]', '诗', 'shi', '', NULL, '楊生青花紫石硯歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f19f606-b838-41ec-8e9c-c0863bb0bec6', '房中思', '房中思', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["新桂如蛾眉，秋風吹小綠。","行輪出門去，玉鑾聲斷續。","月軒下風露，曉庭自幽澀。","誰能事貞素，臥聽莎雞泣。"]', '["新桂如蛾眉，秋风吹小綠。","行輪出门去，玉鑾声斷續。","月軒下风露，晓庭自幽澀。","誰能事貞素，臥听莎雞泣。"]', '诗', 'shi', '', NULL, '房中思 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f1b8b1c-d6f4-4117-91e5-e012a5c39f8d', '石城曉', '石城晓', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["月落大隄上，女垣棲烏起。","細露溼團紅，寒香解夜醉。","女牛渡天河，柳煙滿城曲。","上客留斷纓，殘蛾鬬雙綠。","春帳依微蟬翼羅，橫茵突金隱體花。","帳前輕絮鶴毛起，欲說春心無所似。"]', '["月落大隄上，女垣棲烏起。","細露溼團紅，寒香解夜醉。","女牛渡天河，柳煙满城曲。","上客留斷纓，殘蛾鬬雙綠。","春帳依微蟬翼羅，橫茵突金隐體花。","帳前轻絮鹤毛起，欲说春心無所似。"]', '诗', 'shi', '', NULL, '石城曉 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('934bd927-617f-46d2-bed6-985abfc99921', '苦晝短', '苦晝短', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["飛光飛光，勸爾一杯酒。","吾不識青天高，黃地厚。","唯見月寒日暖，來煎人壽。","食熊則肥，食蛙則瘦。","神君何在，太一安有。","天東有若木，下置銜燭龍。","吾將斬龍足，嚼龍肉。","使之朝不得迴，夜不得伏。","自然老者不死，少者不哭。","何爲服黃金，吞白玉。","誰似任公子，雲中騎碧驢。","劉徹茂陵多滯骨，嬴政梓棺費鮑魚。"]', '["飞光飞光，勸爾一杯酒。","吾不識青天高，黄地厚。","唯见月寒日暖，来煎人壽。","食熊則肥，食蛙則瘦。","神君何在，太一安有。","天东有若木，下置銜燭龙。","吾將斬龙足，嚼龙肉。","使之朝不得迴，夜不得伏。","自然老者不死，少者不哭。","何爲服黄金，吞白玉。","誰似任公子，云中騎碧驢。","劉徹茂陵多滯骨，嬴政梓棺費鲍鱼。"]', '诗', 'shi', '', NULL, '苦晝短 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('246674af-83a0-456a-acf5-bb8aeeffba75', '章和二年中', '章和二年中', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["雲蕭索，田風拂拂，麥芒如篲黍如粟。","關中父老百領襦，關東吏人乏詬租。","健犢春耕土膏黑，菖蒲叢叢沿水脈。","殷勤爲我下田租，百錢攜償絲桐客。","遊春漫光塢花白，野林散香神降席。","拜神得壽獻天子，七星貫斷姮娥死。"]', '["云蕭索，田风拂拂，麦芒如篲黍如粟。","关中父老百領襦，关东吏人乏詬租。","健犢春耕土膏黑，菖蒲叢叢沿水脈。","殷勤爲我下田租，百錢携償絲桐客。","游春漫光塢花白，野林散香神降席。","拜神得壽獻天子，七星貫斷姮娥死。"]', '诗', 'shi', '', NULL, '章和二年中 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('118ccb2f-fd27-4e22-9c10-4e449f3f0a0a', '春歸昌谷', '春归昌谷', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["束髮方讀書，謀身苦不早。","終軍未乘傳，顏子鬢先老。","天網信崇大，矯士常慅慅。","逸目駢甘華，羈心如荼蓼。","旱雲二三月，岑岫相顛倒。","誰揭頳玉盤，東方發紅照。","春熱張鶴蓋，兔目官槐小。","思焦面如病，嘗膽腸似絞。","京國心爛漫，夜夢歸家少。","發軔東門外，天地皆浩浩。","青樹驪山頭，花風滿秦道。","宮臺光錯落，裝盡偏峰嶠。","細綠及團紅，當路雜啼笑。","香風下高廣，鞍馬正華耀。","獨乘雞棲車，自覺少風調。","心曲語形影，祗身焉足樂。","豈能脫負檐，刻鶴曾無兆。","幽幽太華側，老柏如建纛。","龍皮相排戛，翠羽更蕩掉。","驅趨委憔悴，眺覽強容貌。","花蔓閡行輈，縠煙暝深徼。","少健無所就，入門愧家老。","聽講依大樹，觀書臨曲沼。","知非出柙虎，甘作藏霧豹。","韓鳥處[矰]繳，湘鯈在籠罩。","狹行無廓落，壯士徒輕躁。"]', '["束髮方读书，謀身苦不早。","終軍未乘傳，顏子鬢先老。","天網信崇大，矯士常慅慅。","逸目駢甘华，羈心如荼蓼。","旱云二三月，岑岫相顛倒。","誰揭頳玉盤，东方發紅照。","春熱張鹤蓋，兔目官槐小。","思焦面如病，嘗膽腸似絞。","京国心爛漫，夜梦归家少。","發軔东门外，天地皆浩浩。","青樹驪山头，花风满秦道。","宮台光錯落，裝尽偏峰嶠。","細綠及團紅，當路杂啼笑。","香风下高廣，鞍马正华耀。","独乘雞棲车，自覺少风調。","心曲語形影，祗身焉足乐。","豈能脫負檐，刻鹤曾無兆。","幽幽太华側，老柏如建纛。","龙皮相排戛，翠羽更蕩掉。","驱趨委憔悴，眺覽強容貌。","花蔓閡行輈，縠煙暝深徼。","少健無所就，入门愧家老。","听講依大樹，观书臨曲沼。","知非出柙虎，甘作藏霧豹。","韓鸟处[矰]繳，湘鯈在籠罩。","狹行無廓落，壯士徒轻躁。"]', '诗', 'shi', '', NULL, '春歸昌谷 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c55c63-c2c0-4b1a-8368-93ea24fed046', '昌谷詩', '昌谷诗', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["昌谷五月稻，細青滿平水。","遙巒相壓疊，頹綠愁墮地。","光潔無秋思，涼曠吹浮媚。","竹香滿淒寂，粉節塗生翠。","草髮垂恨鬢，光露泣幽淚。","層圍爛洞曲，芳徑老紅醉。","攢蟲鎪古柳，蟬子鳴高邃。","大帶委黃葛，紫蒲交狹涘。","石錢差復藉，厚葉皆蟠膩。","汰沙好平白，立馬印青字。","晚鱗自遨遊，瘦鵠暝單跱。","嘹嘹溼蛄聲，咽源驚濺起。","紆緩玉真路，神娥蕙花裏。","苔絮縈澗礫，山實垂頳紫。","小柏儼重扇，肥松突丹髓。","鳴流走響韻，壠秋拖光穟。","鶯唱閔女歌，瀑懸楚練帔。","風露滿笑眼，駢巖雜舒墜。","亂條迸石嶺，細頸喧島毖。","日脚埽昏翳，新雲啓華閟。","謐謐厭夏光，商風道清氣。","高眠服玉容，燒桂祀天几。","霧衣夜披拂，眠壇夢真粹。","待駕棲鸞老，故宮椒壁圮。","鴻瓏數鈴響，羈臣發涼思。","陰藤束朱鍵，龍帳著魈魅。","碧錦帖花檉，香衾事殘貴。","歌塵蠹木在，舞綵長雲似。","珍壤割繡段，里俗祖風義。","鄰凶不相杵，疫病無邪祀。","鮐皮識仁惠，丱角知靦恥。","縣省司刑官，戶乏詬租吏。","竹藪添墮簡，石磯引鉤餌。","溪灣轉水帶，芭蕉傾蜀紙。","岑光晃縠襟，孤景拂繁事。","泉尊陶宰酒，月眉謝郎妓。","丁丁幽鐘遠，矯矯單飛至。","霞巘殷嵯峨，危溜聽爭次。","淡蛾流平碧，薄月眇陰悴。","涼光入澗岸，廓盡山中意。","漁童下宵網，霜禽竦煙翅。","潭鏡滑蛟涎，浮珠噞魚戲。","風桐瑤匣瑟，螢星錦城使。","柳綴長縹帶，篁掉短笛吹。","石根緣綠蘚，蘆筍抽丹漬。","漂旋弄天影，古檜拏雲臂。","愁月薇帳紅，罥雲香蔓刺。","芒麥平百井，閑乘列千肆。","刺促成紀人，好學鴟夷子。"]', '["昌谷五月稻，細青满平水。","遙巒相壓叠，頹綠愁墮地。","光潔無秋思，涼曠吹浮媚。","竹香满淒寂，粉節塗生翠。","草髮垂恨鬢，光露泣幽泪。","層圍爛洞曲，芳徑老紅醉。","攢蟲鎪古柳，蟬子鳴高邃。","大带委黄葛，紫蒲交狹涘。","石錢差复藉，厚葉皆蟠膩。","汰沙好平白，立马印青字。","晚鱗自遨游，瘦鵠暝單跱。","嘹嘹溼蛄声，咽源驚濺起。","紆緩玉真路，神娥蕙花裏。","苔絮縈澗礫，山實垂頳紫。","小柏儼重扇，肥松突丹髓。","鳴流走响韻，壠秋拖光穟。","鶯唱閔女歌，瀑懸楚練帔。","风露满笑眼，駢巖杂舒墜。","亂條迸石嶺，細頸喧島毖。","日脚埽昏翳，新云啓华閟。","謐謐厭夏光，商风道清氣。","高眠服玉容，燒桂祀天几。","霧衣夜披拂，眠壇梦真粹。","待駕棲鸾老，故宮椒壁圮。","鴻瓏數鈴响，羈臣發涼思。","陰藤束朱鍵，龙帳著魈魅。","碧錦帖花檉，香衾事殘貴。","歌塵蠹木在，舞綵长云似。","珍壤割繡段，里俗祖风義。","鄰凶不相杵，疫病無邪祀。","鮐皮識仁惠，丱角知靦恥。","縣省司刑官，戶乏詬租吏。","竹藪添墮簡，石磯引鉤餌。","溪灣轉水带，芭蕉傾蜀紙。","岑光晃縠襟，孤景拂繁事。","泉尊陶宰酒，月眉謝郎妓。","丁丁幽鐘远，矯矯單飞至。","霞巘殷嵯峨，危溜听爭次。","淡蛾流平碧，薄月眇陰悴。","涼光入澗岸，廓尽山中意。","漁童下宵網，霜禽竦煙翅。","潭镜滑蛟涎，浮珠噞鱼戲。","风桐瑤匣瑟，螢星錦城使。","柳綴长縹带，篁掉短笛吹。","石根緣綠蘚，蘆筍抽丹漬。","漂旋弄天影，古檜拏云臂。","愁月薇帳紅，罥云香蔓刺。","芒麦平百井，闲乘列千肆。","刺促成紀人，好学鴟夷子。"]', '诗', 'shi', '', NULL, '昌谷詩 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('504d52fe-70fd-4dc2-8bf3-8faff1fa5ec4', '銅駝悲', '銅駝悲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["落魄三月罷，尋花去東家。","誰作送春曲，洛岸悲銅駝。","橋南多馬客，北山饒古人。","客飲盃中酒，駝悲千萬春。","生世莫徒勞，風吹盤上燭。","厭見桃株笑，銅駝夜來哭。"]', '["落魄三月罷，尋花去东家。","誰作送春曲，洛岸悲銅駝。","橋南多马客，北山饒古人。","客饮盃中酒，駝悲千万春。","生世莫徒勞，风吹盤上燭。","厭见桃株笑，銅駝夜来哭。"]', '诗', 'shi', '', NULL, '銅駝悲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('285ac776-5a32-4366-af69-92136732c1b5', '自昌谷到洛後門', '自昌谷到洛後门', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["九月大野白，蒼芩竦秋門。","寒涼十月末，露霰濛曉昏。","澹色結晝天，心事填空雲。","道上千里風，野竹蛇涎痕。","石澗涷波聲，雞叫清寒晨。","強行到東舍，解馬投舊鄰。","東家名廖者，鄉曲傳姓辛。","杖頭非飲酒，吾請造其人。","始欲南去楚，又將西適秦。","襄王與武帝，各自留青春。","聞道蘭臺上，宋玉無歸魂。","緗縹兩行字，蟄蟲蠹秋芸。","爲探秦臺意，豈命余負薪。"]', '["九月大野白，蒼芩竦秋门。","寒涼十月末，露霰濛晓昏。","澹色結晝天，心事填空云。","道上千里风，野竹蛇涎痕。","石澗涷波声，雞叫清寒晨。","強行到东舍，解马投旧鄰。","东家名廖者，乡曲傳姓辛。","杖头非饮酒，吾請造其人。","始欲南去楚，又將西適秦。","襄王與武帝，各自留青春。","闻道蘭台上，宋玉無归魂。","緗縹兩行字，蟄蟲蠹秋芸。","爲探秦台意，豈命余負薪。"]', '诗', 'shi', '', NULL, '自昌谷到洛後門 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cde13a8-f1cf-4ac8-b723-5faaf5b0029d', '七月一日曉入太行山', '七月一日晓入太行山', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["一夕遶山秋，香露溘蒙菉。","新橋倚雲阪，候蟲嘶露樸。","洛南今已遠，越衾誰爲熟。","石氣何淒淒，老莎如短鏃。"]', '["一夕遶山秋，香露溘蒙菉。","新橋倚云阪，候蟲嘶露樸。","洛南今已远，越衾誰爲熟。","石氣何淒淒，老莎如短鏃。"]', '诗', 'shi', '', NULL, '七月一日曉入太行山 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e71353-3040-4da8-9f07-daf449d6c4a3', '秋涼詩寄正字十二兄', '秋涼诗寄正字十二兄', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["閉門感秋風，幽姿任契闊。","大野生素空，天地曠肅殺。","露光泣殘蕙，蟲響連夜發。","房寒寸輝薄，迎風絳紗折。","披書古芸馥，恨唱華容歇。","百日不相知，花光變涼節。","弟兄誰念慮，牋翰既通達。","青袍度白馬，草簡奏東闕。","夢中相聚笑，覺見半牀月。","長思劇尋環，亂憂抵覃葛。"]', '["閉门感秋风，幽姿任契闊。","大野生素空，天地曠肅殺。","露光泣殘蕙，蟲响連夜發。","房寒寸輝薄，迎风絳紗折。","披书古芸馥，恨唱华容歇。","百日不相知，花光变涼節。","弟兄誰念慮，牋翰既通達。","青袍度白马，草簡奏东闕。","梦中相聚笑，覺见半牀月。","长思劇尋环，亂憂抵覃葛。"]', '诗', 'shi', '', NULL, '秋涼詩寄正字十二兄 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de51f6f7-eb38-4119-b448-66dc337e4dfa', '艾如張', '艾如張', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["錦襜褕，繡襠襦。","強飲啄，哺爾雛。","隴東臥穟滿風雨，莫信籠媒隴西去。","齊人織網如素空，張在野田平碧中。","網絲漠漠無形影，誤爾觸之傷首紅。","艾葉綠花誰剪刻，中藏禍機不可測。"]', '["錦襜褕，繡襠襦。","強饮啄，哺爾雛。","隴东臥穟满风雨，莫信籠媒隴西去。","齊人织網如素空，張在野田平碧中。","網絲漠漠無形影，誤爾觸之傷首紅。","艾葉綠花誰剪刻，中藏禍機不可測。"]', '诗', 'shi', '', NULL, '艾如張 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8c5f866-877e-4690-b5d3-f6b55bbd27a1', '上雲樂', '上云乐', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["飛香走紅滿天春，花龍盤盤上紫雲。","三千宮女列金屋，五十弦瑟海上聞。","天江碎碎銀沙路，嬴女機中斷煙素。","斷煙素，縫衣縷，八月一日君前舞。"]', '["飞香走紅满天春，花龙盤盤上紫云。","三千宮女列金屋，五十弦瑟海上闻。","天江碎碎銀沙路，嬴女機中斷煙素。","斷煙素，縫衣縷，八月一日君前舞。"]', '诗', 'shi', '', NULL, '上雲樂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd685601-7976-4c6c-8fd0-169ae4163487', '摩多樓子', '摩多楼子', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["玉塞去金人，二萬四千里。","風吹沙作雲，一時渡遼水。","天白水如練，甲絲雙串斷。","行行莫苦辛，城月猶殘半。","曉氣朔煙上，趢趗胡馬蹄。","行人臨水別，隔隴長東西。"]', '["玉塞去金人，二万四千里。","风吹沙作云，一时渡遼水。","天白水如練，甲絲雙串斷。","行行莫苦辛，城月猶殘半。","晓氣朔煙上，趢趗胡马蹄。","行人臨水別，隔隴长东西。"]', '诗', 'shi', '', NULL, '摩多樓子 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0422e408-0484-40d0-b826-da8e2c947490', '猛虎行', '猛虎行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長戈莫舂，長弩莫抨。","乳孫哺子，教得生獰。","舉頭爲城，掉尾爲旌。","東海黃公，愁見夜行。","道逢騶虞，牛哀不平。","何用尺刀，壁上雷鳴。","泰山之下，婦人哭聲。","官家有程，吏不敢聽。"]', '["长戈莫舂，长弩莫抨。","乳孫哺子，教得生獰。","舉头爲城，掉尾爲旌。","东海黄公，愁见夜行。","道逢騶虞，牛哀不平。","何用尺刀，壁上雷鳴。","泰山之下，婦人哭声。","官家有程，吏不敢听。"]', '诗', 'shi', '', NULL, '猛虎行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d0e7182f-cc73-4de5-b3c2-d891d0034686', '日出行', '日出行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["白日下崑崙，發光如舒絲。","徒照葵藿心，不照遊子悲。","折折黃河曲，日從中央轉。","暘谷耳曾聞，若木眼不見。","奈爾鑠石，胡爲銷人，羿彎弓屬矢那不中。","足令久不得奔，詎教晨光夕昏。"]', '["白日下崑崙，發光如舒絲。","徒照葵藿心，不照游子悲。","折折黄河曲，日從中央轉。","暘谷耳曾闻，若木眼不见。","奈爾鑠石，胡爲銷人，羿彎弓屬矢那不中。","足令久不得奔，詎教晨光夕昏。"]', '诗', 'shi', '', NULL, '日出行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f6bd03f-8b60-487c-8448-570a10a581a5', '苦篁調嘯引', '苦篁調嘯引', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["請說軒轅在時事，伶倫採竹二十四。","伶倫採之自崑丘，軒轅詔遣中分作十二。","伶倫以之正音律，軒轅以之調元氣。","當時黃帝上天時，二十三管咸相隨。","唯留一管人間吹，無德不能得此管，此管沈埋虞舜祠。"]', '["請说軒轅在时事，伶倫採竹二十四。","伶倫採之自崑丘，軒轅詔遣中分作十二。","伶倫以之正音律，軒轅以之調元氣。","當时黄帝上天时，二十三管咸相隨。","唯留一管人间吹，無德不能得此管，此管沈埋虞舜祠。"]', '诗', 'shi', '', NULL, '苦篁調嘯引 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9815b2df-26e7-4efc-ab90-c4efbe1deffc', '拂舞歌辭', '拂舞歌辞', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["吳娥聲絕天，空雲閑裴回。","門外滿車馬，亦須生綠苔。","尊有烏程酒，勸君千萬壽。","全勝漢武錦樓上，曉望晴寒飲花露。","東方日不破，天光無老時。","丹成作蛇乘白霧，千年重化玉井土。","從蛇作土一千載，吳堤綠草年年在。","背有八卦稱神仙，邪鱗頑甲滑腥涎。"]', '["吳娥声絕天，空云闲裴回。","门外满车马，亦須生綠苔。","尊有烏程酒，勸君千万壽。","全勝漢武錦楼上，晓望晴寒饮花露。","东方日不破，天光無老时。","丹成作蛇乘白霧，千年重化玉井土。","從蛇作土一千載，吳堤綠草年年在。","背有八卦稱神仙，邪鱗頑甲滑腥涎。"]', '诗', 'shi', '', NULL, '拂舞歌辭 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e70d45-82d5-44a7-a20e-cbb2c762d857', '夜坐吟', '夜坐吟', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["踏踏馬蹄誰見過，眼看北斗直天河。","西風羅幕生翠波，鉛華笑妾顰青蛾。","爲君起唱長相思，簾外嚴霜皆倒飛。","明星爛爛東方陲，紅霞梢出東南涯，陸郎去矣乘班騅。"]', '["踏踏马蹄誰见過，眼看北斗直天河。","西风羅幕生翠波，鉛华笑妾顰青蛾。","爲君起唱长相思，簾外嚴霜皆倒飞。","明星爛爛东方陲，紅霞梢出东南涯，陸郎去矣乘班騅。"]', '诗', 'shi', '', NULL, '夜坐吟 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('301681cd-441c-4a5c-967e-fbf82511de3a', '箜篌引', '箜篌引', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["公乎公乎，提壺將焉如。","屈平沈湘不足慕，徐衍入海誠爲愚。","公乎公乎，牀有菅席盤有魚。","北里有賢兄，東隣有小姑。","隴畝油油黍與葫，瓦甒濁醪蟻浮浮。","黍可食，醪可飲，公乎公乎其奈居。","被髮奔流竟何如，賢兄小姑哭嗚嗚。"]', '["公乎公乎，提壺將焉如。","屈平沈湘不足慕，徐衍入海誠爲愚。","公乎公乎，牀有菅席盤有鱼。","北里有賢兄，东隣有小姑。","隴畝油油黍與葫，瓦甒濁醪蟻浮浮。","黍可食，醪可饮，公乎公乎其奈居。","被髮奔流竟何如，賢兄小姑哭嗚嗚。"]', '诗', 'shi', '', NULL, '箜篌引 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05184315-6703-4e60-b85a-57b887c2b7c0', '巫山高', '巫山高', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["碧叢叢，高插天，大江翻瀾神曳煙。","楚魂尋夢風颸然，曉風飛雨生苔錢。","瑤姬一去一千年，丁香筇竹啼老猨。","古祠近月蟾桂寒，椒花墜紅溼雲間。"]', '["碧叢叢，高插天，大江翻瀾神曳煙。","楚魂尋梦风颸然，晓风飞雨生苔錢。","瑤姬一去一千年，丁香筇竹啼老猨。","古祠近月蟾桂寒，椒花墜紅溼云间。"]', '诗', 'shi', '', NULL, '巫山高 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52abee2b-32dd-4f8d-922e-a7b6cb28c181', '平城下', '平城下', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["飢寒平城下，夜夜守明月。","別劒無玉花，海風斷鬢髮。","塞長連白空，遙見漢旗紅。","青帳吹短笛，煙霧溼晝龍。","日晚在城上，依稀望城下。","風吹枯蓬起，城中嘶瘦馬。","借問築城吏，去關幾千里。","惟愁裹屍歸，不惜倒戈死。"]', '["飢寒平城下，夜夜守明月。","別劒無玉花，海风斷鬢髮。","塞长連白空，遙见漢旗紅。","青帳吹短笛，煙霧溼晝龙。","日晚在城上，依稀望城下。","风吹枯蓬起，城中嘶瘦马。","借问築城吏，去关幾千里。","惟愁裹屍归，不惜倒戈死。"]', '诗', 'shi', '', NULL, '平城下 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c2c37c6-de2a-400a-9de6-ca2b6473e38e', '江南弄', '江南弄', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["江中綠霧起涼波，天上疊巘紅嵯峨。","水風浦雲生老竹，渚暝蒲帆如一幅。","鱸魚千頭酒百斛，酒中倒臥南山綠。","吳歈越吟未終曲，江上團團帖寒玉。"]', '["江中綠霧起涼波，天上叠巘紅嵯峨。","水风浦云生老竹，渚暝蒲帆如一幅。","鱸鱼千头酒百斛，酒中倒臥南山綠。","吳歈越吟未終曲，江上團團帖寒玉。"]', '诗', 'shi', '', NULL, '江南弄 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ec67bba-ece4-49ff-81b0-455d662a0be2', '榮華樂', '榮华乐', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["鳶肩公子二十餘，齒編貝，脣激朱。","氣如虹霓，飲如建瓴。","走馬夜歸呌嚴更，徑穿複道遊椒房。","龍裘金玦雜花光，玉堂調笑金樓子。","臺下戲學邯鄲倡，口吟舌話稱女郎。","錦祛繡面漢帝旁，得明珠十斛。","白璧一雙，新詔垂金曳紫光煌煌。","馬如飛，人如水。","九卿六官皆望履，將迴日月先反掌。","欲作江河唯畫地，峨峨虎冠上切雲。","竦劒晨趨凌紫氛，繡段千尋貽皂隸。","黃金百鎰貺家臣，十二門前張大宅。","晴春煙起連天碧，金鋪綴日雜紅光。","銅龍齧環似爭力，瑤姬凝醉臥芳席。","海素籠窗空下隔，丹穴取鳳充行庖。","貜貜如拳那足食，金蟾呀呀蘭燭香。","軍裝武妓聲琅璫，誰知花雨夜來過。","但見池臺春草長，嘈嘈弦吹匝天開。","洪厓簫聲遶天來，天長一矢貫雙虎。","雲弝絕騁聒旱雷，亂袖交竿管兒舞。","吳音綠鳥學言語，能教刻石平紫金。","解送刻毛寄新兔，三皇皇后七貴人。","五十校尉二將軍，當時飛去逐彩雲，化作今日京華春。"]', '["鳶肩公子二十餘，齒編貝，脣激朱。","氣如虹霓，饮如建瓴。","走马夜归呌嚴更，徑穿複道游椒房。","龙裘金玦杂花光，玉堂調笑金楼子。","台下戲学邯鄲倡，口吟舌話稱女郎。","錦祛繡面漢帝旁，得明珠十斛。","白璧一雙，新詔垂金曳紫光煌煌。","马如飞，人如水。","九卿六官皆望履，將迴日月先反掌。","欲作江河唯畫地，峨峨虎冠上切云。","竦劒晨趨凌紫氛，繡段千尋貽皂隸。","黄金百鎰貺家臣，十二门前張大宅。","晴春煙起連天碧，金鋪綴日杂紅光。","銅龙齧环似爭力，瑤姬凝醉臥芳席。","海素籠窗空下隔，丹穴取鳳充行庖。","貜貜如拳那足食，金蟾呀呀蘭燭香。","軍裝武妓声琅璫，誰知花雨夜来過。","但见池台春草长，嘈嘈弦吹匝天开。","洪厓簫声遶天来，天长一矢貫雙虎。","云弝絕騁聒旱雷，亂袖交竿管兒舞。","吳音綠鸟学言語，能教刻石平紫金。","解送刻毛寄新兔，三皇皇后七貴人。","五十校尉二將軍，當时飞去逐彩云，化作今日京华春。"]', '诗', 'shi', '', NULL, '榮華樂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebcafead-15e8-433f-8127-f29e78237222', '相勸酒', '相勸酒', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["羲和騁六轡，晝夕不曾閑。","彈烏崦嵫竹，抶馬蟠桃鞭。","蓐收既斷翠柳，青帝又造紅蘭。","堯舜至今萬萬歲，數子將爲傾蓋間。","青錢白璧買無端，丈夫快意方爲歡。","臛蠵臛熊何足云，會須鍾飲北海，箕踞南山。","歌淫淫，管愔愔，橫波好送雕題金。","人生得意且如此，何用強知元化心。","相勸酒，終無輟，伏願陛下鴻名終不歇。","子孫綿如石上葛，來長安，車駢駢。","中有梁冀舊宅，石崇故園。"]', '["羲和騁六轡，晝夕不曾闲。","彈烏崦嵫竹，抶马蟠桃鞭。","蓐收既斷翠柳，青帝又造紅蘭。","堯舜至今万万歲，數子將爲傾蓋间。","青錢白璧買無端，丈夫快意方爲歡。","臛蠵臛熊何足云，會須鍾饮北海，箕踞南山。","歌淫淫，管愔愔，橫波好送雕題金。","人生得意且如此，何用強知元化心。","相勸酒，終無輟，伏願陛下鴻名終不歇。","子孫綿如石上葛，来长安，车駢駢。","中有梁冀旧宅，石崇故园。"]', '诗', 'shi', '', NULL, '相勸酒 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0dbf3a4-19cd-4279-9613-4de2cc5d4734', '瑤華樂', '瑤华乐', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["穆天子，走龍媒，八轡冬瓏逐天迴。","五精掃地凝雲開，高門左右日月環。","四方錯鏤稜層殷，舞霞垂尾長盤珊。","江澄海淨神母顏，施紅點翠照虞泉。","曳雲拖玉下崑山，列斾如松，張蓋如輪。","金風殿秋，清明發春。","八鑾十乘，矗如雲屯。","瓊鍾瑤席甘露文，玄霜絳雪何足云，薰梅染柳將贈君。","鉛華之水洗君骨，與君相對作真質。"]', '["穆天子，走龙媒，八轡冬瓏逐天迴。","五精掃地凝云开，高门左右日月环。","四方錯鏤稜層殷，舞霞垂尾长盤珊。","江澄海淨神母顏，施紅点翠照虞泉。","曳云拖玉下崑山，列斾如松，張蓋如輪。","金风殿秋，清明發春。","八鑾十乘，矗如云屯。","瓊鍾瑤席甘露文，玄霜絳雪何足云，薰梅染柳將贈君。","鉛华之水洗君骨，與君相对作真質。"]', '诗', 'shi', '', NULL, '瑤華樂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32638651-d574-455c-a0d2-07d2b0956018', '北中寒', '北中寒', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["一方黑照三方紫，黃河冰合魚龍死。","三尺木皮斷文理，百石強車上河水。","霜花草上大如錢，揮刀不入迷濛天。","爭瀯海水飛凌喧，山瀑無聲玉虹懸。"]', '["一方黑照三方紫，黄河冰合鱼龙死。","三尺木皮斷文理，百石強车上河水。","霜花草上大如錢，揮刀不入迷濛天。","爭瀯海水飞凌喧，山瀑無声玉虹懸。"]', '诗', 'shi', '', NULL, '北中寒 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff19d74e-bc9a-48e9-9f9b-ab9722df50a9', '梁臺古愁', '梁台古愁', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["梁王臺沼空中立，天河之水夜飛入。","臺前鬬玉作蛟龍，綠粉掃天愁露溼。","撞鐘飲酒行射天，金虎蹙裘噴血斑。","朝朝暮暮愁海翻，長繩繫日樂當年。","芙蓉凝紅得秋色，蘭臉別春啼脈脈。","蘆洲客雁報春來，寥落野篁秋漫白。"]', '["梁王台沼空中立，天河之水夜飞入。","台前鬬玉作蛟龙，綠粉掃天愁露溼。","撞鐘饮酒行射天，金虎蹙裘噴血斑。","朝朝暮暮愁海翻，长繩繫日乐當年。","芙蓉凝紅得秋色，蘭臉別春啼脈脈。","蘆洲客雁報春来，寥落野篁秋漫白。"]', '诗', 'shi', '', NULL, '梁臺古愁 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0db2e58b-f499-4672-a2b2-340734b67051', '公無出門', '公無出门', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["天迷迷，地密密。","熊虺食人魂，雪霜斷人骨。","嗾犬狺狺相索索，舐掌偏宜佩蘭客。","帝遣乘軒災自息，玉星點劒黃金軛。","我雖跨馬不得還，歷陽湖波大如山。","毒虬相視振金環，狻猊猰貐吐嚵涎。","鮑焦一世披草眠，顏回廿九鬢毛斑。","顏回非血衰，鮑焦不違天。","天畏遭銜齧，所以致之然。","分明猶懼公不信，公看呵壁書問天。"]', '["天迷迷，地密密。","熊虺食人魂，雪霜斷人骨。","嗾犬狺狺相索索，舐掌偏宜佩蘭客。","帝遣乘軒災自息，玉星点劒黄金軛。","我雖跨马不得還，歷陽湖波大如山。","毒虬相視振金环，狻猊猰貐吐嚵涎。","鲍焦一世披草眠，顏回廿九鬢毛斑。","顏回非血衰，鲍焦不違天。","天畏遭銜齧，所以致之然。","分明猶懼公不信，公看呵壁书问天。"]', '诗', 'shi', '', NULL, '公無出門 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d28db5a-f66d-45e8-abbc-babe8dde823c', '神弦別曲', '神弦別曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["巫山小女隔雲別，春風松花山上發。","綠蓋獨穿香徑歸，白馬花竿前孑孑。","蜀江風澹水如羅，墮蘭誰泛相經過。","南山桂樹爲君死，雲衫淺汚紅脂花。"]', '["巫山小女隔云別，春风松花山上發。","綠蓋独穿香徑归，白马花竿前孑孑。","蜀江风澹水如羅，墮蘭誰泛相經過。","南山桂樹爲君死，云衫淺汚紅脂花。"]', '诗', 'shi', '', NULL, '神弦別曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54fb0ffc-a287-41a6-b415-ebf47436548a', '綠水詞', '綠水词', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["今宵好風月，阿侯在何處。","爲有傾人色，翻成足愁苦。","東湖採蓮葉，南湖拔蒲根。","未持寄小姑，且持感愁魂。"]', '["今宵好风月，阿侯在何处。","爲有傾人色，翻成足愁苦。","东湖採蓮葉，南湖拔蒲根。","未持寄小姑，且持感愁魂。"]', '诗', 'shi', '', NULL, '綠水詞 李賀 shi');
